//==================================================================================
// INA226 Power Monitor Driver
//==================================================================================

static esp_err_t ina226_init(void)
{
    if (ina226_initialized) {
        return ESP_OK;
    }

    i2c_master_bus_handle_t i2c_bus = bsp_i2c_get_handle();
    if (i2c_bus == NULL) {
        ESP_LOGE(TAG, "I2C bus not initialized");
        return ESP_ERR_INVALID_STATE;
    }

    // Probe for INA226 at default address
    esp_err_t ret = i2c_master_probe(i2c_bus, INA226_I2C_ADDR, 100);
    if (ret != ESP_OK) {
        ESP_LOGW(TAG, "INA226 not found at address 0x%02X", INA226_I2C_ADDR);
        return ret;
    }

    // Add INA226 device to I2C bus
    i2c_device_config_t dev_cfg = {
        .dev_addr_length = I2C_ADDR_BIT_LEN_7,
        .device_address = INA226_I2C_ADDR,
        .scl_speed_hz = 100000,  // 100kHz
    };

    ret = i2c_master_bus_add_device(i2c_bus, &dev_cfg, &ina226_dev_handle);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "Failed to add INA226 device: %s", esp_err_to_name(ret));
        return ret;
    }

    // Verify manufacturer ID (should be 0x5449 for TI)
    uint8_t reg = INA226_REG_MFG_ID;
    uint8_t data[2];
    ret = i2c_master_transmit_receive(ina226_dev_handle, &reg, 1, data, 2, 100);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "Failed to read INA226 manufacturer ID: %s", esp_err_to_name(ret));
        i2c_master_bus_rm_device(ina226_dev_handle);
        ina226_dev_handle = NULL;
        return ret;
    }

        uint16_t mfg_id = (data[0] << 8) | data[1];
        ESP_LOGI(TAG, "INA226 Manufacturer ID: 0x%04X (expected 0x5449)", mfg_id);

    if (mfg_id != 0x5449) {
        ESP_LOGE(TAG, "INA226 manufacturer ID mismatch - device not responding correctly");
        i2c_master_bus_rm_device(ina226_dev_handle);
        ina226_dev_handle = NULL;
        return ESP_ERR_INVALID_RESPONSE;
    }

    // Configure INA226: AVG=16, 1100us conversion times, continuous mode
    // Using INA226_CONFIG_VALUE (0x4527) from M5Tab5 official demo
    uint8_t config_cmd[3] = {INA226_REG_CONFIG, (INA226_CONFIG_VALUE >> 8) & 0xFF, INA226_CONFIG_VALUE & 0xFF};
    ret = i2c_master_transmit(ina226_dev_handle, config_cmd, 3, 100);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "Failed to configure INA226: %s", esp_err_to_name(ret));
        i2c_master_bus_rm_device(ina226_dev_handle);
        ina226_dev_handle = NULL;
        return ret;
    }

    // Calibrate for current/power measurements
    // Cal = 0.00512 / (currentLSB * Rshunt)
    // With Rshunt=0.005 and maxI=8.192A: currentLSB = 8.192/32767 ≈ 0.00025
    // Cal = 0.00512 / (0.00025 * 0.005) = 4096 = 0x1000
    uint8_t calib_cmd[3] = {INA226_REG_CALIB, 0x10, 0x00};
    ret = i2c_master_transmit(ina226_dev_handle, calib_cmd, 3, 100);
    if (ret != ESP_OK) {
        ESP_LOGW(TAG, "Failed to calibrate INA226: %s (voltage readings will still work)", esp_err_to_name(ret));
        // Don't fail - voltage readings will still work
    }

    ina226_initialized = true;
    ESP_LOGI(TAG, "INA226 Power Monitor initialized successfully at address 0x%02X", INA226_I2C_ADDR);
    return ESP_OK;
}

static float ina226_read_bus_voltage(void)
{
    if (!ina226_initialized || ina226_dev_handle == NULL) {
        return 0.0f;
    }

    uint8_t reg = INA226_REG_BUS_VOLT;
    uint8_t data[2];

    esp_err_t ret = i2c_master_transmit_receive(ina226_dev_handle, &reg, 1, data, 2, 100);
    if (ret != ESP_OK) {
        ESP_LOGW(TAG, "Failed to read INA226 bus voltage: %s", esp_err_to_name(ret));
        return 0.0f;
    }

    // Bus voltage register is 16-bit, 1.25mV per LSB
    uint16_t raw_voltage = (data[0] << 8) | data[1];
    // Use same formula as official M5Tab5 demo: voltage * 0.00125 (V)
    float voltage_v = raw_voltage * 0.00125f;

    ESP_LOGD(TAG, "INA226 raw: 0x%04X (%u), voltage: %.3fV", raw_voltage, raw_voltage, voltage_v);

    return voltage_v;
}

static bool ina226_read_current(float *current_a)
{
    if (current_a) *current_a = 0.0f;
    if (!ina226_initialized || ina226_dev_handle == NULL || current_a == NULL) {
        return false;
    }

    uint8_t reg = INA226_REG_CURRENT;
    uint8_t data[2];

    esp_err_t ret = i2c_master_transmit_receive(ina226_dev_handle, &reg, 1, data, 2, 100);
    if (ret != ESP_OK) {
        ESP_LOGW(TAG, "Failed to read INA226 current: %s", esp_err_to_name(ret));
        return false;
    }

    int16_t raw_current = (int16_t)((data[0] << 8) | data[1]);
    *current_a = raw_current * INA226_CURRENT_LSB_A;

    ESP_LOGD(TAG, "INA226 current raw: 0x%04X (%d), current: %.3fA",
             (uint16_t)raw_current, raw_current, *current_a);

    return true;
}

//==================================================================================
// RX8130CE Real-Time Clock (I2C 0x32, shared bsp bus: P4 G32=SCL, G31=SDA)
//==================================================================================

#define RX8130_I2C_ADDR     0x32
#define RX8130_REG_SEC      0x10   // 0x10..0x16: Sec,Min,Hour,Week,Day,Month,Year (BCD)
#define RX8130_REG_FLAG     0x1D   // bit1 = VLF (voltage-low / data loss)
#define RX8130_REG_CTRL0    0x1E   // bit6 = STOP (must be 0 to run)
#define RX8130_FLAG_VLF     0x02

static i2c_master_dev_handle_t rx8130_dev_handle = NULL;
static bool rx8130_present = false;

static inline uint8_t rx8130_bcd2bin(uint8_t v) { return (uint8_t)((v >> 4) * 10 + (v & 0x0F)); }
static inline uint8_t rx8130_bin2bcd(uint8_t v) { return (uint8_t)(((v / 10) << 4) | (v % 10)); }

static esp_err_t rx8130_read_reg(uint8_t reg, uint8_t *buf, size_t len)
{
    if (!rx8130_dev_handle) return ESP_ERR_INVALID_STATE;
    return i2c_master_transmit_receive(rx8130_dev_handle, &reg, 1, buf, len, 100);
}

static esp_err_t rx8130_write_reg(uint8_t reg, const uint8_t *buf, size_t len)
{
    if (!rx8130_dev_handle) return ESP_ERR_INVALID_STATE;
    uint8_t tmp[8];
    if (len + 1 > sizeof(tmp)) return ESP_ERR_INVALID_SIZE;
    tmp[0] = reg;
    memcpy(&tmp[1], buf, len);
    return i2c_master_transmit(rx8130_dev_handle, tmp, len + 1, 100);
}

static esp_err_t rx8130_init(void)
{
    if (rx8130_dev_handle) {
        return ESP_OK;
    }

    i2c_master_bus_handle_t i2c_bus = bsp_i2c_get_handle();
    if (i2c_bus == NULL) {
        ESP_LOGE(TAG, "RX8130: I2C bus not initialized");
        return ESP_ERR_INVALID_STATE;
    }

    esp_err_t ret = i2c_master_probe(i2c_bus, RX8130_I2C_ADDR, 100);
    if (ret != ESP_OK) {
        ESP_LOGW(TAG, "RX8130CE not found at 0x%02X", RX8130_I2C_ADDR);
        return ret;
    }

    i2c_device_config_t dev_cfg = {
        .dev_addr_length = I2C_ADDR_BIT_LEN_7,
        .device_address = RX8130_I2C_ADDR,
        .scl_speed_hz = 100000,
    };
    ret = i2c_master_bus_add_device(i2c_bus, &dev_cfg, &rx8130_dev_handle);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "RX8130: failed to add device: %s", esp_err_to_name(ret));
        rx8130_dev_handle = NULL;
        return ret;
    }

    // Make sure the oscillator is running (clear STOP bit in Control 0).
    uint8_t ctrl0 = 0;
    if (rx8130_read_reg(RX8130_REG_CTRL0, &ctrl0, 1) == ESP_OK && (ctrl0 & 0x40)) {
        ctrl0 &= (uint8_t)~0x40;
        rx8130_write_reg(RX8130_REG_CTRL0, &ctrl0, 1);
    }

    rx8130_present = true;
    ESP_LOGI(TAG, "RX8130CE RTC initialized at 0x%02X", RX8130_I2C_ADDR);
    return ESP_OK;
}

// Reads the RTC into tm_out (normalized via mktime). power_lost (optional) is set
// true when the VLF flag indicates the clock lost power and time is invalid.
static esp_err_t rx8130_read_time(struct tm *tm_out, bool *power_lost)
{
    if (!tm_out) return ESP_ERR_INVALID_ARG;
    if (!rx8130_dev_handle) return ESP_ERR_INVALID_STATE;

    if (power_lost) {
        uint8_t flag = 0;
        if (rx8130_read_reg(RX8130_REG_FLAG, &flag, 1) == ESP_OK) {
            *power_lost = (flag & RX8130_FLAG_VLF) != 0;
        } else {
            *power_lost = false;
        }
    }

    uint8_t b[7];
    esp_err_t ret = rx8130_read_reg(RX8130_REG_SEC, b, sizeof(b));
    if (ret != ESP_OK) {
        return ret;
    }

    memset(tm_out, 0, sizeof(*tm_out));
    tm_out->tm_sec  = rx8130_bcd2bin(b[0] & 0x7F);
    tm_out->tm_min  = rx8130_bcd2bin(b[1] & 0x7F);
    tm_out->tm_hour = rx8130_bcd2bin(b[2] & 0x3F);
    tm_out->tm_mday = rx8130_bcd2bin(b[4] & 0x3F);
    tm_out->tm_mon  = rx8130_bcd2bin(b[5] & 0x1F) - 1;   // 0-based
    tm_out->tm_year = rx8130_bcd2bin(b[6]) + 100;        // years since 1900 (20xx)
    tm_out->tm_isdst = -1;
    mktime(tm_out);  // normalize + fill tm_wday/tm_yday
    return ESP_OK;
}

static esp_err_t rx8130_set_time(const struct tm *tm_in)
{
    if (!tm_in) return ESP_ERR_INVALID_ARG;
    if (!rx8130_dev_handle) return ESP_ERR_INVALID_STATE;

    struct tm t = *tm_in;
    t.tm_isdst = -1;
    mktime(&t);  // normalize and compute weekday

    uint8_t b[7];
    b[0] = rx8130_bin2bcd((uint8_t)t.tm_sec);
    b[1] = rx8130_bin2bcd((uint8_t)t.tm_min);
    b[2] = rx8130_bin2bcd((uint8_t)t.tm_hour);
    b[3] = (uint8_t)(1 << (t.tm_wday & 0x07));        // week = single set bit
    b[4] = rx8130_bin2bcd((uint8_t)t.tm_mday);
    b[5] = rx8130_bin2bcd((uint8_t)(t.tm_mon + 1));
    b[6] = rx8130_bin2bcd((uint8_t)((t.tm_year + 1900) % 100));

    esp_err_t ret = rx8130_write_reg(RX8130_REG_SEC, b, sizeof(b));
    if (ret != ESP_OK) {
        ESP_LOGW(TAG, "RX8130: set_time write failed: %s", esp_err_to_name(ret));
        return ret;
    }

    // Clock now holds a valid time: clear the VLF / data-loss flag.
    uint8_t flag = 0;
    if (rx8130_read_reg(RX8130_REG_FLAG, &flag, 1) == ESP_OK && (flag & RX8130_FLAG_VLF)) {
        flag &= (uint8_t)~RX8130_FLAG_VLF;
        rx8130_write_reg(RX8130_REG_FLAG, &flag, 1);
    }
    return ESP_OK;
}

// Push the current ESP system clock (UTC seconds) from the RTC.
static void rx8130_sync_system_from_rtc(void)
{
    struct tm t;
    bool power_lost = false;
    if (rx8130_read_time(&t, &power_lost) != ESP_OK) {
        return;
    }
    if (power_lost) {
        ESP_LOGW(TAG, "RX8130: VLF set - RTC lost power, not syncing system clock");
        return;
    }
    time_t epoch = mktime(&t);
    if (epoch <= 0) {
        return;
    }
    struct timeval tv = { .tv_sec = epoch, .tv_usec = 0 };
    settimeofday(&tv, NULL);
    ESP_LOGI(TAG, "System clock set from RTC: %04d-%02d-%02d %02d:%02d:%02d",
             t.tm_year + 1900, t.tm_mon + 1, t.tm_mday, t.tm_hour, t.tm_min, t.tm_sec);
}

//==================================================================================
// Battery Status Functions
//==================================================================================

static bool get_charging_status(float current_a, bool current_valid)
{
    if (!current_valid) {
        return bsp_usb_c_detect();
    }

    // Tab5's INA226 current polarity is inverted: charging reads as negative current.
    return current_a < -BATTERY_CHARGING_THRESHOLD_A;
}

static int battery_percent_from_voltage(float voltage_v)
{
    if (voltage_v <= 0.1f) return -1;

    // Tab5 pack behaves like ~2S Li-ion in practice.
    const float empty_v = 6.6f;
    const float full_v = 8.4f;
    float ratio = (voltage_v - empty_v) / (full_v - empty_v);
    if (ratio < 0.0f) ratio = 0.0f;
    if (ratio > 1.0f) ratio = 1.0f;
    return (int)(ratio * 100.0f + 0.5f);
}

// Forward declaration for USB RX arbitration flag (defined with initializer later).
static volatile bool usb_rx_exclusive;

static void format_uptime(char *out, size_t out_len)
{
    uint64_t sec = (uint64_t)(esp_timer_get_time() / 1000000LL);
    unsigned long h = (unsigned long)(sec / 3600ULL);
    unsigned long m = (unsigned long)((sec % 3600ULL) / 60ULL);
    unsigned long s = (unsigned long)(sec % 60ULL);
    snprintf(out, out_len, "%02lu:%02lu:%02lu", h, m, s);
}

static bool str_ends_with_ext(const char *s, const char *ext)
{
    if (!s || !ext) return false;
    size_t s_len = strlen(s);
    size_t ext_len = strlen(ext);
    if (s_len < ext_len) return false;
    for (size_t i = 0; i < ext_len; i++) {
        char a = (char)tolower((unsigned char)s[s_len - ext_len + i]);
        char b = (char)tolower((unsigned char)ext[i]);
        if (a != b) return false;
    }
    return true;
}

static int count_local_pcap_files(const char *dir_path)
{
    if (!dir_path) return 0;
    DIR *dir = opendir(dir_path);
    if (!dir) return 0;

    int count = 0;
    struct dirent *ent = NULL;
    while ((ent = readdir(dir)) != NULL) {
        if (ent->d_name[0] == '.') continue;
        if (str_ends_with_ext(ent->d_name, ".pcap")) {
            count++;
        }
    }
    closedir(dir);
    return count;
}

static bool file_exists(const char *path)
{
    if (!path) return false;
    struct stat st;
    return stat(path, &st) == 0;
}

static int home_collect_uart_response(tab_id_t tab, uart_port_t uart_port, char *out, size_t out_size, uint32_t timeout_ms)
{
    if (!out || out_size < 2) return 0;

    int total = 0;
    int idle_reads = 0;
    uint32_t start = lv_tick_get();
    while (lv_tick_elaps(start) < timeout_ms && total < (int)out_size - 1) {
        int len = transport_read_bytes_tab(tab, uart_port, out + total, out_size - 1 - total, pdMS_TO_TICKS(80));
        if (len > 0) {
            total += len;
            idle_reads = 0;
            continue;
        }
        if (total > 0 && ++idle_reads >= 6) {
            break;
        }
    }
    out[total] = '\0';
    return total;
}

static void home_parse_remote_list_dir(const char *buf, int *pcap_count, bool *wpasec_ok, bool *vendors_ok, bool *wigle_ok, bool *wdgwars_ok, bool *white_ok, bool *home_ok)
{
    if (!buf) return;

    char line[256];
    size_t line_pos = 0;
    for (size_t i = 0; ; i++) {
        char c = buf[i];
        if (c == '\r' || c == '\n' || c == '\0') {
            if (line_pos > 0) {
                line[line_pos] = '\0';
                if (pcap_count && strstr(line, ".pcap")) {
                    (*pcap_count)++;
                }
                if (wpasec_ok && strstr(line, "wpa-sec.txt")) {
                    *wpasec_ok = true;
                }
                if (vendors_ok && strstr(line, "oui_wifi.bin")) {
                    *vendors_ok = true;
                }
                if (wigle_ok && strstr(line, "wigle.txt")) {
                    *wigle_ok = true;
                }
                if (wdgwars_ok && strstr(line, "wdgwars.txt")) {
                    *wdgwars_ok = true;
                }
                if (white_ok && strstr(line, "white.txt")) {
                    *white_ok = true;
                }
                if (home_ok && strstr(line, "home.txt")) {
                    *home_ok = true;
                }
                line_pos = 0;
            }
            if (c == '\0') break;
            continue;
        }
        if (line_pos < sizeof(line) - 1) {
            line[line_pos++] = c;
        }
    }
}

static bool home_list_dir_success(const char *buf)
{
    if (!buf || buf[0] == '\0') return false;
    if (strstr(buf, "Files in ")) return true;
    if (strstr(buf, "Found ") && strstr(buf, "file(s)")) return true;
    return false;
}

static void home_read_local_meta(tab_context_t *ctx)
{
    if (!ctx) return;

    int pcap_count = count_local_pcap_files("/sdcard/lab/handshakes");
    if (pcap_count == 0) {
        pcap_count = count_local_pcap_files("/sdcard/handshakes");
    }
    ctx->home_handshake_count = pcap_count;
    ctx->home_wpasec_present = file_exists("/sdcard/lab/wpa-sec.txt") || file_exists("/sdcard/wpa-sec.txt");
    ctx->home_vendors_present = file_exists("/sdcard/lab/oui_wifi.bin") ||
                                file_exists("/sdcard/lab/vendors/oui_wifi.bin") ||
                                file_exists("/sdcard/oui_wifi.bin");
    ctx->home_wigle_present   = file_exists("/sdcard/lab/wigle.txt");
    ctx->home_wdgwars_present = file_exists("/sdcard/lab/wdgwars.txt");
    ctx->home_white_present   = file_exists("/sdcard/lab/white.txt");
    ctx->home_homenet_present = file_exists("/sdcard/lab/home.txt");

    uint64_t total = 0;
    uint64_t free = 0;
    if (esp_vfs_fat_info("/sdcard", &total, &free) == ESP_OK && total > 0) {
        ctx->home_sd_total_bytes = total;
        ctx->home_sd_free_bytes = free;
        ctx->home_sd_stats_valid = true;
    } else {
        ctx->home_sd_total_bytes = 0;
        ctx->home_sd_free_bytes = 0;
        ctx->home_sd_stats_valid = false;
    }
}

static void home_read_remote_meta(tab_context_t *ctx)
{
    if (!ctx) return;

    tab_id_t tab = tab_id_for_ctx(ctx);
    uart_port_t uart_port = uart_port_for_tab(tab);
    char rx_buf[2048];
    int pcap_count = 0;
    bool wpasec_ok = false;
    bool vendors_ok = false;
    bool wigle_ok = false;
    bool wdgwars_ok = false;
    bool white_ok = false;
    bool home_ok = false;
    bool usb_lock_set = false;

    if (tab == TAB_INTERNAL) {
        home_read_local_meta(ctx);
        return;
    }

    if (tab == TAB_USB) {
        usb_rx_exclusive = true;
        usb_lock_set = true;
        usb_flush_input(180);
    } else {
        uart_flush_input(uart_port);
    }

    const char *hs_paths[] = { "/sdcard/lab/handshakes", "/lab/handshakes" };
    for (size_t i = 0; i < sizeof(hs_paths) / sizeof(hs_paths[0]); i++) {
        if (tab == TAB_USB) usb_flush_input(50);
        else uart_flush_input(uart_port);
        char cmd[96];
        snprintf(cmd, sizeof(cmd), "list_dir %s", hs_paths[i]);
        transport_write_bytes_tab(tab, uart_port, cmd, strlen(cmd));
        transport_write_bytes_tab(tab, uart_port, "\r\n", 2);
        if (home_collect_uart_response(tab, uart_port, rx_buf, sizeof(rx_buf), 1600) > 0) {
            home_parse_remote_list_dir(rx_buf, &pcap_count, NULL, NULL, NULL, NULL, NULL, NULL);
            if (home_list_dir_success(rx_buf)) break;
        }
    }

    if (tab == TAB_USB) {
        usb_flush_input(100);
    } else {
        uart_flush_input(uart_port);
    }

    const char *lab_paths[] = { "/sdcard/lab", "/lab" };
    for (size_t i = 0; i < sizeof(lab_paths) / sizeof(lab_paths[0]); i++) {
        if (tab == TAB_USB) usb_flush_input(50);
        else uart_flush_input(uart_port);
        char cmd[80];
        snprintf(cmd, sizeof(cmd), "list_dir %s", lab_paths[i]);
        transport_write_bytes_tab(tab, uart_port, cmd, strlen(cmd));
        transport_write_bytes_tab(tab, uart_port, "\r\n", 2);
        if (home_collect_uart_response(tab, uart_port, rx_buf, sizeof(rx_buf), 1400) > 0) {
            home_parse_remote_list_dir(rx_buf, NULL, &wpasec_ok, &vendors_ok, &wigle_ok, &wdgwars_ok, &white_ok, &home_ok);
            if (home_list_dir_success(rx_buf)) break;
        }
    }

    if (!vendors_ok) {
        const char *vendor_paths[] = { "/sdcard/lab/vendors", "/lab/vendors" };
        for (size_t i = 0; i < sizeof(vendor_paths) / sizeof(vendor_paths[0]); i++) {
            if (tab == TAB_USB) usb_flush_input(50);
            else uart_flush_input(uart_port);
            char cmd[96];
            snprintf(cmd, sizeof(cmd), "list_dir %s", vendor_paths[i]);
            transport_write_bytes_tab(tab, uart_port, cmd, strlen(cmd));
            transport_write_bytes_tab(tab, uart_port, "\r\n", 2);
            if (home_collect_uart_response(tab, uart_port, rx_buf, sizeof(rx_buf), 1200) > 0) {
                home_parse_remote_list_dir(rx_buf, NULL, NULL, &vendors_ok, NULL, NULL, NULL, NULL);
                if (vendors_ok) break;
            }
        }
    }

    if (usb_lock_set) {
        usb_rx_exclusive = false;
    }

    ctx->home_handshake_count = pcap_count;
    ctx->home_wpasec_present  = wpasec_ok;
    ctx->home_vendors_present = vendors_ok;
    ctx->home_wigle_present   = wigle_ok;
    ctx->home_wdgwars_present = wdgwars_ok;
    ctx->home_white_present   = white_ok;
    ctx->home_homenet_present = home_ok;

    // Storage ring tracks Tab5 SD free space (always local mount on this UI device).
    uint64_t total = 0;
    uint64_t free = 0;
    if (esp_vfs_fat_info("/sdcard", &total, &free) == ESP_OK && total > 0) {
        ctx->home_sd_total_bytes = total;
        ctx->home_sd_free_bytes = free;
        ctx->home_sd_stats_valid = true;
    } else {
        ctx->home_sd_stats_valid = false;
        ctx->home_sd_total_bytes = 0;
        ctx->home_sd_free_bytes = 0;
    }
}

static bool home_meta_refresh_allowed(const tab_context_t *ctx)
{
    if (!ctx) return false;
    if (!ctx->tiles || ctx->current_visible_page != ctx->tiles) return false;
    if (ctx->scan_in_progress) return false;
    if (ctx->observer_running || ctx->deauth_detector_running) return false;
    if (ctx->handshaker_monitoring || ctx->global_handshaker_monitoring) return false;
    if (ctx->wardrive_monitoring || ctx->phishing_portal_monitoring) return false;
    return true;
}

static void trigger_home_meta_refresh(tab_context_t *ctx, bool force)
{
    if (!ctx || !dashboard_enabled) return;
    if (!ctx->sd_card_present) return;
    if (ctx->home_meta_refresh_running) return;
    if (!home_meta_refresh_allowed(ctx)) return;
    if (tab_id_for_ctx(ctx) != current_tab) return;

    if (!force && ctx->home_meta_last_update_ms != 0 &&
        lv_tick_elaps(ctx->home_meta_last_update_ms) < 12000) {
        return;
    }

    ctx->home_meta_refresh_running = true;
    if (xTaskCreate(home_meta_refresh_task, "home_meta", 6144, ctx, 4, &ctx->home_meta_task) != pdTRUE) {
        ctx->home_meta_refresh_running = false;
        ctx->home_meta_task = NULL;
        ESP_LOGW(TAG, "Failed to create home metadata refresh task");
    }
}

static void home_meta_refresh_task(void *arg)
{
    tab_context_t *ctx = (tab_context_t *)arg;
    if (!ctx) {
        vTaskDelete(NULL);
        return;
    }

    if (tab_id_for_ctx(ctx) == TAB_INTERNAL) {
        home_read_local_meta(ctx);
    } else {
        home_read_remote_meta(ctx);
    }
    ctx->home_meta_last_update_ms = lv_tick_get();
    ctx->home_meta_refresh_running = false;
    ctx->home_meta_task = NULL;

    int battery_pct = battery_percent_from_voltage(current_battery_voltage);
    bsp_display_lock(0);
    update_home_dashboard_labels(ctx, battery_pct);
    bsp_display_unlock();
    vTaskDelete(NULL);
}

static void format_short_coord(double coord, char *out, size_t out_len)
{
    if (!out || out_len == 0) return;
    snprintf(out, out_len, "%.4f", coord);
}

static void update_home_dashboard_labels(tab_context_t *ctx, int battery_pct)
{
    if (!ctx || !dashboard_enabled) return;

    if (ctx->home_last_net_label) {
        if (ctx->network_count > 0 && ctx->networks) {
            int best_idx = 0;
            int best_rssi = ctx->networks[0].rssi;
            for (int i = 1; i < ctx->network_count; i++) {
                if (ctx->networks[i].rssi > best_rssi) {
                    best_rssi = ctx->networks[i].rssi;
                    best_idx = i;
                }
            }
            const char *ssid = ctx->networks[best_idx].ssid;
            if (!ssid || ssid[0] == '\0') ssid = "(hidden)";
            char net_buf[72];
            snprintf(net_buf, sizeof(net_buf), "%s\n%d dBm", ssid, best_rssi);
            lv_label_set_text(ctx->home_last_net_label, net_buf);
        } else {
            lv_label_set_text(ctx->home_last_net_label, "No scan data");
        }
    }

    if (ctx->home_gps_label) {
        double lat = 0.0;
        double lon = 0.0;
        bool has_fix = usb_gps_get_fix(&lat, &lon, 0);

        if (!has_fix && ctx->wardrive_gps_fix && ctx->wardrive_net_count > 0) {
            int idx = ctx->wardrive_net_head - 1;
            if (idx < 0) idx = WARDRIVE_MAX_NETWORKS - 1;
            const char *lat_str = ctx->wardrive_networks[idx].lat;
            const char *lon_str = ctx->wardrive_networks[idx].lon;
            if (lat_str && lon_str && lat_str[0] != '\0' && lon_str[0] != '\0') {
                lat = strtod(lat_str, NULL);
                lon = strtod(lon_str, NULL);
                has_fix = true;
            }
        }

        if (has_fix) {
            lv_label_set_text(ctx->home_gps_label, "FIX");
            lv_obj_set_style_text_color(ctx->home_gps_label, COLOR_MATERIAL_GREEN, 0);
            if (ctx->home_gps_detail_label) {
                char lat_buf[20];
                char lon_buf[20];
                char gps_buf[48];
                format_short_coord(lat, lat_buf, sizeof(lat_buf));
                format_short_coord(lon, lon_buf, sizeof(lon_buf));
                snprintf(gps_buf, sizeof(gps_buf), "%s, %s", lat_buf, lon_buf);
                lv_label_set_text(ctx->home_gps_detail_label, gps_buf);
            }
        } else {
            lv_label_set_text(ctx->home_gps_label, "NO FIX");
            lv_obj_set_style_text_color(ctx->home_gps_label, COLOR_MATERIAL_RED, 0);
            if (ctx->home_gps_detail_label) {
                lv_label_set_text(ctx->home_gps_detail_label, "");
            }
        }
    }

    if (ctx->home_battery_label) {
        char battery_buf[32];
        if (current_battery_voltage > 0.1f && battery_pct >= 0) {
            unsigned pct_display = (unsigned)battery_pct;
            if (pct_display > 100U) pct_display = 100U;
            snprintf(battery_buf, sizeof(battery_buf), "%.2fV %u%%",
                     current_battery_voltage, pct_display);
        } else {
            snprintf(battery_buf, sizeof(battery_buf), "--.--V --%%");
        }
        lv_label_set_text(ctx->home_battery_label, battery_buf);
    }

    if (ctx->home_handshakes_label) {
        if (!ctx->sd_card_present) {
            lv_label_set_text(ctx->home_handshakes_label, "NO SD");
            lv_obj_set_style_text_color(ctx->home_handshakes_label, COLOR_MATERIAL_RED, 0);
        } else {
            char hs_buf[24];
            snprintf(hs_buf, sizeof(hs_buf), "%d pcap", ctx->home_handshake_count);
            lv_label_set_text(ctx->home_handshakes_label, hs_buf);
            lv_obj_set_style_text_color(ctx->home_handshakes_label, ui_text_color(), 0);
        }
    }
    if (ctx->home_handshakes_detail_label) {
        lv_label_set_text(ctx->home_handshakes_detail_label, "");
    }

    if (ctx->home_uptime_label) {
        char uptime_buf[20];
        format_uptime(uptime_buf, sizeof(uptime_buf));
        lv_label_set_text(ctx->home_uptime_label, uptime_buf);
    }

    if (ctx->home_storage_percent_label) {
        if (!internal_sd_present) {
            lv_label_set_text(ctx->home_storage_percent_label, "NO SD");
            if (ctx->home_storage_detail_label) lv_label_set_text(ctx->home_storage_detail_label, "card missing");
            if (ctx->home_storage_arc) lv_arc_set_value(ctx->home_storage_arc, 0);
        } else if (ctx->home_sd_stats_valid && ctx->home_sd_total_bytes > 0) {
            uint32_t pct = (uint32_t)((ctx->home_sd_free_bytes * 100ULL) / ctx->home_sd_total_bytes);
            if (pct > 100U) pct = 100U;
            char pct_buf[20];
            char detail_buf[64];
            double free_gb = (double)ctx->home_sd_free_bytes / (1024.0 * 1024.0 * 1024.0);
            double total_gb = (double)ctx->home_sd_total_bytes / (1024.0 * 1024.0 * 1024.0);
            snprintf(pct_buf, sizeof(pct_buf), "%u%% FREE", (unsigned)pct);
            snprintf(detail_buf, sizeof(detail_buf), "%.1f/%.1fGB free", free_gb, total_gb);
            lv_label_set_text(ctx->home_storage_percent_label, pct_buf);
            if (ctx->home_storage_detail_label) lv_label_set_text(ctx->home_storage_detail_label, detail_buf);
            if (ctx->home_storage_arc) lv_arc_set_value(ctx->home_storage_arc, (int)pct);
        } else {
            lv_label_set_text(ctx->home_storage_percent_label, "SD READY");
            if (ctx->home_storage_detail_label) lv_label_set_text(ctx->home_storage_detail_label, "stats unavailable");
            if (ctx->home_storage_arc) lv_arc_set_value(ctx->home_storage_arc, 0);
        }
    } else if (ctx->home_storage_label) {
        lv_label_set_text(ctx->home_storage_label, internal_sd_present ? "Mounted\nready" : "No SD card");
    }

    bool files_loaded = (ctx->home_meta_last_update_ms != 0);
    if (ctx->home_files_spinner) {
        if (files_loaded) {
            lv_obj_add_flag(ctx->home_files_spinner, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_clear_flag(ctx->home_files_spinner, LV_OBJ_FLAG_HIDDEN);
        }
    }
    if (ctx->home_files_row) {
        if (files_loaded) {
            lv_obj_clear_flag(ctx->home_files_row, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(ctx->home_files_row, LV_OBJ_FLAG_HIDDEN);
        }
    }

    if (ctx->home_files_label && files_loaded) {
        if (!ctx->sd_card_present) {
            lv_label_set_text(ctx->home_files_label, "wpa-sec: " LV_SYMBOL_CLOSE);
            lv_obj_set_style_text_color(ctx->home_files_label, COLOR_MATERIAL_RED, 0);
            if (ctx->home_files_detail_label) {
                lv_label_set_text(ctx->home_files_detail_label, "vendors: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_detail_label, COLOR_MATERIAL_RED, 0);
            }
            if (ctx->home_files_white_label) {
                lv_label_set_text(ctx->home_files_white_label, "white: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_white_label, COLOR_MATERIAL_RED, 0);
            }
            if (ctx->home_files_wigle_label) {
                lv_label_set_text(ctx->home_files_wigle_label, "wigle: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_wigle_label, COLOR_MATERIAL_RED, 0);
            }
            if (ctx->home_files_wdgwars_label) {
                lv_label_set_text(ctx->home_files_wdgwars_label, "wdgwars: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_wdgwars_label, COLOR_MATERIAL_RED, 0);
            }
            if (ctx->home_files_home_label) {
                lv_label_set_text(ctx->home_files_home_label, "home: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_home_label, COLOR_MATERIAL_RED, 0);
            }
        } else {
            lv_label_set_text(ctx->home_files_label,
                              ctx->home_wpasec_present ? "wpa-sec: " LV_SYMBOL_OK : "wpa-sec: " LV_SYMBOL_CLOSE);
            lv_obj_set_style_text_color(ctx->home_files_label,
                                        ctx->home_wpasec_present ? COLOR_MATERIAL_GREEN : COLOR_MATERIAL_RED, 0);
            if (ctx->home_files_detail_label) {
                lv_label_set_text(ctx->home_files_detail_label,
                                  ctx->home_vendors_present ? "vendors: " LV_SYMBOL_OK : "vendors: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_detail_label,
                                            ctx->home_vendors_present ? COLOR_MATERIAL_GREEN : COLOR_MATERIAL_RED, 0);
            }
            if (ctx->home_files_white_label) {
                lv_label_set_text(ctx->home_files_white_label,
                                  ctx->home_white_present ? "white: " LV_SYMBOL_OK : "white: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_white_label,
                                            ctx->home_white_present ? COLOR_MATERIAL_GREEN : COLOR_MATERIAL_RED, 0);
            }
            if (ctx->home_files_wigle_label) {
                lv_label_set_text(ctx->home_files_wigle_label,
                                  ctx->home_wigle_present ? "wigle: " LV_SYMBOL_OK : "wigle: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_wigle_label,
                                            ctx->home_wigle_present ? COLOR_MATERIAL_GREEN : COLOR_MATERIAL_RED, 0);
            }
            if (ctx->home_files_wdgwars_label) {
                lv_label_set_text(ctx->home_files_wdgwars_label,
                                  ctx->home_wdgwars_present ? "wdgwars: " LV_SYMBOL_OK : "wdgwars: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_wdgwars_label,
                                            ctx->home_wdgwars_present ? COLOR_MATERIAL_GREEN : COLOR_MATERIAL_RED, 0);
            }
            if (ctx->home_files_home_label) {
                lv_label_set_text(ctx->home_files_home_label,
                                  ctx->home_homenet_present ? "home: " LV_SYMBOL_OK : "home: " LV_SYMBOL_CLOSE);
                lv_obj_set_style_text_color(ctx->home_files_home_label,
                                            ctx->home_homenet_present ? COLOR_MATERIAL_GREEN : COLOR_MATERIAL_RED, 0);
            }
        }
    } else if (ctx->home_files_detail_label) {
        lv_label_set_text(ctx->home_files_detail_label, "");
    }

    trigger_home_meta_refresh(ctx, false);
}

static uint32_t home_quote_rand_u32(void)
{
    if (home_quote_rng == 0) {
        home_quote_rng = lv_tick_get() ^ 0xA5A55A5Au;
        if (home_quote_rng == 0) home_quote_rng = 0x6D2B79F5u;
    }
    home_quote_rng ^= home_quote_rng << 13;
    home_quote_rng ^= home_quote_rng >> 17;
    home_quote_rng ^= home_quote_rng << 5;
    if (home_quote_rng == 0) home_quote_rng = 0x6D2B79F5u;
    return home_quote_rng;
}

static uint32_t home_quote_next_period_ms(void)
{
    // Readable pace with slight irregularity: ~6.2s to ~11.2s
    uint32_t period = 6200u + (home_quote_rand_u32() % 3200u);
    if ((home_quote_rand_u32() % 4u) == 0u) {
        period += 1800u;
    }
    return period;
}

static const char *home_quote_select_next(void)
{
    if (HOME_FOOTER_QUOTE_COUNT == 0) return "";
    if (home_quote_index < 0) {
        home_quote_index = (int)(home_quote_rand_u32() % HOME_FOOTER_QUOTE_COUNT);
    } else {
        int step = ((home_quote_rand_u32() % 5u) == 0u) ? 2 : 1;
        home_quote_index = (home_quote_index + step) % (int)HOME_FOOTER_QUOTE_COUNT;
    }
    return home_footer_quotes[home_quote_index];
}

static void home_quote_apply_to_all(const char *quote)
{
    tab_context_t *ctx_list[] = { &grove_ctx, &usb_ctx, &mbus_ctx };
    for (size_t i = 0; i < sizeof(ctx_list) / sizeof(ctx_list[0]); i++) {
        tab_context_t *ctx = ctx_list[i];
        if (ctx && ctx->home_quote_label) {
            lv_label_set_text(ctx->home_quote_label, quote);
        }
    }
}

static void home_quote_sync_to_ctx(tab_context_t *ctx)
{
    if (!ctx || !ctx->home_quote_label || HOME_FOOTER_QUOTE_COUNT == 0) return;
    if (home_quote_index < 0) {
        home_quote_index = (int)(home_quote_rand_u32() % HOME_FOOTER_QUOTE_COUNT);
    }
    lv_label_set_text(ctx->home_quote_label, home_footer_quotes[home_quote_index]);
}

static void home_quote_timer_cb(lv_timer_t *timer)
{
    if (!timer) return;

    if (!dashboard_enabled) {
        lv_timer_set_period(timer, 9000);
        return;
    }

    tab_context_t *ctx = get_current_ctx();
    if (!ctx || !ctx->home_quote_label || !ctx->tiles || ctx->current_visible_page != ctx->tiles) {
        lv_timer_set_period(timer, home_quote_next_period_ms());
        return;
    }

    home_quote_apply_to_all(home_quote_select_next());
    lv_timer_set_period(timer, home_quote_next_period_ms());
}

static void home_quote_start(void)
{
    if (home_quote_timer == NULL) {
        home_quote_timer = lv_timer_create(home_quote_timer_cb, home_quote_next_period_ms(), NULL);
    }
}

// Refresh the status-bar clock from the system clock (seeded from the RTC).
static void update_status_clock(void)
{
    if (!status_clock_label) {
        return;
    }
    if (!clock_show) {
        lv_obj_add_flag(status_clock_label, LV_OBJ_FLAG_HIDDEN);
        return;
    }
    lv_obj_clear_flag(status_clock_label, LV_OBJ_FLAG_HIDDEN);
    time_t now = time(NULL);
    struct tm t;
    localtime_r(&now, &t);

    // Skip showing a clock until the time looks real (year >= 2024).
    if (t.tm_year + 1900 < 2024) {
        lv_label_set_text(status_clock_label, "--:--");
        return;
    }

    char buf[8];
    if (clock_24h) {
        snprintf(buf, sizeof(buf), "%02d:%02d", t.tm_hour, t.tm_min);
    } else {
        int h12 = t.tm_hour % 12;
        if (h12 == 0) h12 = 12;
        snprintf(buf, sizeof(buf), "%02d:%02d", h12, t.tm_min);
    }
    lv_label_set_text(status_clock_label, buf);
}

static void update_battery_status(void)
{
    current_battery_voltage = ina226_read_bus_voltage();
    current_battery_current_valid = ina226_read_current(&current_battery_current_a);
    current_charging_status = get_charging_status(current_battery_current_a, current_battery_current_valid);
}

static void battery_status_timer_cb(lv_timer_t *timer)
{
    (void)timer;

    // Read new values
    update_battery_status();

    // Memory stats
    size_t psram_free = heap_caps_get_free_size(MALLOC_CAP_SPIRAM);
    size_t psram_min = heap_caps_get_minimum_free_size(MALLOC_CAP_SPIRAM);
    size_t sram_free = heap_caps_get_free_size(MALLOC_CAP_INTERNAL);
    size_t sram_min = heap_caps_get_minimum_free_size(MALLOC_CAP_INTERNAL);
    size_t dma_free = heap_caps_get_free_size(MALLOC_CAP_DMA);
    size_t dma_min = heap_caps_get_minimum_free_size(MALLOC_CAP_DMA);

    // Memory stats only (no battery log to reduce noise)
    ESP_LOGD(TAG, "Memory - PSRAM: %u KB free (min: %u KB) | SRAM: %u KB free (min: %u KB) | DMA: %u KB free (min: %u KB)",
             (unsigned)(psram_free / 1024), (unsigned)(psram_min / 1024),
             (unsigned)(sram_free / 1024), (unsigned)(sram_min / 1024),
             (unsigned)(dma_free / 1024), (unsigned)(dma_min / 1024));

    int battery_pct = battery_percent_from_voltage(current_battery_voltage);

    update_status_clock();

    // Update top bar labels
    if (battery_voltage_label) {
        if (current_battery_voltage > 0.1f && battery_pct >= 0) {
            unsigned pct_display = (unsigned)battery_pct;
            if (pct_display > 100U) pct_display = 100U;
            char top_batt_str[24];
            snprintf(top_batt_str, sizeof(top_batt_str), "%.2fV %u%%",
                     current_battery_voltage, pct_display);
            lv_label_set_text(battery_voltage_label, top_batt_str);
        } else {
            lv_label_set_text(battery_voltage_label, "--.--V --%");
        }
        lv_obj_set_style_text_color(battery_voltage_label,
                                    (battery_pct >= 0 && battery_pct < 15) ? COLOR_MATERIAL_RED : ui_text_color(), 0);
    }

    if (charging_status_label) {
        if (current_charging_status) {
            lv_obj_set_width(charging_status_label, charging_status_slot_width);
            lv_label_set_text(charging_status_label, LV_SYMBOL_CHARGE);
            lv_obj_set_style_text_color(charging_status_label, COLOR_NEON_GREEN, 0);
        } else {
            lv_label_set_text(charging_status_label, "");
            lv_obj_set_width(charging_status_label, 0);
            lv_obj_set_style_text_color(charging_status_label, ui_muted_color(), 0);
        }
    }

    update_home_dashboard_labels(&grove_ctx, battery_pct);
    update_home_dashboard_labels(&usb_ctx, battery_pct);
    update_home_dashboard_labels(&mbus_ctx, battery_pct);
    update_home_dashboard_labels(&internal_ctx, battery_pct);
}

// Get screen timeout in milliseconds based on setting
static uint32_t get_screen_timeout_ms(void)
{
    switch (screen_timeout_setting) {
        case 0: return 10000;      // 10s
        case 1: return 30000;      // 30s
        case 2: return 60000;      // 1min
        case 3: return 300000;     // 5min
        case 4: return UINT32_MAX; // Stays On (effectively never)
        default: break;
    }
    return 30000;  // Default fallback
}

// Set display brightness with gamma correction using full 12-bit LEDC precision.
// Direct LEDC control gives 4096 steps (0-4095) with 200Hz PWM for proper LED dimming.
// Gamma 2.2 maps slider percentage to perceived linear brightness.
#define BRIGHTNESS_LEDC_CH      LEDC_CHANNEL_1
#define BRIGHTNESS_LEDC_MAX     4095  // 12-bit resolution
static void set_brightness_gamma(uint8_t percent)
{
    uint32_t duty;
    if (percent == 0) {
        duty = 0;
    } else if (percent >= 100) {
        duty = BRIGHTNESS_LEDC_MAX;
    } else {
        float normalized = percent / 100.0f;
        float corrected = powf(normalized, 2.2f);
        duty = (uint32_t)(corrected * BRIGHTNESS_LEDC_MAX + 0.5f);
        if (duty < 1) duty = 1;
    }
    ESP_LOGI(TAG, "Brightness: slider %d%% -> duty %lu/4095", percent, (unsigned long)duty);
    ledc_set_duty(LEDC_LOW_SPEED_MODE, BRIGHTNESS_LEDC_CH, duty);
    ledc_update_duty(LEDC_LOW_SPEED_MODE, BRIGHTNESS_LEDC_CH);
}

// Wake screen helper - restores brightness and clears dimmed state
static void wake_screen(const char *source)
{
    if (sleep_overlay) {
        lv_obj_delete(sleep_overlay);
        sleep_overlay = NULL;
    }

    set_brightness_gamma(screen_brightness_setting);  // Restore brightness with gamma correction
    screen_dimmed = false;
    last_activity_time = lv_tick_get();
    ESP_LOGI(TAG, "Screen woken by %s (brightness %d%%)", source, screen_brightness_setting);
}

// Sleep overlay click callback - wakes screen and removes overlay (GT911 only)
static void sleep_overlay_click_cb(lv_event_t *e)
{
    (void)e;
    wake_screen("touch");
}

// Screen timeout timer callback - dims screen after inactivity and handles wake
static void screen_timeout_timer_cb(lv_timer_t *timer)
{
    (void)timer;

    // If screen is dimmed, touch overlay handles wake via sleep_overlay_click_cb
    if (screen_dimmed) {
        return;
    }

    uint32_t now = lv_tick_get();
    uint32_t timeout_ms = get_screen_timeout_ms();
    if (timeout_ms != UINT32_MAX && (now - last_activity_time) >= timeout_ms) {
        bsp_display_brightness_set(0);  // Turn off backlight
        screen_dimmed = true;

        // Auto-lock: engage the lock now (before the wake overlay) so it stays in
        // place underneath and the user must slide to unlock after waking.
        if (screen_auto_lock_enabled) {
            lock_screen_activate();
        }

        // Create invisible overlay to capture wake touch
        sleep_overlay = lv_obj_create(lv_layer_top());
        lv_obj_remove_style_all(sleep_overlay);
        lv_obj_set_size(sleep_overlay, LV_PCT(100), LV_PCT(100));
        lv_obj_set_style_bg_opa(sleep_overlay, LV_OPA_TRANSP, 0);
        lv_obj_add_flag(sleep_overlay, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_event_cb(sleep_overlay, sleep_overlay_click_cb, LV_EVENT_CLICKED, NULL);

        ESP_LOGI(TAG, "Screen dimmed (touch to wake)");
    }
}

// Touch activity callback - resets inactivity timer on any touch
static void touch_activity_cb(lv_event_t *e)
{
    (void)e;

    // Only update activity time if screen is not dimmed
    // (when dimmed, the overlay handles everything)
    if (!screen_dimmed) {
        last_activity_time = lv_tick_get();
    }
}

// Slider drag callback: unlock once dragged (almost) all the way across.
static void lock_slider_value_cb(lv_event_t *e)
{
    lv_obj_t *slider = lv_event_get_target(e);
    if (lv_slider_get_value(slider) >= 95) {
        if (lock_overlay) {
            lv_obj_del(lock_overlay);
            lock_overlay = NULL;
        }
        last_activity_time = lv_tick_get();
        ESP_LOGI(TAG, "Screen unlocked");
    }
}

// Slider release callback: snap back to the start if not dragged far enough.
static void lock_slider_release_cb(lv_event_t *e)
{
    lv_obj_t *slider = lv_event_get_target(e);
    if (lv_slider_get_value(slider) < 95) {
        lv_slider_set_value(slider, 0, LV_ANIM_ON);
    }
}

// Engage the lock: a full-screen overlay that swallows all touches except the
// "slide to unlock" slider. Lives on lv_layer_top() so it covers every tab.
static void lock_screen_activate(void)
{
    if (lock_overlay) return;

    lock_overlay = lv_obj_create(lv_layer_top());
    lv_obj_remove_style_all(lock_overlay);
    lv_obj_set_size(lock_overlay, LV_PCT(100), LV_PCT(100));
    lv_obj_set_style_bg_color(lock_overlay, ui_bg_color(), 0);
    lv_obj_set_style_bg_opa(lock_overlay, LV_OPA_80, 0);
    lv_obj_add_flag(lock_overlay, LV_OBJ_FLAG_CLICKABLE);  // Swallow taps to the UI below
    lv_obj_clear_flag(lock_overlay, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *hint = lv_label_create(lock_overlay);
    lv_label_set_text(hint, LV_SYMBOL_RIGHT "  Slide to unlock");
    lv_obj_set_style_text_font(hint, &lv_font_montserrat_24, 0);
    lv_obj_set_style_text_color(hint, COLOR_LAB5_MAGENTA, 0);
    lv_obj_align(hint, LV_ALIGN_CENTER, 0, -60);

    lv_obj_t *slider = lv_slider_create(lock_overlay);
    lv_slider_set_range(slider, 0, 100);
    lv_slider_set_value(slider, 0, LV_ANIM_OFF);
    lv_obj_set_size(slider, LV_PCT(70), 56);
    lv_obj_align(slider, LV_ALIGN_CENTER, 0, 20);
    lv_obj_set_style_bg_color(slider, ui_card_color(), LV_PART_MAIN);
    lv_obj_set_style_bg_color(slider, COLOR_LAB5_MAGENTA, LV_PART_INDICATOR);
    lv_obj_set_style_bg_color(slider, COLOR_LAB5_MAGENTA, LV_PART_KNOB);
    lv_obj_set_style_pad_all(slider, 6, LV_PART_KNOB);
    lv_obj_set_style_radius(slider, LV_RADIUS_CIRCLE, LV_PART_MAIN);
    lv_obj_add_event_cb(slider, lock_slider_value_cb, LV_EVENT_VALUE_CHANGED, NULL);
    lv_obj_add_event_cb(slider, lock_slider_release_cb, LV_EVENT_RELEASED, NULL);
    lv_obj_add_event_cb(slider, lock_slider_release_cb, LV_EVENT_PRESS_LOST, NULL);

    ESP_LOGI(TAG, "Screen locked");
}

// Status-bar lock button callback.
static void lock_status_btn_cb(lv_event_t *e)
{
    (void)e;
    lock_screen_activate();
}

static bool usb_transport_ready = false;
static bool usb_transport_warned = false;
static usbh_cdc_handle_t usb_cdc_handle = NULL;
static bool usb_cdc_connected = false;
static bool usb_host_checked = false;
static bool usb_host_installed = false;
static bool usb_host_started_by_us = false;
static uint32_t usb_next_retry_ms = 0;
static bool usb_log_tuned = false;
static bool board_redetect_pending = false;
static bool usb_debug_logs = true;
static bool usb_cdc_preferred_valid = false;
static uint8_t usb_cdc_preferred_itf = 0;
static uint16_t usb_last_vid = 0;
static uint16_t usb_last_pid = 0;
static bool usb_gps_fix_valid = false;
static double usb_gps_last_lat = 0.0;
static double usb_gps_last_lon = 0.0;
static uint32_t usb_gps_fix_tick = 0;
static char usb_gps_line_buffer[160];
static size_t usb_gps_line_len = 0;
static bool usb_nmea_device_seen = false;
static bool usb_is_known_gps = false;
static TaskHandle_t usb_gps_drain_task_handle = NULL;
static volatile bool usb_rx_exclusive = false;

#define USB_GPS_FIX_MAX_AGE_MS 15000
#define USB_GPS_KNOWN_VID 0x1546
#define USB_GPS_KNOWN_PID 0x01A7

#define CP210X_VID 0x10C4
#define CP210X_REQTYPE_HOST_TO_DEVICE 0x41
#define CP210X_IFC_ENABLE 0x00
#define CP210X_SET_LINE_CTL 0x03
#define CP210X_SET_MHS 0x07
#define CP210X_SET_BAUDRATE 0x1E

#define CP210X_UART_ENABLE 0x0001

#define CP210X_BITS_DATA_8 0x0800
#define CP210X_BITS_PARITY_NONE 0x0000
#define CP210X_BITS_STOP_1 0x0000

#define CP210X_CONTROL_DTR 0x0001
#define CP210X_CONTROL_RTS 0x0002
#define CP210X_CONTROL_WRITE_DTR 0x0100
#define CP210X_CONTROL_WRITE_RTS 0x0200

static void cp210x_send_simple_request(uint8_t request, uint16_t value, uint16_t index)
{
    if (!usb_cdc_handle) {
        return;
    }
    esp_err_t err = usbh_cdc_send_custom_request(usb_cdc_handle,
                                                 CP210X_REQTYPE_HOST_TO_DEVICE,
                                                 request,
                                                 value,
                                                 index,
                                                 0,
                                                 NULL);
    if (usb_debug_logs && err != ESP_OK) {
        ESP_LOGW(TAG, "[USB][CP210X] request 0x%02X failed: %s", request, esp_err_to_name(err));
    }
}

static void cp210x_send_baudrate(uint32_t baud, uint16_t index)
{
    if (!usb_cdc_handle) {
        return;
    }
    uint8_t data[4];
    data[0] = (uint8_t)(baud & 0xFF);
    data[1] = (uint8_t)((baud >> 8) & 0xFF);
    data[2] = (uint8_t)((baud >> 16) & 0xFF);
    data[3] = (uint8_t)((baud >> 24) & 0xFF);
    esp_err_t err = usbh_cdc_send_custom_request(usb_cdc_handle,
                                                 CP210X_REQTYPE_HOST_TO_DEVICE,
                                                 CP210X_SET_BAUDRATE,
                                                 0,
                                                 index,
                                                 sizeof(data),
                                                 data);
    if (usb_debug_logs && err != ESP_OK) {
        ESP_LOGW(TAG, "[USB][CP210X] SET_BAUDRATE failed: %s", esp_err_to_name(err));
    }
}

static void cp210x_init_port(uint16_t index)
{
    uint16_t line_ctl = CP210X_BITS_DATA_8 | CP210X_BITS_PARITY_NONE | CP210X_BITS_STOP_1;
    uint16_t mhs = CP210X_CONTROL_WRITE_DTR | CP210X_CONTROL_WRITE_RTS |
                   CP210X_CONTROL_DTR | CP210X_CONTROL_RTS;

    cp210x_send_simple_request(CP210X_IFC_ENABLE, CP210X_UART_ENABLE, index);
    cp210x_send_simple_request(CP210X_SET_LINE_CTL, line_ctl, index);
    cp210x_send_baudrate(UART_BAUD_RATE, index);
    cp210x_send_simple_request(CP210X_SET_MHS, mhs, index);

    if (usb_debug_logs) {
        ESP_LOGI(TAG, "[USB][CP210X] init done: itf=%u baud=%u line=0x%04X mhs=0x%04X",
                 index, (unsigned)UART_BAUD_RATE, line_ctl, mhs);
    }
}

static void usb_cdc_new_dev_cb(usb_device_handle_t usb_dev, void *user_data)
{
    (void)user_data;

    const usb_device_desc_t *device_desc = NULL;
    const usb_config_desc_t *config_desc = NULL;
    esp_err_t dev_err = usb_host_get_device_descriptor(usb_dev, &device_desc);
    esp_err_t cfg_err = usb_host_get_active_config_descriptor(usb_dev, &config_desc);
    if (dev_err != ESP_OK || cfg_err != ESP_OK || !device_desc || !config_desc) {
        if (usb_debug_logs) {
            ESP_LOGW(TAG, "[USB] new_dev_cb: desc error dev=%s cfg=%s",
                     esp_err_to_name(dev_err), esp_err_to_name(cfg_err));
        }
        return;
    }

    usb_last_vid = device_desc->idVendor;
    usb_last_pid = device_desc->idProduct;
    usb_is_known_gps = (usb_last_vid == USB_GPS_KNOWN_VID && usb_last_pid == USB_GPS_KNOWN_PID);
    usb_cdc_preferred_valid = false;
    usb_cdc_preferred_itf = 0;

    int desc_offset = 0;
    const usb_standard_desc_t *this_desc = (const usb_standard_desc_t *)config_desc;
    while ((this_desc = usb_parse_next_descriptor_of_type(this_desc,
                                                         config_desc->wTotalLength,
                                                         USB_B_DESCRIPTOR_TYPE_INTERFACE,
                                                         &desc_offset))) {
        const usb_intf_desc_t *intf_desc = (const usb_intf_desc_t *)this_desc;
        if (intf_desc->bInterfaceClass == USB_CLASS_CDC_DATA) {
            usb_cdc_preferred_itf = intf_desc->bInterfaceNumber;
            usb_cdc_preferred_valid = true;
            break;
        }
    }

    if (!usb_cdc_preferred_valid) {
        int intf_offset = 0;
        const usb_standard_desc_t *intf_desc_std = (const usb_standard_desc_t *)config_desc;
        while ((intf_desc_std = usb_parse_next_descriptor_of_type(intf_desc_std,
                                                                  config_desc->wTotalLength,
                                                                  USB_B_DESCRIPTOR_TYPE_INTERFACE,
                                                                  &intf_offset))) {
            const usb_intf_desc_t *intf_desc = (const usb_intf_desc_t *)intf_desc_std;
            int desc_off = intf_offset;
            int temp_off = desc_off;
            bool has_in = false;
            bool has_out = false;

            for (int i = 0; i < intf_desc->bNumEndpoints; i++) {
                const usb_ep_desc_t *ep_desc = usb_parse_endpoint_descriptor_by_index(intf_desc, i,
                                                                                      config_desc->wTotalLength,
                                                                                      &desc_off);
                if (!ep_desc) {
                    continue;
                }
                if (USB_EP_DESC_GET_XFERTYPE(ep_desc) == USB_TRANSFER_TYPE_BULK) {
                    if (USB_EP_DESC_GET_EP_DIR(ep_desc)) {
                        has_in = true;
                    } else {
                        has_out = true;
                    }
                }
                desc_off = temp_off;
            }

            if (has_in && has_out) {
                usb_cdc_preferred_itf = intf_desc->bInterfaceNumber;
                usb_cdc_preferred_valid = true;
                if (usb_debug_logs) {
                    ESP_LOGI(TAG, "[USB] Fallback bulk interface selected: itf=%u class=0x%02X",
                             usb_cdc_preferred_itf, intf_desc->bInterfaceClass);
                }
                break;
            }
        }
    }

    if (usb_debug_logs) {
        ESP_LOGI(TAG, "[USB] new_dev_cb: vid=0x%04X pid=0x%04X class=0x%02X pref_itf=%u valid=%d",
                 device_desc->idVendor,
                 device_desc->idProduct,
                 device_desc->bDeviceClass,
                 usb_cdc_preferred_itf,
                 usb_cdc_preferred_valid);
        if (usb_is_known_gps) {
            ESP_LOGI(TAG, "[USB] Known GPS device detected by VID/PID");
        }
    }
}

static const char *usb_cdc_state_str(usbh_cdc_state_t state)
{
    switch (state) {
        case USBH_CDC_CLOSE: return "CLOSE";
        case USBH_CDC_OPEN: return "OPEN";
        default: return "UNKNOWN";
    }
}

static void usb_log_cdc_state(const char *where)
{
    if (!usb_cdc_handle) {
        ESP_LOGI(TAG, "[USB] %s: handle=NULL connected=%d transport_ready=%d",
                 where, usb_cdc_connected, usb_transport_ready);
        return;
    }

    usbh_cdc_state_t state = USBH_CDC_CLOSE;
    esp_err_t state_err = usbh_cdc_get_state(usb_cdc_handle, &state);
    size_t rx_size = 0;
    esp_err_t rx_err = usbh_cdc_get_rx_buffer_size(usb_cdc_handle, &rx_size);

    ESP_LOGI(TAG,
             "[USB] %s: handle=%p connected=%d transport_ready=%d state=%s(%d) state_err=%s rx_buf=%u rx_err=%s",
             where,
             (void *)usb_cdc_handle,
             usb_cdc_connected,
             usb_transport_ready,
             usb_cdc_state_str(state),
             (int)state,
             esp_err_to_name(state_err),
             (unsigned)rx_size,
             esp_err_to_name(rx_err));
}

static void schedule_board_redetect(void);

static void board_redetect_cb(void *user_data)
{
    (void)user_data;
    ESP_LOGI(TAG, "board_redetect_cb called");
    board_redetect_pending = false;

    bool prev_grove = grove_detected;
    bool prev_usb = usb_detected;
    bool prev_uart2 = mbus_detected;
    bool prev_grove_sd = grove_ctx.sd_card_present;
    bool prev_usb_sd = usb_ctx.sd_card_present;
    bool prev_mbus_sd = mbus_ctx.sd_card_present;
    bool prev_internal_sd = internal_sd_present;

    detect_boards();

    // One SD probe only, and only after the board answered ping.
    check_all_sd_cards();

    // Re-probe Sub-GHz availability so the home tile reflects the new state.
    check_all_subghz_status();

    bool changed = (prev_grove != grove_detected) ||
                   (prev_usb != usb_detected) ||
                   (prev_uart2 != mbus_detected) ||
                   (prev_grove_sd != grove_ctx.sd_card_present) ||
                   (prev_usb_sd != usb_ctx.sd_card_present) ||
                   (prev_mbus_sd != mbus_ctx.sd_card_present) ||
                   (prev_internal_sd != internal_sd_present);

    ESP_LOGI(TAG, "Redetect: changed=%d, uart1=%d, mbus=%d, sd: G=%d U=%d M=%d I=%d, popup_open=%d",
             changed, uart1_detected, mbus_detected,
             grove_ctx.sd_card_present, usb_ctx.sd_card_present,
             mbus_ctx.sd_card_present, internal_sd_present,
             board_detection_popup_open);

    if (changed && (uart1_detected || mbus_detected) && !board_detection_popup_open) {
        ESP_LOGI(TAG, "Redetect: calling reload_gui_for_detection + show_main_tiles");
        reload_gui_for_detection();
        show_main_tiles();
    } else if (changed) {
        ESP_LOGW(TAG, "Redetect: changed but conditions not met for reload");
    }
}

static void schedule_board_redetect(void)
{
    if (board_redetect_pending) {
        return;
    }
    board_redetect_pending = true;
    lv_async_call(board_redetect_cb, NULL);
}

static tab_id_t uart1_preferred_tab(void)
{
    if (grove_detected) {
        return TAB_GROVE;
    }
    if (usb_detected) {
        return TAB_USB;
    }
    return TAB_GROVE;
}

static void usb_check_host_installed(void)
{
    if (usb_host_checked) {
        return;
    }
    usb_host_lib_info_t info = { 0 };
    esp_err_t err = usb_host_lib_info(&info);
    usb_host_installed = (err == ESP_OK);
    usb_host_checked = true;
}

static void usb_cdc_connect_cb(usbh_cdc_handle_t cdc_handle, void *user_data)
{
    (void)user_data;
    usb_cdc_handle = cdc_handle;
    usb_cdc_connected = true;
    usb_nmea_device_seen = false;
    usb_transport_ready = true;
    usb_transport_warned = false;
    ESP_LOGI(TAG, "[USB] CDC device connected (handle=%p)", (void *)cdc_handle);

    // Note: SET_LINE_CODING and SET_CONTROL_LINE_STATE are skipped because:
    // 1. They cause 5-second blocking timeouts
    // 2. ESP32 USB Serial/JTAG doesn't support these CDC class requests (returns STALL)
    // 3. Data transfer works without them for this device type

    // Flush any stale data in the RX buffer
    esp_err_t flush_err = usbh_cdc_flush_rx_buffer(cdc_handle);
    if (flush_err != ESP_OK) {
        ESP_LOGW(TAG, "[USB] Flush RX buffer failed on connect: %s", esp_err_to_name(flush_err));
    }

    if (usb_debug_logs) {
        esp_err_t desc_err = usbh_cdc_desc_print(cdc_handle);
        ESP_LOGI(TAG, "[USB] CDC descriptor dump: %s", esp_err_to_name(desc_err));
        usb_log_cdc_state("connect");
    }

    if (usb_last_vid == CP210X_VID) {
        cp210x_init_port(usb_cdc_preferred_itf);
    }

    start_usb_gps_drain_task();
    schedule_board_redetect();
}

static void usb_cdc_disconnect_cb(usbh_cdc_handle_t cdc_handle, void *user_data)
{
    (void)cdc_handle;
    (void)user_data;
    if (usb_cdc_handle == cdc_handle) {
        usb_cdc_handle = NULL;
    }
    usb_cdc_connected = false;
    usb_transport_ready = false;
    usb_transport_warned = false;
    usb_nmea_device_seen = false;
    usb_is_known_gps = false;
    usb_gps_fix_valid = false;
    usb_gps_line_len = 0;
    usb_cdc_preferred_valid = false;
    usb_cdc_preferred_itf = 0;
    usb_last_vid = 0;
    usb_last_pid = 0;
    ESP_LOGW(TAG, "[USB] CDC device disconnected");
    if (usb_debug_logs) {
        usb_log_cdc_state("disconnect");
    }
    schedule_board_redetect();
}

static void usb_cdc_recv_cb(usbh_cdc_handle_t cdc_handle, void *user_data)
{
    (void)cdc_handle;
    (void)user_data;
}

static void usb_cdc_notif_cb(usbh_cdc_handle_t cdc_handle, iot_cdc_notification_t *notif, void *user_data)
{
    (void)cdc_handle;
    (void)user_data;
    if (!usb_debug_logs) {
        return;
    }
    if (!notif) {
        ESP_LOGW(TAG, "[USB] CDC notification: NULL");
        return;
    }
    ESP_LOGI(TAG, "[USB] CDC notification: bmReq=0x%02X code=0x%02X wValue=0x%04X wIndex=0x%04X wLen=%u",
             notif->bmRequestType,
             notif->bNotificationCode,
             notif->wValue,
             notif->wIndex,
             notif->wLength);
}

static void usb_transport_init(void)
{
    if (usb_transport_ready) {
        return;
    }

    if (usb_cdc_handle) {
        usb_transport_ready = true;
        return;
    }

    uint32_t now_ms = lv_tick_get();
    if (now_ms < usb_next_retry_ms) {
        return;
    }

    if (!usb_log_tuned) {
        if (usb_debug_logs) {
            esp_log_level_set("USBH_CDC", ESP_LOG_INFO);
            esp_log_level_set("USBH", ESP_LOG_INFO);
            esp_log_level_set("USB HOST", ESP_LOG_INFO);
        } else {
            esp_log_level_set("USBH_CDC", ESP_LOG_NONE);
            esp_log_level_set("USBH", ESP_LOG_NONE);
            esp_log_level_set("USB HOST", ESP_LOG_NONE);
        }
        usb_log_tuned = true;
    }

    ESP_LOGI(TAG, "[USB] Starting USB host for CDC...");
    usb_check_host_installed();
    if (!usb_host_installed) {
        esp_err_t err = bsp_usb_host_start(BSP_USB_HOST_POWER_MODE_USB_DEV, false);
        if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) {
            ESP_LOGE(TAG, "[USB] USB host start failed: %s", esp_err_to_name(err));
            return;
        }
        usb_host_installed = true;
        usb_host_started_by_us = true;
    } else {
        ESP_LOGI(TAG, "[USB] USB host already installed");
    }

    usbh_cdc_driver_config_t config = {
        .task_stack_size = 4096,
        .task_priority = 5,
        .task_coreid = -1,
        .skip_init_usb_host_driver = true,
        .new_dev_cb = usb_cdc_new_dev_cb,
        .user_data = NULL,
    };
    if (usb_debug_logs) {
        ESP_LOGI(TAG, "[USB] CDC driver config: stack=%d prio=%d core=%d",
                 config.task_stack_size, config.task_priority, config.task_coreid);
    }

    esp_err_t err = usbh_cdc_driver_install(&config);
    if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) {
        ESP_LOGE(TAG, "[USB] CDC driver install failed: %s", esp_err_to_name(err));
        return;
    }

    if (usb_debug_logs) {
        ESP_LOGI(TAG, "[USB] Waiting for new_dev_cb...");
    }
    for (int i = 0; i < 5 && !usb_cdc_preferred_valid; i++) {
        vTaskDelay(pdMS_TO_TICKS(20));
    }

    if (!usb_cdc_preferred_valid) {
        if (usb_debug_logs) {
            ESP_LOGW(TAG, "[USB] No CDC-DATA or bulk IN/OUT interface found, ignoring device");
        }
        return;
    }

    usbh_cdc_device_config_t dev_config = {
        .vid = CDC_HOST_ANY_VID,
        .pid = CDC_HOST_ANY_PID,
        .itf_num = usb_cdc_preferred_valid ? usb_cdc_preferred_itf : 0,
        .rx_buffer_size = UART_BUF_SIZE,
        .tx_buffer_size = UART_BUF_SIZE,
        .cbs = {
            .connect = usb_cdc_connect_cb,
            .disconnect = usb_cdc_disconnect_cb,
            .recv_data = usb_cdc_recv_cb,
            .notif_cb = usb_cdc_notif_cb,
            .user_data = NULL,
        },
    };
    if (usb_debug_logs) {
        ESP_LOGI(TAG, "[USB] CDC device config: vid=0x%04X pid=0x%04X itf=%d rx=%u tx=%u",
                 dev_config.vid, dev_config.pid, dev_config.itf_num,
                 (unsigned)dev_config.rx_buffer_size, (unsigned)dev_config.tx_buffer_size);
    }

    err = usbh_cdc_create(&dev_config, &usb_cdc_handle);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "[USB] CDC create failed: %s", esp_err_to_name(err));
        usb_next_retry_ms = now_ms + 1000;
        return;
    }

    usb_transport_ready = true;
    usb_transport_warned = false;
    ESP_LOGI(TAG, "[USB] USB CDC host ready, waiting for device...");
}

static __attribute__((unused)) void usb_transport_deinit(void)
{
    if (!usb_transport_ready) {
        return;
    }

    if (usb_cdc_handle) {
        usbh_cdc_delete(usb_cdc_handle);
        usb_cdc_handle = NULL;
    }

    usbh_cdc_driver_uninstall();
    if (usb_host_started_by_us) {
        bsp_usb_host_stop();
        usb_host_started_by_us = false;
    }

    usb_transport_ready = false;
    ESP_LOGI(TAG, "[USB] USB CDC host stopped");
}

static int usb_transport_write(const char *data, size_t len)
{
    if (!usb_transport_ready) {
        ESP_LOGD(TAG, "[USB] Transport not ready, initializing...");
        usb_transport_init();
    }
    if (!usb_cdc_handle || !usb_cdc_connected) {
        if (!usb_transport_warned) {
            ESP_LOGW(TAG, "[USB] No CDC device connected (handle=%p, connected=%d)",
                     (void*)usb_cdc_handle, usb_cdc_connected);
            usb_transport_warned = true;
        }
        return 0;
    }

    ESP_LOGD(TAG, "[USB] Writing %zu bytes: %.*s", len, (int)(len > 50 ? 50 : len), data);

    esp_err_t err = usbh_cdc_write_bytes(usb_cdc_handle, (const uint8_t *)data, len, pdMS_TO_TICKS(200));
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "[USB] CDC write failed: %s", esp_err_to_name(err));
        if (usb_debug_logs) {
            usb_log_cdc_state("write_failed");
        }
        return 0;
    }

    ESP_LOGD(TAG, "[USB] Write successful: %zu bytes", len);
    return (int)len;
}

static int usb_transport_read(void *data, size_t len, TickType_t ticks_to_wait)
{
    if (!usb_transport_ready) {
        ESP_LOGD(TAG, "[USB] Transport not ready for read, initializing...");
        usb_transport_init();
    }
    if (!usb_cdc_handle || !usb_cdc_connected) {
        ESP_LOGD(TAG, "[USB] Read failed: no CDC device (handle=%p, connected=%d)",
                 (void*)usb_cdc_handle, usb_cdc_connected);
        return 0;
    }
    size_t rx_size = 0;
    esp_err_t rx_err = usbh_cdc_get_rx_buffer_size(usb_cdc_handle, &rx_size);
    if (rx_err == ESP_OK && rx_size == 0) {
        if (ticks_to_wait > 0) {
            vTaskDelay(ticks_to_wait);
            rx_err = usbh_cdc_get_rx_buffer_size(usb_cdc_handle, &rx_size);
        }
        if (rx_err == ESP_OK && rx_size == 0) {
            return 0;
        }
    }

    size_t read_len = len;
    esp_err_t err = usbh_cdc_read_bytes(usb_cdc_handle, (uint8_t *)data, &read_len, 0);
    if (err != ESP_OK) {
        // ESP_FAIL often means no data available - treat as timeout (normal during polling)
        // ESP_ERR_TIMEOUT is also normal
        // Only log actual unexpected errors
        if (err != ESP_ERR_TIMEOUT && err != ESP_FAIL) {
            ESP_LOGW(TAG, "[USB] CDC read error: %s (0x%x)", esp_err_to_name(err), err);
            if (usb_debug_logs) {
                usb_log_cdc_state("read_error");
            }
        }
        return 0;
    }
    if (read_len > 0) {
        // Log raw bytes received from USB (hex + ASCII for debugging)
        char hex_buf[128];
        char ascii_buf[64];
        size_t log_len = read_len > 32 ? 32 : read_len;  // Limit to 32 bytes in log
        for (size_t i = 0; i < log_len; i++) {
            uint8_t b = ((uint8_t*)data)[i];
            snprintf(hex_buf + i*3, 4, "%02X ", b);
            ascii_buf[i] = (b >= 32 && b < 127) ? (char)b : '.';
        }
        hex_buf[log_len * 3] = '\0';
        ascii_buf[log_len] = '\0';
        ESP_LOGD(TAG, "[USB] Read %zu bytes: [%s] \"%s\"%s",
                 read_len, hex_buf, ascii_buf, read_len > 32 ? "..." : "");
    }
    return (int)read_len;
}

static void usb_flush_input(uint32_t max_ms)
{
    if (!usb_cdc_handle || !usb_cdc_connected) {
        return;
    }
    uint8_t tmp[64];
    uint32_t start_ms = esp_timer_get_time() / 1000;
    while ((esp_timer_get_time() / 1000) - start_ms < max_ms) {
        size_t rx_size = 0;
        if (usbh_cdc_get_rx_buffer_size(usb_cdc_handle, &rx_size) != ESP_OK || rx_size == 0) {
            break;
        }
        size_t read_len = rx_size > sizeof(tmp) ? sizeof(tmp) : rx_size;
        usbh_cdc_read_bytes(usb_cdc_handle, tmp, &read_len, 0);
    }
    if (usb_debug_logs) {
        ESP_LOGI(TAG, "[USB] Flushed input for %u ms", (unsigned)max_ms);
    }
}

static bool usb_buffer_contains_nmea(const char *buf)
{
    if (!buf) {
        return false;
    }
    return strstr(buf, "$GP") != NULL ||
           strstr(buf, "$GN") != NULL ||
           strstr(buf, "$GL") != NULL ||
           strstr(buf, "$GA") != NULL;
}

// Ping USB device to verify it responds (similar to ping_uart_direct for Grove/MBus)
static bool ping_usb(void)
{
    bool detected = false;

    usb_rx_exclusive = true;

    if (!usb_cdc_handle || !usb_cdc_connected) {
        ESP_LOGW(TAG, "[USB] Cannot ping - no CDC device connected");
        goto done;
    }

    // NOTE: do NOT flush here - we want to keep JanOS's pre-ping boot banner so
    // we can snoop "JanOS version:" / "JanOS RF version:" lines into usb_ctx.

    // Send ping command
    const char *ping_cmd = "ping\r\n";
    int written = usb_transport_write(ping_cmd, strlen(ping_cmd));
    if (written <= 0) {
        ESP_LOGW(TAG, "[USB] Failed to send ping");
        goto done;
    }
    ESP_LOGI(TAG, "[USB] Sent ping");

    // Wait for pong response (timeout ~500ms, 10 x 50ms reads)
    char buf[64];
    int total = 0;
    bool saw_nmea = false;
    char line_buf[160];
    int line_pos = 0;
    for (int i = 0; i < 10; i++) {
        int n = usb_transport_read(buf + total, sizeof(buf) - total - 1, pdMS_TO_TICKS(50));
        if (usb_debug_logs && n == 0) {
            ESP_LOGD(TAG, "[USB] Ping wait %d/10: no data", i + 1);
        }
        if (n > 0) {
            usb_gps_process_bytes((const uint8_t *)(buf + total), (size_t)n);
            // Snoop JanOS boot banner lines into usb_ctx
            janos_feed_bytes(&usb_ctx, "USB", (const uint8_t *)(buf + total), n,
                             line_buf, sizeof(line_buf), &line_pos);
            total += n;
            buf[total] = '\0';
            if (!saw_nmea && usb_buffer_contains_nmea(buf)) {
                saw_nmea = true;
            }
            if (strstr(buf, "pong")) {
                usb_nmea_device_seen = false;
                ESP_LOGI(TAG, "[USB] Received pong - device detected!");
                detected = true;
                goto done;
            }
        }
    }

    usb_nmea_device_seen = saw_nmea;
    if (saw_nmea) {
        if (usb_debug_logs && total > 0) {
            ESP_LOGI(TAG, "[USB] NMEA stream detected during ping probe: \"%s\"", buf);
        }
        ESP_LOGI(TAG, "[USB] CDC device appears to be GPS (NMEA), not scanner board");
    } else {
        if (usb_debug_logs && total > 0) {
            ESP_LOGW(TAG, "[USB] No pong response, partial data: \"%s\"", buf);
        }
        ESP_LOGW(TAG, "[USB] No pong response - device not detected");
    }

done:
    usb_rx_exclusive = false;
    return detected;
}

static bool usb_gps_parse_nmea_coord(const char *field, char hemisphere, double *out)
{
    if (!field || !*field || !out) {
        return false;
    }

    char *endptr = NULL;
    double raw = strtod(field, &endptr);
    if (endptr == field || !isfinite(raw)) {
        return false;
    }

    int degrees = (int)(raw / 100.0);
    double minutes = raw - ((double)degrees * 100.0);
    if (minutes < 0.0 || minutes >= 60.0) {
        return false;
    }

    double decimal = (double)degrees + (minutes / 60.0);
    if (hemisphere == 'S' || hemisphere == 'W') {
        decimal = -decimal;
    } else if (hemisphere != 'N' && hemisphere != 'E') {
        return false;
    }

    *out = decimal;
    return true;
}

static bool usb_gps_parse_sentence(const char *sentence, double *lat_out, double *lon_out)
{
    if (!sentence || sentence[0] != '$' || !lat_out || !lon_out) {
        return false;
    }

    char buf[160];
    snprintf(buf, sizeof(buf), "%s", sentence);

    char *checksum = strchr(buf, '*');
    if (checksum) {
        *checksum = '\0';
    }

    char *saveptr = NULL;
    char *token = strtok_r(buf, ",", &saveptr);
    if (!token) {
        return false;
    }

    bool is_gga = strstr(token, "GGA") != NULL;
    bool is_rmc = strstr(token, "RMC") != NULL;
    if (!is_gga && !is_rmc) {
        return false;
    }

    const char *lat_field = NULL;
    const char *lat_hemi = NULL;
    const char *lon_field = NULL;
    const char *lon_hemi = NULL;
    const char *fix_field = NULL;
    const char *status_field = NULL;
    int field_idx = 0;

    while ((token = strtok_r(NULL, ",", &saveptr)) != NULL) {
        field_idx++;
        if (is_gga) {
            if (field_idx == 2) lat_field = token;
            if (field_idx == 3) lat_hemi = token;
            if (field_idx == 4) lon_field = token;
            if (field_idx == 5) lon_hemi = token;
            if (field_idx == 6) fix_field = token;
        } else {
            if (field_idx == 2) status_field = token;
            if (field_idx == 3) lat_field = token;
            if (field_idx == 4) lat_hemi = token;
            if (field_idx == 5) lon_field = token;
            if (field_idx == 6) lon_hemi = token;
        }
    }

    if (!lat_field || !lat_hemi || !lon_field || !lon_hemi) {
        return false;
    }

    if (is_gga) {
        if (!fix_field || atoi(fix_field) <= 0) {
            return false;
        }
    } else {
        if (!status_field || toupper((unsigned char)status_field[0]) != 'A') {
            return false;
        }
    }

    double lat = 0.0;
    double lon = 0.0;
    if (!usb_gps_parse_nmea_coord(lat_field, toupper((unsigned char)lat_hemi[0]), &lat)) {
        return false;
    }
    if (!usb_gps_parse_nmea_coord(lon_field, toupper((unsigned char)lon_hemi[0]), &lon)) {
        return false;
    }

    *lat_out = lat;
    *lon_out = lon;
    return true;
}

static void usb_gps_process_bytes(const uint8_t *data, size_t len)
{
    if (!data || len == 0) {
        return;
    }

    for (size_t i = 0; i < len; i++) {
        char c = (char)data[i];
        if (c == '\r' || c == '\n') {
            if (usb_gps_line_len > 0) {
                usb_gps_line_buffer[usb_gps_line_len] = '\0';
                double lat = 0.0;
                double lon = 0.0;
                if (usb_gps_parse_sentence(usb_gps_line_buffer, &lat, &lon)) {
                    usb_gps_last_lat = lat;
                    usb_gps_last_lon = lon;
                    usb_gps_fix_tick = lv_tick_get();
                    usb_gps_fix_valid = true;
                    ESP_LOGD(TAG, "[USB][GPS] Fix %.6f, %.6f", lat, lon);
                }
                usb_gps_line_len = 0;
            }
            continue;
        }

        if (usb_gps_line_len < sizeof(usb_gps_line_buffer) - 1) {
            usb_gps_line_buffer[usb_gps_line_len++] = c;
        } else {
            usb_gps_line_len = 0;
        }
    }
}

static void usb_gps_poll(uint32_t wait_ms)
{
    if (!usb_cdc_handle || !usb_cdc_connected) {
        return;
    }

    uint8_t rx_buf[128];
    uint32_t start = lv_tick_get();

    do {
        uint32_t elapsed = lv_tick_elaps(start);
        uint32_t remaining = (wait_ms > elapsed) ? (wait_ms - elapsed) : 0;
        TickType_t wait_ticks = 0;
        if (remaining > 0) {
            uint32_t slice_ms = remaining > 40 ? 40 : remaining;
            wait_ticks = pdMS_TO_TICKS(slice_ms);
        }

        int read_len = usb_transport_read(rx_buf, sizeof(rx_buf), wait_ticks);
        if (read_len > 0) {
            usb_gps_process_bytes(rx_buf, (size_t)read_len);
            continue;
        }

        if (usb_gps_fix_valid && lv_tick_elaps(usb_gps_fix_tick) <= USB_GPS_FIX_MAX_AGE_MS) {
            return;
        }
        if (wait_ms == 0 || remaining == 0) {
            return;
        }
    } while (lv_tick_elaps(start) < wait_ms);
}

static bool usb_gps_get_fix(double *lat_out, double *lon_out, uint32_t wait_ms)
{
    if (!lat_out || !lon_out) {
        return false;
    }

    if (!usb_cdc_handle || !usb_cdc_connected) {
        return false;
    }

    usb_rx_exclusive = true;
    usb_gps_poll(wait_ms);
    usb_rx_exclusive = false;

    if (!usb_gps_fix_valid) {
        return false;
    }
    if (lv_tick_elaps(usb_gps_fix_tick) > USB_GPS_FIX_MAX_AGE_MS) {
        return false;
    }

    *lat_out = usb_gps_last_lat;
    *lon_out = usb_gps_last_lon;
    return true;
}

static void usb_gps_drain_task(void *arg)
{
    (void)arg;
    uint8_t rx_buf[128];

    while (1) {
        bool should_drain = usb_cdc_connected &&
                            (usb_is_known_gps || usb_nmea_device_seen) &&
                            !usb_detected &&
                            !usb_rx_exclusive;

        if (!should_drain) {
            vTaskDelay(pdMS_TO_TICKS(100));
            continue;
        }

        int len = usb_transport_read(rx_buf, sizeof(rx_buf), pdMS_TO_TICKS(50));
        if (len > 0) {
            usb_gps_process_bytes(rx_buf, (size_t)len);
        } else {
            vTaskDelay(pdMS_TO_TICKS(10));
        }
    }
}

static void start_usb_gps_drain_task(void)
{
    if (usb_gps_drain_task_handle) {
        return;
    }

    if (xTaskCreate(usb_gps_drain_task, "usb_gps_drain", 4096, NULL, 4, &usb_gps_drain_task_handle) != pdTRUE) {
        usb_gps_drain_task_handle = NULL;
        ESP_LOGW(TAG, "[USB] Failed to create GPS drain task");
    }
}

static int transport_write_bytes_tab(tab_id_t tab, uart_port_t port, const char *data, size_t len)
{
    if (port == UART_NUM && tab == TAB_USB) {
        return usb_transport_write(data, len);
    }
    return uart_write_bytes(port, data, len);
}

static int transport_read_bytes_tab(tab_id_t tab, uart_port_t port, void *data, size_t len, TickType_t ticks_to_wait)
{
    if (port == UART_NUM && tab == TAB_USB) {
        return usb_transport_read(data, len, ticks_to_wait);
    }
    return uart_read_bytes(port, (uint8_t *)data, len, ticks_to_wait);
}

static int transport_write_bytes(uart_port_t port, const char *data, size_t len)
{
    return transport_write_bytes_tab(current_tab, port, data, len);
}

static int transport_read_bytes(uart_port_t port, void *data, size_t len, TickType_t ticks_to_wait)
{
    return transport_read_bytes_tab(current_tab, port, data, len, ticks_to_wait);
}

// UART initialization
static void uart_init(void)
{
    const uart_config_t uart_config = {
        .baud_rate = UART_BAUD_RATE,
        .data_bits = UART_DATA_8_BITS,
        .parity    = UART_PARITY_DISABLE,
        .stop_bits = UART_STOP_BITS_1,
        .flow_ctrl = UART_HW_FLOWCTRL_DISABLE,
        .source_clk = UART_SCLK_DEFAULT,
    };

    // Get UART1 pins (fixed to Grove connector)
    int tx_pin, rx_pin;
    get_uart1_pins(&tx_pin, &rx_pin);

    ESP_ERROR_CHECK(uart_driver_install(UART_NUM, UART_BUF_SIZE * 2, 0, 0, NULL, 0));
    ESP_ERROR_CHECK(uart_param_config(UART_NUM, &uart_config));
    ESP_ERROR_CHECK(uart_set_pin(UART_NUM, tx_pin, rx_pin,
                                  UART_PIN_NO_CHANGE, UART_PIN_NO_CHANGE));

    ESP_LOGI(TAG, "[Grove] Initialized: TX=%d, RX=%d, baud=%d (Grove connector)",
             tx_pin, rx_pin, UART_BAUD_RATE);

    usb_transport_init();
}

// Log memory statistics
static void log_memory_stats(const char *context)
{
    size_t internal_free = heap_caps_get_free_size(MALLOC_CAP_INTERNAL);
    size_t internal_min = heap_caps_get_minimum_free_size(MALLOC_CAP_INTERNAL);
    size_t dma_free = heap_caps_get_free_size(MALLOC_CAP_DMA);
    size_t dma_min = heap_caps_get_minimum_free_size(MALLOC_CAP_DMA);
    size_t psram_free = heap_caps_get_free_size(MALLOC_CAP_SPIRAM);
    size_t psram_min = heap_caps_get_minimum_free_size(MALLOC_CAP_SPIRAM);

    ESP_LOGI(TAG, "[MEM:%s] INTERNAL: %zu free, %zu min | DMA: %zu free, %zu min | PSRAM: %zu free, %zu min",
             context,
             internal_free, internal_min,
             dma_free, dma_min,
             psram_free, psram_min);
}

// Send command over UART1 (primary)
static void uart_send_command(const char *cmd)
{
    log_memory_stats("TX1");
    tab_id_t uart1_tab = uart1_preferred_tab();
    transport_write_bytes_tab(uart1_tab, UART_NUM, cmd, strlen(cmd));
    transport_write_bytes_tab(uart1_tab, UART_NUM, "\r\n", 2);
    ESP_LOGI(TAG, "[%s] Sent command: %s", tab_transport_name(uart1_tab), cmd);
}

// Send command over MBus (UART2)
static void uart2_send_command(const char *cmd)
{
    if (!uart2_initialized) {
        ESP_LOGW(TAG, "[MBus] Not initialized");
        return;
    }
    log_memory_stats("TX2");
    transport_write_bytes(UART2_NUM, cmd, strlen(cmd));
    transport_write_bytes(UART2_NUM, "\r\n", 2);
    ESP_LOGI(TAG, "[MBus] Sent command: %s", cmd);
}

static void trim_ascii_whitespace(char *s)
{
    if (!s || s[0] == '\0') return;

    char *start = s;
    while (*start == ' ' || *start == '\t') start++;
    if (start != s) {
        memmove(s, start, strlen(start) + 1);
    }

    size_t len = strlen(s);
    while (len > 0) {
        char c = s[len - 1];
        if (c == ' ' || c == '\t') {
            s[--len] = '\0';
        } else {
            break;
        }
    }
}

static int parse_csv_mixed_fields(char *line, char **fields, int max_fields)
{
    if (!line || !fields || max_fields <= 0) return 0;

    int field_idx = 0;
    char *p = line;

    while (*p != '\0' && field_idx < max_fields) {
        if (*p == ',') {
            p++;
            continue;
        }

        if (*p == '"') {
            p++;  // Skip opening quote
            fields[field_idx++] = p;
            while (*p != '\0') {
                if (*p == '"' && p[1] == '"') {
                    // Keep one quote character in-place: "" -> "
                    memmove(p, p + 1, strlen(p));
                    p++;
                    continue;
                }
                if (*p == '"') {
                    *p = '\0';
                    p++;
                    break;
                }
                p++;
            }
            if (*p == ',') p++;
        } else {
            fields[field_idx++] = p;
            while (*p != '\0' && *p != ',') p++;
            if (*p == ',') {
                *p = '\0';
                p++;
            }
            trim_ascii_whitespace(fields[field_idx - 1]);
        }
    }

    return field_idx;
}

// Parse a single network line like:
// "1","SSID","","C4:2B:44:12:29:21","1","WPA2","-53","2.4GHz","Vendor Name"
// and also handles optional unquoted vendor as 9th field.
static bool parse_network_line(const char *line, wifi_network_t *net)
{
    // Check if line starts with quote and number
    if (line[0] != '"') return false;

    char temp[512];
    strncpy(temp, line, sizeof(temp) - 1);
    temp[sizeof(temp) - 1] = '\0';

    // Parse CSV with mixed quoted/unquoted fields
    char *fields[10] = {NULL};
    int field_idx = parse_csv_mixed_fields(temp, fields, 10);

    if (field_idx < 8) return false;

    // fields[0] = index, fields[1] = SSID, fields[3] = BSSID, fields[4] = channel, fields[5] = security, fields[6] = RSSI, fields[7] = band
    net->index = atoi(fields[0]);
    if (net->index <= 0) return false;

    strncpy(net->ssid, fields[1], sizeof(net->ssid) - 1);
    net->ssid[sizeof(net->ssid) - 1] = '\0';

    strncpy(net->bssid, fields[3], sizeof(net->bssid) - 1);
    net->bssid[sizeof(net->bssid) - 1] = '\0';

    net->channel = (field_idx >= 5 && fields[4]) ? atoi(fields[4]) : 0;

    strncpy(net->security, fields[5], sizeof(net->security) - 1);
    net->security[sizeof(net->security) - 1] = '\0';

    net->rssi = atoi(fields[6]);

    strncpy(net->band, fields[7], sizeof(net->band) - 1);
    net->band[sizeof(net->band) - 1] = '\0';

    net->vendor[0] = '\0';
    // JanOS format in logs: vendor is usually the 3rd field (index 2).
    if (field_idx >= 3 && fields[2] && fields[2][0] != '\0') {
        strncpy(net->vendor, fields[2], sizeof(net->vendor) - 1);
        net->vendor[sizeof(net->vendor) - 1] = '\0';
    } else if (field_idx >= 9 && fields[8] && fields[8][0] != '\0') {
        // Fallback for alternate format with vendor as 9th field.
        strncpy(net->vendor, fields[8], sizeof(net->vendor) - 1);
        net->vendor[sizeof(net->vendor) - 1] = '\0';
    }

    return true;
}

// ============================================================================
// INSPECT-NETWORK ASYNC TASK
// Runs after a successful scan; iterates 1..network_count calling
// `inspect_network <i>` and rewriting each scanned row's info_label with
// MFP/NO_MFP + uptime info. Allocated in PSRAM. Cooperatively cancelled
// before any attack-initiating UART traffic so commands don't clash.
// ============================================================================

// Cooperatively stop the inspect task for the given tab.
// Sets the active flag false and waits up to ~250 ms for the task to exit.
static void cancel_inspect_task(tab_context_t *ctx)
{
    if (!ctx) return;
    if (!ctx->inspect_task && !ctx->inspect_active) return;

    ctx->inspect_active = false;
    for (int w = 0; w < 25 && ctx->inspect_task != NULL; w++) {
        vTaskDelay(pdMS_TO_TICKS(10));
    }
    if (ctx->inspect_task != NULL) {
        ESP_LOGW(TAG, "cancel_inspect_task: task did not exit within 250 ms");
    }
}

// Extract `key=` value into `out` (zero-terminated), copying up to `out_sz - 1`
// bytes until the first space or end-of-string. Returns true on success.
static bool extract_inspect_kv(const char *line, const char *key,
                               char *out, size_t out_sz)
{
    if (!line || !key || !out || out_sz == 0) return false;
    const char *p = strstr(line, key);
    if (!p) return false;
    p += strlen(key);
    size_t i = 0;
    while (*p && *p != ' ' && *p != '\r' && *p != '\n' && i + 1 < out_sz) {
        out[i++] = *p++;
    }
    out[i] = '\0';
    return i > 0;
}

// `uptime_str=` is the only multi-word value in the [INSPECT] line. Extract
// it up to (but not including) the next ` <key>=` token, falling back to
// end-of-line. Returns true on success.
static bool extract_inspect_uptime(const char *line, char *out, size_t out_sz)
{
    if (!line || !out || out_sz == 0) return false;
    const char *start = strstr(line, "uptime_str=");
    if (!start) return false;
    start += strlen("uptime_str=");

    // Find the next " <something>=" boundary which terminates the value.
    const char *end = start;
    const char *probe = start;
    while (*probe) {
        if (*probe == ' ') {
            const char *q = probe + 1;
            while (*q && *q != ' ' && *q != '=') q++;
            if (*q == '=') {
                end = probe;
                break;
            }
        }
        probe++;
    }
    if (end == start) {
        end = start + strlen(start);
        while (end > start && (end[-1] == '\r' || end[-1] == '\n')) end--;
    }

    size_t len = (size_t)(end - start);
    if (len >= out_sz) len = out_sz - 1;
    memcpy(out, start, len);
    out[len] = '\0';
    return len > 0;
}

static void inspect_networks_task(void *arg)
{
    tab_id_t tab = (tab_id_t)(uintptr_t)arg;
    tab_context_t *ctx = get_ctx_for_tab(tab);
    if (!ctx) {
        ESP_LOGE(TAG, "inspect_networks_task: no ctx for tab %d", tab);
        vTaskDeleteWithCaps(NULL);
        return;
    }

    uart_port_t port = uart_port_for_tab(tab);
    const char *uart_name = tab_transport_name(tab);

    char *rx   = heap_caps_malloc(UART_BUF_SIZE, MALLOC_CAP_SPIRAM);
    char *line = heap_caps_malloc(512,           MALLOC_CAP_SPIRAM);
    if (!rx || !line) {
        ESP_LOGE(TAG, "[%s] inspect: PSRAM allocation failed", uart_name);
        if (rx) heap_caps_free(rx);
        if (line) heap_caps_free(line);
        ctx->inspect_task = NULL;
        ctx->inspect_active = false;
        vTaskDeleteWithCaps(NULL);
        return;
    }

    ESP_LOGI(TAG, "[%s] inspect task started for %d networks",
             uart_name, ctx->inspect_label_count);

    int total = ctx->inspect_label_count;
    for (int i = 1; ctx->inspect_active && i <= total; i++) {
        // Flush any stale bytes before sending each command so we read the
        // matching [INSPECT] line cleanly.
        if (tab == TAB_USB && usb_cdc_handle) {
            usbh_cdc_flush_rx_buffer(usb_cdc_handle);
        } else {
            uart_flush(port);
        }

        char cmd[40];
        int  n = snprintf(cmd, sizeof(cmd), "inspect_network %d\r\n", i);
        transport_write_bytes_tab(tab, port, cmd, n);

        bool       got_line = false;
        int        lp = 0;
        TickType_t t0 = xTaskGetTickCount();
        bool       mfp_capable = false;
        char       uptime_str[64] = {0};

        while (ctx->inspect_active && !got_line &&
               (xTaskGetTickCount() - t0) < pdMS_TO_TICKS(1500)) {
            int rxlen = transport_read_bytes_tab(tab, port, rx,
                                                 UART_BUF_SIZE - 1,
                                                 pdMS_TO_TICKS(100));
            if (rxlen <= 0) continue;
            rx[rxlen] = '\0';

            for (int b = 0; b < rxlen && !got_line; b++) {
                char c = rx[b];
                if (c == '\n' || c == '\r') {
                    if (lp > 0) {
                        line[lp] = '\0';
                        if (strstr(line, "[INSPECT]")) {
                            char mfp_val[8] = {0};
                            if (extract_inspect_kv(line, "mfp_capable=",
                                                   mfp_val, sizeof(mfp_val))) {
                                mfp_capable = (mfp_val[0] == '1');
                            }
                            extract_inspect_uptime(line, uptime_str,
                                                   sizeof(uptime_str));
                            got_line = true;
                        }
                        lp = 0;
                    }
                } else if (lp < 511) {
                    line[lp++] = c;
                }
            }
        }

        if (!ctx->inspect_active) break;

        if (got_line && bsp_display_lock(50)) {
            if (ctx->inspect_info_labels &&
                i - 1 < ctx->inspect_label_count &&
                ctx->inspect_info_labels[i - 1] &&
                lv_obj_is_valid(ctx->inspect_info_labels[i - 1]) &&
                ctx->networks &&
                i - 1 < ctx->network_count) {

                wifi_network_t *net = &ctx->networks[i - 1];
                const char *vendor_display =
                    (net->vendor[0] != '\0') ? net->vendor : "-";
                const char *up_text = uptime_str[0] ? uptime_str : "?";

                lv_label_set_recolor(ctx->inspect_info_labels[i - 1], true);
                const char *rssi_col_s  = net->rssi > -50 ? "#55DD55" : (net->rssi > -70 ? "#FFAA00" : "#FF5555");
                const char *band_col_s  = strstr(net->band, "5") ? "#CC66FF" : "#FFAA33";
                const char *sec_col_s   = strstr(net->security, "WPA3") ? "#55DD55" :
                                          strstr(net->security, "WPA2") ? "#00CCCC" : "#FF6666";
                lv_label_set_text_fmt(ctx->inspect_info_labels[i - 1],
                    "#5599FF %s#  |  #5599FF CH%d#  |  %s %s#  |  %s %s#  |  %s %d dBm#\n%s  |  Uptime: %s\nVendor: %s",
                    net->bssid, net->channel,
                    band_col_s, net->band,
                    sec_col_s, net->security,
                    rssi_col_s, net->rssi,
                    mfp_capable ? "#FF5555 MFP On#" : "#55DD55 MFP Off#",
                    up_text, vendor_display);
            }
            bsp_display_unlock();
        } else if (!got_line) {
            ESP_LOGD(TAG, "[%s] inspect %d: no response", uart_name, i);
        }

        // Small yield so the UI/UART driver can breathe.
        vTaskDelay(pdMS_TO_TICKS(20));
    }

    ESP_LOGI(TAG, "[%s] inspect task finished (active=%d)",
             uart_name, ctx->inspect_active);

    heap_caps_free(rx);
    heap_caps_free(line);

    ctx->inspect_task = NULL;
    ctx->inspect_active = false;
    vTaskDeleteWithCaps(NULL);
}

static void cancel_observer_inspect_task(tab_context_t *ctx)
{
    if (!ctx) return;
    if (!ctx->observer_inspect_task && !ctx->observer_inspect_active) return;
    ctx->observer_inspect_active = false;
    for (int w = 0; w < 25 && ctx->observer_inspect_task != NULL; w++) {
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

static void inspect_observer_task(void *arg)
{
    tab_id_t tab = (tab_id_t)(uintptr_t)arg;
    tab_context_t *ctx = get_ctx_for_tab(tab);
    if (!ctx) { vTaskDeleteWithCaps(NULL); return; }

    uart_port_t port = uart_port_for_tab(tab);
    const char *uart_name = tab_transport_name(tab);

    char *rx   = heap_caps_malloc(UART_BUF_SIZE, MALLOC_CAP_SPIRAM);
    char *line = heap_caps_malloc(512,           MALLOC_CAP_SPIRAM);
    if (!rx || !line) {
        if (rx) heap_caps_free(rx);
        if (line) heap_caps_free(line);
        ctx->observer_inspect_task = NULL;
        ctx->observer_inspect_active = false;
        vTaskDeleteWithCaps(NULL);
        return;
    }

    int total = ctx->observer_inspect_label_count;
    ESP_LOGI(TAG, "[%s] observer inspect task started for %d networks", uart_name, total);

    for (int i = 0; ctx->observer_inspect_active && i < total; i++) {
        if (!ctx->observer_networks || i >= ctx->observer_network_count) break;
        observer_network_t *net = &ctx->observer_networks[i];

        // Skip if already inspected
        if (net->inspected) {
            // Still update label in case table was just rebuilt
            if (bsp_display_lock(50)) {
                if (ctx->observer_inspect_info_labels &&
                    i < ctx->observer_inspect_label_count &&
                    ctx->observer_inspect_info_labels[i] &&
                    lv_obj_is_valid(ctx->observer_inspect_info_labels[i])) {
                    const char *up_text = net->uptime[0] ? net->uptime : "?";
                    lv_label_set_recolor(ctx->observer_inspect_info_labels[i], true);
                    const char *rssi_col_oa = net->rssi > -50 ? "#55DD55" : (net->rssi > -70 ? "#FFAA00" : "#FF5555");
                    const char *band_col_oa = strstr(net->band, "5") ? "#CC66FF" : "#FFAA33";
                    lv_label_set_text_fmt(ctx->observer_inspect_info_labels[i],
                        "#5599FF %s#  |  #5599FF CH%d#  |  %s %s#  |  %s %d dBm#\n%s  |  Uptime: %s\nVendor: %s",
                        net->bssid, net->channel,
                        band_col_oa, net->band,
                        rssi_col_oa, net->rssi,
                        net->mfp_capable ? "#FF5555 MFP On#" : "#55DD55 MFP Off#",
                        up_text, net->vendor[0] ? net->vendor : "-");
                }
                bsp_display_unlock();
            }
            continue;
        }

        if (tab == TAB_USB && usb_cdc_handle) {
            usbh_cdc_flush_rx_buffer(usb_cdc_handle);
        } else {
            uart_flush(port);
        }

        char cmd[40];
        int  n = snprintf(cmd, sizeof(cmd), "inspect_network %d\r\n", net->scan_index);
        transport_write_bytes_tab(tab, port, cmd, n);

        bool       got_line = false;
        int        lp = 0;
        TickType_t t0 = xTaskGetTickCount();
        bool       mfp_capable = false;
        char       uptime_str[64] = {0};

        while (ctx->observer_inspect_active && !got_line &&
               (xTaskGetTickCount() - t0) < pdMS_TO_TICKS(1500)) {
            int rxlen = transport_read_bytes_tab(tab, port, rx,
                                                 UART_BUF_SIZE - 1,
                                                 pdMS_TO_TICKS(100));
            if (rxlen <= 0) continue;
            rx[rxlen] = '\0';
            for (int b = 0; b < rxlen && !got_line; b++) {
                char c = rx[b];
                if (c == '\n' || c == '\r') {
                    if (lp > 0) {
                        line[lp] = '\0';
                        if (strstr(line, "[INSPECT]")) {
                            char mfp_val[8] = {0};
                            if (extract_inspect_kv(line, "mfp_capable=", mfp_val, sizeof(mfp_val)))
                                mfp_capable = (mfp_val[0] == '1');
                            extract_inspect_uptime(line, uptime_str, sizeof(uptime_str));
                            got_line = true;
                        }
                        lp = 0;
                    }
                } else if (lp < 511) {
                    line[lp++] = c;
                }
            }
        }

        if (!ctx->observer_inspect_active) break;

        if (got_line) {
            net->mfp_capable = mfp_capable;
            snprintf(net->uptime, sizeof(net->uptime), "%s", uptime_str);
            net->inspected = true;

            if (bsp_display_lock(50)) {
                if (ctx->observer_inspect_info_labels &&
                    i < ctx->observer_inspect_label_count &&
                    ctx->observer_inspect_info_labels[i] &&
                    lv_obj_is_valid(ctx->observer_inspect_info_labels[i])) {
                        const char *up_text = uptime_str[0] ? uptime_str : "?";
                    lv_label_set_recolor(ctx->observer_inspect_info_labels[i], true);
                    const char *rssi_col_ob = net->rssi > -50 ? "#55DD55" : (net->rssi > -70 ? "#FFAA00" : "#FF5555");
                    const char *band_col_ob = strstr(net->band, "5") ? "#CC66FF" : "#FFAA33";
                    lv_label_set_text_fmt(ctx->observer_inspect_info_labels[i],
                        "#5599FF %s#  |  #5599FF CH%d#  |  %s %s#  |  %s %d dBm#\n%s  |  Uptime: %s\nVendor: %s",
                        net->bssid, net->channel,
                        band_col_ob, net->band,
                        rssi_col_ob, net->rssi,
                        mfp_capable ? "#FF5555 MFP On#" : "#55DD55 MFP Off#",
                        up_text, net->vendor[0] ? net->vendor : "-");
                }
                bsp_display_unlock();
            }
        }

        vTaskDelay(pdMS_TO_TICKS(20));
    }

    ESP_LOGI(TAG, "[%s] observer inspect task finished", uart_name);
    heap_caps_free(rx);
    heap_caps_free(line);
    ctx->observer_inspect_task = NULL;
    ctx->observer_inspect_active = false;
    vTaskDeleteWithCaps(NULL);
}

// WiFi scan task
static void wifi_scan_task(void *arg)
{
    // Tab that initiated this scan (passed via arg) - results go to that tab's context.
    tab_id_t scan_tab = (tab_id_t)(uintptr_t)arg;
    tab_context_t *ctx = get_ctx_for_tab(scan_tab);
    const char *uart_name = tab_transport_name(scan_tab);

    if (!ctx || !ctx->networks) {
        ESP_LOGE(TAG, "wifi_scan_task: ctx or ctx->networks is NULL for tab %d", scan_tab);
        vTaskDelete(NULL);
        return;
    }

    ESP_LOGI(TAG, "Starting WiFi scan task for tab %d (%s)", scan_tab, uart_name);

    // Clear previous results in this tab's context
    ctx->network_count = 0;
    memset(ctx->networks, 0, sizeof(wifi_network_t) * MAX_NETWORKS);

    // Get the UART for this tab
    uart_port_t uart_port = uart_port_for_tab(scan_tab);

    ESP_LOGI(TAG, "[%s] Using transport on port %d for scan", uart_name, uart_port);

    // Flush buffer before scan
    if (scan_tab == TAB_USB && usb_cdc_handle) {
        usbh_cdc_flush_rx_buffer(usb_cdc_handle);
        ESP_LOGI(TAG, "[USB] Flushed RX buffer before scan");
    } else {
        uart_flush(uart_port);
    }

    // Send scan command to the correct transport
    log_memory_stats("TX-scan");
    transport_write_bytes_tab(scan_tab, uart_port, "scan_networks\r\n", 15);
    ESP_LOGI(TAG, "[%s] Sent command: scan_networks", tab_transport_name(scan_tab));

    // Buffer for receiving data
    static char rx_buffer[UART_BUF_SIZE];
    static char line_buffer[512];
    int line_pos = 0;
    bool scan_complete = false;

    TickType_t start_time = xTaskGetTickCount();
    TickType_t timeout_ticks = pdMS_TO_TICKS(UART_RX_TIMEOUT);

    while (!scan_complete && (xTaskGetTickCount() - start_time) < timeout_ticks) {
        int len = transport_read_bytes_tab(scan_tab, uart_port, rx_buffer, UART_BUF_SIZE - 1, pdMS_TO_TICKS(100));

        if (len > 0) {
            rx_buffer[len] = '\0';
            ESP_LOGD(TAG, "Received %d bytes", len);

            // Process received data character by character
            for (int i = 0; i < len; i++) {
                char c = rx_buffer[i];

                if (c == '\n' || c == '\r') {
                    if (line_pos > 0) {
                        line_buffer[line_pos] = '\0';
                        ESP_LOGD(TAG, "Line: %s", line_buffer);

                        // Check for scan complete marker
                        if (strstr(line_buffer, "Scan results printed") != NULL) {
                            scan_complete = true;
                            ESP_LOGI(TAG, "Scan complete marker received");
                            break;
                        }

                        // Try to parse network line
                        if (line_buffer[0] == '"' && ctx->network_count < MAX_NETWORKS) {
                            wifi_network_t net;
                            if (parse_network_line(line_buffer, &net)) {
                                ctx->networks[ctx->network_count] = net;
                                ctx->network_count++;
                                ESP_LOGI(TAG, "[%s] Parsed network %d: %s (%s) %s",
                                         uart_name, net.index, net.ssid, net.bssid, net.band);
                            }
                        }

                        line_pos = 0;
                    }
                } else if (line_pos < sizeof(line_buffer) - 1) {
                    line_buffer[line_pos++] = c;
                }
            }
        }
    }

    if (!scan_complete) {
        ESP_LOGW(TAG, "[%s] Scan timed out", uart_name);
    }

    log_memory_stats("RX-scan");
    ESP_LOGI(TAG, "[%s] Scan finished. Found %d networks", uart_name, ctx->network_count);

    // Update UI on main thread
    bsp_display_lock(0);

    // Hide spinner
    if (ctx->spinner) {
        lv_obj_add_flag(ctx->spinner, LV_OBJ_FLAG_HIDDEN);
    }

    // Update status
    if (ctx->scan_status_label) {
        if (scan_complete) {
            lv_label_set_text_fmt(ctx->scan_status_label, "Found %d networks", ctx->network_count);
        } else {
            lv_label_set_text(ctx->scan_status_label, "Scan timed out");
        }
    }

    // Update network list
    if (ctx->network_list) {
        lv_obj_clean(ctx->network_list);

        // Reallocate per-row label pointer array in PSRAM so the inspect
        // task can address each row's info_label by 0-based index.
        if (ctx->inspect_info_labels) {
            heap_caps_free(ctx->inspect_info_labels);
            ctx->inspect_info_labels = NULL;
        }
        ctx->inspect_label_count = ctx->network_count;
        if (ctx->network_count > 0) {
            ctx->inspect_info_labels = heap_caps_calloc(
                ctx->network_count, sizeof(lv_obj_t *), MALLOC_CAP_SPIRAM);
            if (!ctx->inspect_info_labels) {
                ESP_LOGW(TAG, "Failed to allocate inspect_info_labels in PSRAM");
                ctx->inspect_label_count = 0;
            }
        }

        for (int i = 0; i < ctx->network_count; i++) {
            wifi_network_t *net = &ctx->networks[i];

            // Create list item with horizontal layout (checkbox + text container)
            lv_obj_t *item = lv_obj_create(ctx->network_list);
            lv_obj_set_size(item, lv_pct(100), LV_SIZE_CONTENT);
            lv_obj_set_style_pad_all(item, 8, 0);
            lv_obj_set_style_bg_color(item, lv_color_hex(0x2D2D2D), 0);
            lv_obj_set_style_bg_color(item, lv_color_hex(0x3A3A3A), LV_STATE_PRESSED);
            lv_obj_set_style_border_width(item, 0, 0);
            lv_obj_set_style_radius(item, 8, 0);
            lv_obj_set_flex_flow(item, LV_FLEX_FLOW_ROW);
            lv_obj_set_flex_align(item, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
            lv_obj_set_style_pad_column(item, 12, 0);
            lv_obj_add_flag(item, LV_OBJ_FLAG_CLICKABLE);

            // Checkbox (on the left) - explicit size for better touch accuracy
            lv_obj_t *cb = lv_checkbox_create(item);
            lv_checkbox_set_text(cb, "");  // Empty text - we use separate labels
            lv_obj_set_size(cb, 50, 50);  // Explicit size for touch target
            lv_obj_set_ext_click_area(cb, 15);  // Extend touch area by 15px
            lv_obj_set_style_pad_all(cb, 4, 0);
            lv_obj_set_style_align(cb, LV_ALIGN_LEFT_MID, 0);  // Center vertically in row
            // Style the indicator - dark when unchecked, green when checked
            lv_obj_set_style_bg_color(cb, lv_color_hex(0x3D3D3D), LV_PART_INDICATOR);
            lv_obj_set_style_bg_color(cb, lv_color_hex(0x4CAF50), LV_PART_INDICATOR | LV_STATE_CHECKED);
            lv_obj_set_style_border_color(cb, lv_color_hex(0x888888), LV_PART_INDICATOR);
            lv_obj_set_style_border_width(cb, 2, LV_PART_INDICATOR);
            lv_obj_set_style_radius(cb, 4, LV_PART_INDICATOR);
            // Pass 0-based index as user data
            lv_obj_add_event_cb(cb, network_checkbox_event_cb, LV_EVENT_VALUE_CHANGED, (void*)(intptr_t)i);
            lv_obj_add_event_cb(item, network_item_event_cb, LV_EVENT_CLICKED, cb);

            // Text container (vertical layout for SSID and info)
            lv_obj_t *text_cont = lv_obj_create(item);
            lv_obj_set_size(text_cont, lv_pct(85), LV_SIZE_CONTENT);
            lv_obj_set_style_bg_opa(text_cont, LV_OPA_TRANSP, 0);
            lv_obj_set_style_border_width(text_cont, 0, 0);
            lv_obj_set_style_pad_all(text_cont, 0, 0);
            lv_obj_set_flex_flow(text_cont, LV_FLEX_FLOW_COLUMN);
            lv_obj_set_style_pad_row(text_cont, 4, 0);
            lv_obj_clear_flag(text_cont, LV_OBJ_FLAG_CLICKABLE);  // Don't steal clicks

            // SSID (or "Hidden" if empty)
            lv_obj_t *ssid_label = lv_label_create(text_cont);
            if (strlen(net->ssid) > 0) {
                lv_label_set_text(ssid_label, net->ssid);
            } else {
                lv_label_set_text(ssid_label, "(Hidden)");
            }
            lv_obj_set_style_text_font(ssid_label, &lv_font_montserrat_18, 0);
            lv_obj_set_style_text_color(ssid_label, lv_color_hex(0xFFFFFF), 0);

            // BSSID, Band, Security, RSSI and vendor
            lv_obj_t *info_label = lv_label_create(text_cont);
            const char *vendor_display = strlen(net->vendor) > 0 ? net->vendor : "-";
            const char *rssi_col   = net->rssi > -50 ? "#55DD55" : (net->rssi > -70 ? "#FFAA00" : "#FF5555");
            const char *band_col   = strstr(net->band, "5") ? "#CC66FF" : "#FFAA33";
            const char *sec_col    = strstr(net->security, "WPA3") ? "#55DD55" :
                                     strstr(net->security, "WPA2") ? "#00CCCC" : "#FF6666";
            lv_label_set_recolor(info_label, true);
            lv_label_set_text_fmt(info_label,
                "#5599FF %s#  |  #5599FF CH%d#  |  %s %s#  |  %s %s#  |  %s %d dBm#\nVendor: %s",
                net->bssid, net->channel,
                band_col, net->band,
                sec_col, net->security,
                rssi_col, net->rssi,
                vendor_display);
            lv_obj_set_style_text_font(info_label, &lv_font_montserrat_12, 0);
            lv_obj_set_style_text_color(info_label, lv_color_hex(0x888888), 0);

            if (ctx->inspect_info_labels && i < ctx->inspect_label_count) {
                ctx->inspect_info_labels[i] = info_label;
            }
        }
    }

    // Re-enable scan button
    if (ctx->scan_btn) {
        lv_obj_clear_state(ctx->scan_btn, LV_STATE_DISABLED);
    }

    // Hide small spinner
    if (ctx->spinner) {
        lv_obj_add_flag(ctx->spinner, LV_OBJ_FLAG_HIDDEN);
    }

    // Hide large centered overlay only if user is still on the same tab
    if (current_tab == scan_tab) {
        hide_scan_overlay();
    }

    ctx->scan_in_progress = false;
    ESP_LOGI(TAG, "[%s] Stored %d scan results in tab %d context",
             uart_name, ctx->network_count, scan_tab);

    bsp_display_unlock();

    // Kick off the async inspect task in PSRAM. It walks 1..N calling
    // `inspect_network <i>` and decorates each row with MFP/uptime info.
    // It will be cancelled cooperatively before any attack starts.
    if (scan_complete && ctx->network_count > 0 && ctx->inspect_info_labels) {
        cancel_inspect_task(ctx);
        ctx->inspect_tab    = (int)scan_tab;
        ctx->inspect_active = true;
        BaseType_t ok = xTaskCreateWithCaps(
            inspect_networks_task,
            "inspect_net",
            8192,
            (void *)(uintptr_t)scan_tab,
            4,
            &ctx->inspect_task,
            MALLOC_CAP_SPIRAM);
        if (ok != pdPASS) {
            ESP_LOGE(TAG, "[%s] Failed to spawn inspect_networks_task", uart_name);
            ctx->inspect_active = false;
            ctx->inspect_task = NULL;
        }
    }

    // Delete this task
    vTaskDelete(NULL);
}

// Show centered scanning overlay with large spinner
static void show_scan_overlay(void) {
    if (scan_overlay) return;

    scan_overlay = lv_obj_create(lv_scr_act());
    lv_obj_remove_style_all(scan_overlay);
    lv_obj_set_size(scan_overlay, lv_pct(100), lv_pct(100));
    lv_obj_set_style_bg_color(scan_overlay, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(scan_overlay, LV_OPA_70, 0);
    lv_obj_add_flag(scan_overlay, LV_OBJ_FLAG_CLICKABLE);  // Block clicks on elements below

    // Large centered spinner
    lv_obj_t *spin = lv_spinner_create(scan_overlay);
    lv_obj_set_size(spin, 100, 100);
    lv_spinner_set_anim_params(spin, 1000, 200);
    lv_obj_center(spin);

    // "Scanning..." label below spinner
    lv_obj_t *label = lv_label_create(scan_overlay);
    lv_label_set_text(label, "Scanning...");
    lv_obj_set_style_text_font(label, &lv_font_montserrat_24, 0);
    lv_obj_set_style_text_color(label, lv_color_hex(0xFFFFFF), 0);
    lv_obj_align(label, LV_ALIGN_CENTER, 0, 80);
}

// Hide scanning overlay
static void hide_scan_overlay(void) {
    if (scan_overlay) {
        lv_obj_del(scan_overlay);
        scan_overlay = NULL;
    }
}

