        lv_obj_t *list_hosts_label = lv_label_create(nmap_list_hosts_btn);
        lv_label_set_text(list_hosts_label, "List Hosts");
        lv_obj_set_style_text_font(list_hosts_label, &lv_font_montserrat_16, 0);
