    if (idx < 0 || idx >= karma_probe_count) return;

    karma_selected_probe_idx = idx;
    ESP_LOGI(TAG, "Karma: Selected probe %d: %s", idx, karma_probes[idx].ssid);

    lv_obj_t *container = get_current_tab_container();
    if (!container) return;

    // Create overlay
