    lv_obj_set_size(ctx->phishing_portal_popup, 600, 480);
    lv_obj_center(ctx->phishing_portal_popup);
    lv_obj_set_style_bg_color(ctx->phishing_portal_popup, lv_color_hex(0x1A1A2A), 0);
