static bool compromised_start_cleanup_operation(tab_context_t *ctx,
                                                compromised_cleanup_task_args_t *task_args)
{
    if (!ctx || !task_args || task_args->path_count <= 0) {
        return false;
    }

    ctx->compromised_cleanup_running = true;
    show_compromised_cleanup_popup(ctx, task_args->kind, task_args->action);

    if (ctx->compromised_cleanup_status_label) {
        if (task_args->action == COMPROMISED_CLEANUP_ACTION_DELETE && task_args->path_count == 1) {
            lv_label_set_text(ctx->compromised_cleanup_status_label, "Deleting file...");
        } else {
            lv_label_set_text_fmt(ctx->compromised_cleanup_status_label,
                                  "Deleting %d file(s)...", task_args->path_count);
        }
    }
    if (ctx->compromised_cleanup_log_label) {
        lv_label_set_text(ctx->compromised_cleanup_log_label,
                          task_args->action == COMPROMISED_CLEANUP_ACTION_DELETE
                              ? "Starting delete..."
                              : "Starting clean...");
    }
    lv_refr_now(NULL);

    if (xTaskCreate(compromised_cleanup_task, "comp_clean", 8192, task_args, 5,
                    &ctx->compromised_cleanup_task) != pdTRUE) {
        ESP_LOGW(TAG, "Failed to start compromised file task");
        ctx->compromised_cleanup_running = false;
        ctx->compromised_cleanup_task = NULL;
        close_compromised_cleanup_popup(ctx);
        return false;
    }

    return true;
}

static void compromised_cleanup_async_refresh(void *user_data)
{
    tab_context_t *ctx = (tab_context_t *)user_data;
    if (!ctx) {
        return;
    }

    compromised_file_kind_t kind = ctx->compromised_cleanup_kind;
    lv_obj_t **page_slot = compromised_page_slot_for_kind(ctx, kind);
    bool same_tab = (tab_id_for_ctx(ctx) == current_tab);
    bool page_visible = (same_tab && page_slot && *page_slot && ctx->current_visible_page == *page_slot);

    close_compromised_cleanup_popup(ctx);

    if (page_visible) {
        if (kind == COMPROMISED_FILE_KIND_HANDSHAKE) {
            show_handshakes_page();
        } else if (kind == COMPROMISED_FILE_KIND_WARDRIVE) {
            show_wardrive_files_page();
        } else if (kind == COMPROMISED_FILE_KIND_EVIL_TWIN) {
            show_evil_twin_passwords_page();
        } else if (kind == COMPROMISED_FILE_KIND_PORTAL) {
            show_portal_data_page();
        } else if (kind == COMPROMISED_FILE_KIND_PCAP_CAPTURE) {
            show_pcap_captures_page();
        }
    } else if (page_slot && *page_slot) {
        lv_obj_del(*page_slot);
        *page_slot = NULL;
    }

    if (kind == COMPROMISED_FILE_KIND_HANDSHAKE) {
        ctx->home_meta_last_update_ms = 0;
        if (same_tab) {
            trigger_home_meta_refresh(ctx, true);
        }
    }
}

// Runs on the LVGL thread (via lv_async_call) after the background loader finished.
// Rebuilds the file page so it renders from the now-populated ctx cache.
static void compromised_files_load_async_render(void *user_data)
{
    tab_context_t *ctx = (tab_context_t *)user_data;
    if (!ctx) {
        return;
    }

    compromised_file_kind_t kind = ctx->compromised_files_load_kind;
    lv_obj_t **page_slot = compromised_page_slot_for_kind(ctx, kind);
    bool same_tab = (tab_id_for_ctx(ctx) == current_tab);
    bool page_visible = (same_tab && page_slot && *page_slot &&
                         ctx->current_visible_page == *page_slot);

    if (!page_visible) {
        // User navigated away while loading; drop the staged flag so the next open
        // performs a fresh load instead of rendering stale cache.
        ctx->compromised_files_loaded = false;
        return;
    }

    if (kind == COMPROMISED_FILE_KIND_HANDSHAKE) {
        show_handshakes_page();
    } else if (kind == COMPROMISED_FILE_KIND_WARDRIVE) {
        show_wardrive_files_page();
    } else if (kind == COMPROMISED_FILE_KIND_PCAP_CAPTURE) {
        show_pcap_captures_page();
    } else {
        ctx->compromised_files_loaded = false;
    }
}

// Background task: fetch the file listing over UART (off the UI thread so the page
// spinner keeps animating), then ask the LVGL thread to rebuild the page.
static void compromised_files_load_task(void *arg)
{
    tab_context_t *ctx = (tab_context_t *)arg;
    if (!ctx) {
        vTaskDelete(NULL);
        return;
    }

    tab_id_t active_tab = tab_id_for_ctx(ctx);
    uart_port_t uart_port = uart_port_for_tab(active_tab);
    compromised_file_kind_t kind = ctx->compromised_files_load_kind;

    if (kind == COMPROMISED_FILE_KIND_HANDSHAKE) {
        ctx->home_handshake_count = compromised_load_handshake_files(ctx, active_tab, uart_port);
    } else if (kind == COMPROMISED_FILE_KIND_PCAP_CAPTURE) {
        (void)compromised_load_pcap_capture_files(ctx, active_tab, uart_port);
        for (int i = 0; i < ctx->wardrive_wigle_file_count; i++) {
            wardrive_wigle_file_t *file = &ctx->wardrive_wigle_files[i];
            file->tab5_synced = file->path[0] &&
                                janos_sync_state_has_local_copy(active_tab, file->path);
        }
    } else {
        (void)compromised_load_wardrive_files(ctx, active_tab, uart_port);
        if (kind == COMPROMISED_FILE_KIND_WARDRIVE) {
            // Also pull the upload journal so files already uploaded and moved out
            // of the working dir still show up as "uploaded" history on the page.
            wardrive_load_upload_state_from_command(ctx, active_tab, uart_port, 10000);
        }
    }

    ctx->compromised_files_loaded = true;
    ctx->compromised_files_loading = false;
    ctx->compromised_files_load_task = NULL;
    lv_async_call(compromised_files_load_async_render, ctx);
    vTaskDelete(NULL);
}

static void wardrive_cleanup_close_cb(lv_event_t *e)
{
    tab_context_t *ctx = (tab_context_t *)lv_event_get_user_data(e);
    if (!ctx) {
        ctx = get_current_ctx();
    }
    if (!ctx || ctx->compromised_cleanup_running) {
        return;
    }
    close_compromised_cleanup_popup(ctx);
}

static bool wardrive_cleanup_start(tab_context_t *ctx, const char *service,
                                   const char *status, bool move)
{
    if (!ctx || ctx->compromised_cleanup_running || !service || !status) {
        return false;
    }

    wardrive_cleanup_task_args_t *args = calloc(1, sizeof(*args));
    if (!args) {
        return false;
    }
    args->ctx = ctx;
    args->move = move;
    snprintf(args->service, sizeof(args->service), "%s", service);
    snprintf(args->status, sizeof(args->status), "%s", status);

    ctx->compromised_cleanup_running = true;
    ctx->compromised_cleanup_kind = COMPROMISED_FILE_KIND_WARDRIVE;
    ctx->compromised_cleanup_action = COMPROMISED_CLEANUP_ACTION_CLEAN;
    snprintf(ctx->wardrive_cleanup_service, sizeof(ctx->wardrive_cleanup_service), "%s", service);
    snprintf(ctx->wardrive_cleanup_status, sizeof(ctx->wardrive_cleanup_status), "%s", status);
    ctx->wardrive_cleanup_dry_run_ready = false;
    ctx->compromised_cleanup_log_buffer[0] = '\0';

    if (!ctx->compromised_cleanup_overlay) {
        show_compromised_cleanup_popup(ctx, COMPROMISED_FILE_KIND_WARDRIVE,
                                       COMPROMISED_CLEANUP_ACTION_CLEAN);
    }
    if (ctx->compromised_cleanup_status_label) {
        lv_label_set_text_fmt(ctx->compromised_cleanup_status_label,
                              move ? "Moving matched wardrive files..." :
                                     "Dry-run: finding wardrive files to move...");
    }
    if (ctx->compromised_cleanup_spinner) {
        lv_obj_clear_flag(ctx->compromised_cleanup_spinner, LV_OBJ_FLAG_HIDDEN);
    }
    if (ctx->compromised_cleanup_log_label) {
        lv_label_set_text(ctx->compromised_cleanup_log_label,
                          move ? "Starting wardrive_cleanup move..." :
                                 "Starting wardrive_cleanup dry-run...");
    }
    if (ctx->compromised_cleanup_move_btn) {
        lv_obj_add_flag(ctx->compromised_cleanup_move_btn, LV_OBJ_FLAG_HIDDEN);
    }
    lv_refr_now(NULL);

    if (xTaskCreate(wardrive_cleanup_task, "wd_clean", 8192, args, 5,
                    &ctx->compromised_cleanup_task) != pdTRUE) {
        ctx->compromised_cleanup_running = false;
        ctx->compromised_cleanup_task = NULL;
        free(args);
        return false;
    }
    return true;
}

static void wardrive_cleanup_move_confirm_cb(lv_event_t *e)
{
    tab_context_t *ctx = (tab_context_t *)lv_event_get_user_data(e);
    if (!ctx) {
        ctx = get_current_ctx();
    }
    if (!ctx || !ctx->wardrive_cleanup_dry_run_ready) {
        return;
    }
    wardrive_cleanup_start(ctx,
                           ctx->wardrive_cleanup_service[0] ? ctx->wardrive_cleanup_service : "all",
                           ctx->wardrive_cleanup_status[0] ? ctx->wardrive_cleanup_status : "done",
                           true);
}

static void wardrive_cleanup_dry_run_cb(lv_event_t *e)
{
    tab_context_t *ctx = (tab_context_t *)lv_event_get_user_data(e);
    if (!ctx) {
        ctx = get_current_ctx();
    }
    wardrive_cleanup_start(ctx, "all", "done", false);
}

static void wardrive_cleanup_task(void *arg)
{
    wardrive_cleanup_task_args_t *args = (wardrive_cleanup_task_args_t *)arg;
    if (!args || !args->ctx) {
        free(args);
        vTaskDelete(NULL);
        return;
    }

    tab_context_t *ctx = args->ctx;
    tab_id_t tab = tab_id_for_ctx(ctx);
    uart_port_t uart_port = uart_port_for_tab(tab);

    // On the actual move, append a session stamp (from the RTC-seeded system
    // clock) so the module archives into a unique subfolder
    // (.../<service>/<status>/YYYY-MM-DD_HHMMSS). A per-run stamp avoids name
    // collisions even when wN.log restarts at w1 the same day. Dry-run sends
    // no destination.
    char cmd[96];
    if (args->move) {
        time_t now = time(NULL);
        struct tm t;
        localtime_r(&now, &t);
        if (t.tm_year + 1900 >= 2024) {
            char sessbuf[24];
            snprintf(sessbuf, sizeof(sessbuf), "%04d-%02d-%02d_%02d%02d%02d",
                     (t.tm_year + 1900) % 10000, (t.tm_mon + 1) % 100, t.tm_mday % 100,
                     t.tm_hour % 100, t.tm_min % 100, t.tm_sec % 100);
            snprintf(cmd, sizeof(cmd), "wardrive_cleanup %s %s move %s",
                     args->service, args->status, sessbuf);
        } else {
            // No valid clock yet - fall back to the plain move (legacy destination).
            snprintf(cmd, sizeof(cmd), "wardrive_cleanup %s %s move",
                     args->service, args->status);
        }
    } else {
        snprintf(cmd, sizeof(cmd), "wardrive_cleanup %s %s",
                 args->service, args->status);
    }

    bool usb_lock_set = false;
    compromised_transport_lock_begin(tab, uart_port, &usb_lock_set);
    transport_write_bytes_tab(tab, uart_port, cmd, strlen(cmd));
    transport_write_bytes_tab(tab, uart_port, "\r\n", 2);
    ESP_LOGI(TAG, "[%s] sent %s", tab_transport_name(tab), cmd);

    char *rx = heap_caps_malloc(16384, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    size_t rx_size = 16384;
    if (!rx) {
        rx_size = 4096;
        rx = malloc(rx_size);
    }
    if (!rx) {
        compromised_transport_lock_end(usb_lock_set);
        bsp_display_lock(0);
        if (ctx->compromised_cleanup_spinner) {
            lv_obj_add_flag(ctx->compromised_cleanup_spinner, LV_OBJ_FLAG_HIDDEN);
        }
        if (ctx->compromised_cleanup_status_label) {
            lv_label_set_text(ctx->compromised_cleanup_status_label,
                              "Cleanup failed: not enough memory for response buffer.");
        }
        bsp_display_unlock();
        ctx->compromised_cleanup_running = false;
        ctx->compromised_cleanup_task = NULL;
        free(args);
        vTaskDelete(NULL);
        return;
    }
    rx[0] = '\0';

    int total_len = 0;
    int elapsed_ms = 0;
    int empty_reads = 0;
    const int poll_ms = 250;
    while (elapsed_ms < 120000 && total_len < (int)rx_size - 1) {
        int len = transport_read_bytes_tab(tab, uart_port, rx + total_len,
                                           rx_size - 1 - total_len,
                                           pdMS_TO_TICKS(poll_ms));
        if (len > 0) {
            total_len += len;
            rx[total_len] = '\0';
            empty_reads = 0;
            if (strstr(rx, "[WARD_CLEANUP] END") != NULL ||
                strstr(rx, "Usage: wardrive_cleanup") != NULL ||
                strstr(rx, "Unrecognized command") != NULL) {
                break;
            }
        } else {
            empty_reads++;
            if (empty_reads >= 8 && strstr(rx, "[WARD_CLEANUP] BEGIN") == NULL) {
                break;
            }
        }
        elapsed_ms += poll_ms;
    }
    compromised_transport_lock_end(usb_lock_set);

    int scanned = 0, matched = 0, moved = 0, failed = 0, dry_run = args->move ? 0 : 1;
    int shown = 0;
    char *line = strtok(rx, "\n\r");
    while (line) {
        while (isspace((unsigned char)*line)) line++;
        if (strstr(line, "[WARD_CLEANUP] filename=") != NULL) {
            char filename[96] = {0};
            char action[24] = {0};
            wardrive_marker_get_value(line, "filename", filename, sizeof(filename));
            wardrive_marker_get_value(line, "action", action, sizeof(action));
            char log_line[160];
            snprintf(log_line, sizeof(log_line), "%s %s",
                     action[0] ? action : "matched", filename[0] ? filename : "(file)");
            bsp_display_lock(0);
            compromised_cleanup_append_log(ctx, log_line);
            bsp_display_unlock();
            shown++;
        } else if (strstr(line, "[WARD_CLEANUP] SUMMARY") != NULL) {
            scanned = wardrive_marker_get_int(line, "scanned", 0);
            matched = wardrive_marker_get_int(line, "matched", 0);
            moved = wardrive_marker_get_int(line, "moved", 0);
            failed = wardrive_marker_get_int(line, "failed", 0);
            dry_run = wardrive_marker_get_int(line, "dry_run", dry_run);
        }
        line = strtok(NULL, "\n\r");
    }
    if (shown == 0 && rx[0] != '\0') {
        bsp_display_lock(0);
        compromised_cleanup_append_log(ctx, rx);
        bsp_display_unlock();
    }

    free(rx);

    bsp_display_lock(0);
    if (ctx->compromised_cleanup_spinner) {
        lv_obj_add_flag(ctx->compromised_cleanup_spinner, LV_OBJ_FLAG_HIDDEN);
    }
    if (ctx->compromised_cleanup_status_label) {
        if (dry_run) {
            if (matched > 0) {
                lv_label_set_text_fmt(ctx->compromised_cleanup_status_label,
                                      "Dry-run complete. Scanned: %d, matched: %d. Tap Move matched to archive.",
                                      scanned, matched);
            } else {
                lv_label_set_text_fmt(ctx->compromised_cleanup_status_label,
                                      "Dry-run complete. Scanned: %d, nothing to move, failed: %d",
                                      scanned, failed);
            }
        } else {
            lv_label_set_text_fmt(ctx->compromised_cleanup_status_label,
                                  "Move complete. Matched: %d, moved: %d, failed: %d",
                                  matched, moved, failed);
            ctx->compromised_files_loaded = false;
        }
    }
    if (dry_run && matched > 0 && ctx->compromised_cleanup_move_btn) {
        ctx->wardrive_cleanup_dry_run_ready = true;
        lv_obj_clear_flag(ctx->compromised_cleanup_move_btn, LV_OBJ_FLAG_HIDDEN);
    }
    bsp_display_unlock();

    ctx->compromised_cleanup_running = false;
    ctx->compromised_cleanup_task = NULL;
    free(args);
    vTaskDelete(NULL);
}

static void wardrive_fix_task(void *arg)
{
    wardrive_fix_task_args_t *args = (wardrive_fix_task_args_t *)arg;
    if (!args || !args->ctx) {
        free(args);
        vTaskDelete(NULL);
        return;
    }

    tab_context_t *ctx = args->ctx;
    tab_id_t tab = tab_id_for_ctx(ctx);
    uart_port_t uart_port = uart_port_for_tab(tab);

    char cmd[128];
    snprintf(cmd, sizeof(cmd), "wardrive_fix %s", args->file);

    bool usb_lock_set = false;
    compromised_transport_lock_begin(tab, uart_port, &usb_lock_set);
    transport_write_bytes_tab(tab, uart_port, cmd, strlen(cmd));
    transport_write_bytes_tab(tab, uart_port, "\r\n", 2);
    ESP_LOGI(TAG, "[%s] sent %s", tab_transport_name(tab), cmd);

    char *rx = heap_caps_malloc(8192, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    size_t rx_size = 8192;
    if (!rx) {
        rx_size = 4096;
        rx = malloc(rx_size);
    }
    if (!rx) {
        compromised_transport_lock_end(usb_lock_set);
        bsp_display_lock(0);
        if (ctx->compromised_cleanup_spinner) {
            lv_obj_add_flag(ctx->compromised_cleanup_spinner, LV_OBJ_FLAG_HIDDEN);
        }
        if (ctx->compromised_cleanup_status_label) {
            lv_label_set_text(ctx->compromised_cleanup_status_label,
                              "Fix failed: not enough memory for response buffer.");
        }
        bsp_display_unlock();
        ctx->compromised_cleanup_running = false;
        ctx->compromised_cleanup_task = NULL;
        free(args);
        vTaskDelete(NULL);
        return;
    }
    rx[0] = '\0';

    int total_len = 0;
    int elapsed_ms = 0;
    int empty_reads = 0;
    const int poll_ms = 250;
    while (elapsed_ms < 120000 && total_len < (int)rx_size - 1) {
        int len = transport_read_bytes_tab(tab, uart_port, rx + total_len,
                                           rx_size - 1 - total_len,
                                           pdMS_TO_TICKS(poll_ms));
        if (len > 0) {
            total_len += len;
            rx[total_len] = '\0';
            empty_reads = 0;
            if (strstr(rx, "[WARD_FIX] END") != NULL ||
                strstr(rx, "Usage: wardrive_fix") != NULL ||
                strstr(rx, "Unrecognized command") != NULL) {
                break;
            }
        } else {
            empty_reads++;
            if (empty_reads >= 8 && strstr(rx, "[WARD_FIX] BEGIN") == NULL) {
                break;
            }
        }
        elapsed_ms += poll_ms;
    }
    compromised_transport_lock_end(usb_lock_set);

    char filename[96] = {0};
    char output[96] = {0};
    char status[16] = {0};
    long size_bytes = 0;
    int kept = 0, dropped = 0, wifi = 0, ble = 0, bt = 0, bad = 0;
    bool parsed = false;

    char *line = strtok(rx, "\n\r");
    while (line) {
        while (isspace((unsigned char)*line)) line++;
        if (strstr(line, "[WARD_FIX] filename=") != NULL) {
            wardrive_marker_get_value(line, "filename", filename, sizeof(filename));
            wardrive_marker_get_value(line, "output", output, sizeof(output));
            wardrive_marker_get_value(line, "status", status, sizeof(status));
            size_bytes = wardrive_marker_get_long(line, "size", 0);
            kept = wardrive_marker_get_int(line, "kept", 0);
            dropped = wardrive_marker_get_int(line, "dropped", 0);
            wifi = wardrive_marker_get_int(line, "wifi", 0);
            ble = wardrive_marker_get_int(line, "ble", 0);
            bt = wardrive_marker_get_int(line, "bt", 0);
            bad = wardrive_marker_get_int(line, "bad", 0);
            parsed = true;
            break;
        }
        line = strtok(NULL, "\n\r");
    }

    char log_line[320];
    if (parsed) {
        char size_str[24];
        wardrive_human_size(size_bytes, size_str, sizeof(size_str));
        snprintf(log_line, sizeof(log_line),
                 "input: %s\noutput: %s\nsize: %s\nkept=%d dropped=%d\nwifi=%d ble=%d bt=%d bad=%d",
                 filename[0] ? filename : args->file,
                 output[0] ? output : "(unknown)",
                 size_str, kept, dropped, wifi, ble, bt, bad);
    } else {
        snprintf(log_line, sizeof(log_line), "%s", rx[0] ? rx : "No wardrive_fix response.");
    }

    free(rx);

    bsp_display_lock(0);
    if (ctx->compromised_cleanup_spinner) {
        lv_obj_add_flag(ctx->compromised_cleanup_spinner, LV_OBJ_FLAG_HIDDEN);
    }
    if (ctx->compromised_cleanup_status_label) {
        if (parsed && strcmp(status, "ok") == 0) {
            lv_label_set_text(ctx->compromised_cleanup_status_label,
                              "Fix complete. Original file was not changed.");
        } else if (parsed) {
            lv_label_set_text_fmt(ctx->compromised_cleanup_status_label,
                                  "Fix finished with status: %s", status[0] ? status : "unknown");
        } else {
            lv_label_set_text(ctx->compromised_cleanup_status_label,
                              "Fix failed or returned an unexpected response.");
        }
    }
    if (ctx->compromised_cleanup_log_label) {
        lv_label_set_text(ctx->compromised_cleanup_log_label, log_line);
    }
    ctx->compromised_files_loaded = false;
    bsp_display_unlock();

    ctx->compromised_cleanup_running = false;
    ctx->compromised_cleanup_task = NULL;
    free(args);
    vTaskDelete(NULL);
}

static void compromised_cleanup_task(void *arg)
{
    compromised_cleanup_task_args_t *task_args = (compromised_cleanup_task_args_t *)arg;
    if (!task_args || !task_args->ctx) {
        free(task_args);
        vTaskDelete(NULL);
        return;
    }

    tab_context_t *ctx = task_args->ctx;
    tab_id_t tab = tab_id_for_ctx(ctx);
    uart_port_t uart_port = uart_port_for_tab(tab);
    const int total = task_args->path_count;
    int success_count = 0;
    int failed_count = 0;

    bool usb_lock_set = false;
    compromised_transport_lock_begin(tab, uart_port, &usb_lock_set);

    for (int i = 0; i < total; i++) {
        char *path = task_args->paths[i];
        if (path[0] == '\0') {
            continue;
        }

        const char *name = strrchr(path, '/');
        name = name ? (name + 1) : path;

        char delete_path[WARDRIVE_WIGLE_PATH_MAX];
        char rx_buffer[512];
        bool ok = compromised_delete_file_locked(tab, uart_port, path,
                                                 delete_path, sizeof(delete_path),
                                                 rx_buffer, sizeof(rx_buffer));
        if (task_args->kind == COMPROMISED_FILE_KIND_HANDSHAKE) {
            compromised_delete_handshake_companion_locked(tab, uart_port, path);
        }
        if (ok) {
            success_count++;
        } else {
            failed_count++;
        }

        ESP_LOGI(TAG, "[%s] %s %d/%d: %s -> %s",
                 tab_transport_name(tab),
                 task_args->action == COMPROMISED_CLEANUP_ACTION_DELETE ? "Delete" : "Clean",
                 i + 1, total, delete_path[0] ? delete_path : name, ok ? "OK" : "FAIL");

        char status[160];
        if (task_args->action == COMPROMISED_CLEANUP_ACTION_DELETE && total == 1) {
            snprintf(status, sizeof(status), "Deleting file...");
        } else {
            snprintf(status, sizeof(status), "Deleting %d/%d files...", i + 1, total);
        }

        char line[240];
        snprintf(line, sizeof(line), "%s %s",
                 ok ? "[OK]" : "[FAIL]", name);

        bsp_display_lock(0);
        if (ctx->compromised_cleanup_status_label) {
            lv_label_set_text(ctx->compromised_cleanup_status_label, status);
        }
        compromised_cleanup_append_log(ctx, line);
        bsp_display_unlock();

        vTaskDelay(pdMS_TO_TICKS(80));
    }

    compromised_transport_lock_end(usb_lock_set);

    bsp_display_lock(0);
    if (ctx->compromised_cleanup_status_label) {
        lv_label_set_text_fmt(ctx->compromised_cleanup_status_label,
                              "%s finished. Deleted: %d, failed: %d\nRefreshing list...",
                              task_args->action == COMPROMISED_CLEANUP_ACTION_DELETE ? "Delete"
                                                                                     : "Clean",
                              success_count, failed_count);
    }
    bsp_display_unlock();

    vTaskDelay(pdMS_TO_TICKS(350));

    ctx->compromised_cleanup_running = false;
    ctx->compromised_cleanup_task = NULL;
    lv_async_call(compromised_cleanup_async_refresh, ctx);

    free(task_args);
    vTaskDelete(NULL);
}

static compromised_file_kind_t compromised_kind_from_user_data(void *user_data)
{
    uintptr_t raw = (uintptr_t)user_data;
    return (compromised_file_kind_t)((raw >> 16) & 0xFFFFu);
}

static int compromised_index_from_user_data(void *user_data)
{
    uintptr_t raw = (uintptr_t)user_data;
    return (int)(raw & 0xFFFFu);
}

static void *compromised_make_user_data(compromised_file_kind_t kind, int index)
{
    return (void *)(uintptr_t)((((uintptr_t)kind) & 0xFFFFu) << 16 | ((uintptr_t)index & 0xFFFFu));
}

static const char *compromised_primary_file_name_for_kind(compromised_file_kind_t kind)
{
    switch (kind) {
        case COMPROMISED_FILE_KIND_EVIL_TWIN:
            return "eviltwin.txt";
        case COMPROMISED_FILE_KIND_PORTAL:
            return "portals.txt";
        default:
            return NULL;
    }
}

static const char *compromised_primary_file_path_for_kind(compromised_file_kind_t kind)
{
    switch (kind) {
        case COMPROMISED_FILE_KIND_EVIL_TWIN:
            return "/sdcard/lab/eviltwin.txt";
        case COMPROMISED_FILE_KIND_PORTAL:
            return "/sdcard/lab/portals.txt";
        default:
            return NULL;
    }
}

static void compromised_seed_single_file_listing(tab_context_t *ctx, compromised_file_kind_t kind)
{
    if (!ctx) {
        return;
    }

    const char *name = compromised_primary_file_name_for_kind(kind);
    const char *path = compromised_primary_file_path_for_kind(kind);

    compromised_listing_reset_files(ctx);
    if (!name || !path || !ctx->wardrive_wigle_files) {
        return;
    }

    snprintf(ctx->wardrive_wigle_files[0].name, sizeof(ctx->wardrive_wigle_files[0].name), "%s", name);
    snprintf(ctx->wardrive_wigle_files[0].path, sizeof(ctx->wardrive_wigle_files[0].path), "%s", path);
    ctx->wardrive_wigle_file_count = 1;
}

static void compromised_add_single_file_controls(tab_context_t *ctx, lv_obj_t *page, lv_obj_t *header,
                                                 compromised_file_kind_t kind)
{
    if (!ctx || !page || !header) {
        return;
    }

    compromised_seed_single_file_listing(ctx, kind);

    bool actions_enabled = current_tab_has_sd_card() && !tab_is_internal(current_tab);
    const char *name = compromised_primary_file_name_for_kind(kind);
    const char *path = compromised_primary_file_path_for_kind(kind);
    lv_color_t accent = compromised_accent_for_kind(kind);

    lv_obj_t *clean_btn = lv_btn_create(header);
    lv_obj_set_size(clean_btn, 120, 50);
    style_danger_button(clean_btn);
    lv_obj_add_event_cb(clean_btn, compromised_file_clean_cb, LV_EVENT_CLICKED,
                        compromised_make_user_data(kind, 0));
    if (!actions_enabled) {
        lv_obj_add_state(clean_btn, LV_STATE_DISABLED);
    }

    lv_obj_t *clean_lbl = lv_label_create(clean_btn);
    lv_label_set_text(clean_lbl, LV_SYMBOL_TRASH " Clean");
    lv_obj_set_style_text_font(clean_lbl, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(clean_lbl, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(clean_lbl);

    lv_obj_t *file_panel = lv_obj_create(page);
    lv_obj_set_size(file_panel, lv_pct(100), LV_SIZE_CONTENT);
    style_surface_panel(file_panel, 8);
    lv_obj_set_style_pad_all(file_panel, 10, 0);
    lv_obj_clear_flag(file_panel, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *row = lv_obj_create(file_panel);
    lv_obj_set_size(row, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_color(row, ui_card_color(), 0);
    lv_obj_set_style_border_width(row, 1, 0);
    lv_obj_set_style_border_color(row, ui_border_color(), 0);
    lv_obj_set_style_border_opa(row, dark_mode_enabled ? LV_OPA_40 : LV_OPA_70, 0);
    lv_obj_set_style_radius(row, 8, 0);
    lv_obj_set_style_pad_all(row, 10, 0);
    lv_obj_set_style_pad_column(row, 10, 0);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *info = lv_obj_create(row);
    lv_obj_remove_style_all(info);
    lv_obj_set_flex_grow(info, 1);
    lv_obj_set_height(info, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(info, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(info, 4, 0);
    lv_obj_clear_flag(info, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *name_lbl = lv_label_create(info);
    lv_label_set_text(name_lbl, name ? name : "Unknown file");
    lv_obj_set_style_text_font(name_lbl, &lv_font_montserrat_16, 0);
    lv_obj_set_style_text_color(name_lbl, accent, 0);
    lv_obj_set_width(name_lbl, lv_pct(100));
    lv_label_set_long_mode(name_lbl, LV_LABEL_LONG_WRAP);

    lv_obj_t *path_lbl = lv_label_create(info);
    lv_label_set_text(path_lbl, path ? path : "");
    lv_obj_set_style_text_font(path_lbl, &lv_font_montserrat_12, 0);
    lv_obj_set_style_text_color(path_lbl, ui_muted_color(), 0);
    lv_obj_set_width(path_lbl, lv_pct(100));
    lv_label_set_long_mode(path_lbl, LV_LABEL_LONG_WRAP);

    lv_obj_t *delete_btn = lv_btn_create(row);
    lv_obj_set_size(delete_btn, 110, 44);
    style_danger_button(delete_btn);
    lv_obj_add_event_cb(delete_btn, compromised_file_delete_cb, LV_EVENT_CLICKED,
                        compromised_make_user_data(kind, 0));
    if (!actions_enabled) {
        lv_obj_add_state(delete_btn, LV_STATE_DISABLED);
    }

    lv_obj_t *delete_lbl = lv_label_create(delete_btn);
    lv_label_set_text(delete_lbl, LV_SYMBOL_TRASH " Delete");
    lv_obj_set_style_text_font(delete_lbl, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(delete_lbl, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(delete_lbl);
}

static void show_compromised_file_page(compromised_file_kind_t kind)
{
    tab_context_t *ctx = get_current_ctx();
    if (!ctx) {
        return;
    }

    lv_obj_t *container = get_current_tab_container();
    if (!container) {
        return;
    }

    lv_obj_t **page_slot = compromised_page_slot_for_kind(ctx, kind);
    if (!page_slot) {
        return;
    }

    hide_all_pages(ctx);

    if (*page_slot) {
        lv_obj_del(*page_slot);
        *page_slot = NULL;
    }

    lv_color_t accent = compromised_accent_for_kind(kind);
    *page_slot = lv_obj_create(container);
    lv_obj_set_size(*page_slot, lv_pct(100), lv_pct(100));
    lv_obj_align(*page_slot, LV_ALIGN_TOP_MID, 0, 0);
    lv_obj_set_style_bg_color(*page_slot, ui_bg_color(), 0);
    lv_obj_set_style_border_width(*page_slot, 0, 0);
    lv_obj_set_style_pad_all(*page_slot, 10, 0);
    lv_obj_set_flex_flow(*page_slot, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(*page_slot, 8, 0);
    ctx->current_visible_page = *page_slot;

    lv_obj_t *header = lv_obj_create(*page_slot);
    lv_obj_set_size(header, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(header, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(header, 0, 0);
    lv_obj_set_style_pad_all(header, 0, 0);
    lv_obj_set_flex_flow(header, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(header, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(header, 10, 0);

    lv_obj_t *back_btn = lv_btn_create(header);
    lv_obj_set_size(back_btn, 72, 60);
    style_back_nav_button(back_btn);
    lv_obj_add_event_cb(back_btn,
                        kind == COMPROMISED_FILE_KIND_PCAP_CAPTURE
                            ? espshark_remote_back_btn_event_cb
                            : compromised_data_back_btn_event_cb,
                        LV_EVENT_CLICKED, NULL);

    lv_obj_t *back_icon = lv_label_create(back_btn);
    lv_label_set_text(back_icon, LV_SYMBOL_LEFT);
    lv_obj_set_style_text_color(back_icon, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(back_icon);

    lv_obj_t *title = lv_label_create(header);
    lv_label_set_text(title, compromised_title_for_kind(kind));
    lv_obj_set_style_text_font(title, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(title, accent, 0);

    lv_obj_t *spacer = lv_obj_create(header);
    lv_obj_remove_style_all(spacer);
    lv_obj_set_flex_grow(spacer, 1);
    lv_obj_set_height(spacer, 1);

    lv_obj_t *clean_btn = NULL;

    if (kind == COMPROMISED_FILE_KIND_HANDSHAKE) {
        lv_obj_t *wpasec_btn = lv_btn_create(header);
        lv_obj_set_size(wpasec_btn, 190, 50);
        lv_obj_set_style_bg_color(wpasec_btn, COLOR_MATERIAL_PURPLE, 0);
        lv_obj_set_style_bg_color(wpasec_btn, lv_color_hex(0x9C27B0), LV_STATE_PRESSED);
        lv_obj_set_style_bg_color(wpasec_btn, lv_color_hex(0x555555), LV_STATE_DISABLED);
        lv_obj_set_style_radius(wpasec_btn, 8, 0);
        lv_obj_add_event_cb(wpasec_btn, wpasec_btn_event_cb, LV_EVENT_CLICKED, NULL);

        lv_obj_t *wpasec_lbl = lv_label_create(wpasec_btn);
        lv_label_set_text(wpasec_lbl, LV_SYMBOL_UPLOAD " Send to wpa-sec");
        lv_obj_set_style_text_font(wpasec_lbl, &lv_font_montserrat_14, 0);
        lv_obj_set_style_text_color(wpasec_lbl, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(wpasec_lbl);
    }

    // Both handshake and general PCAP pages expose the newest file in the header.
    // Per-file copy remains available on every row.
    bool is_copyable_pcap = (kind == COMPROMISED_FILE_KIND_HANDSHAKE ||
                             kind == COMPROMISED_FILE_KIND_PCAP_CAPTURE);
    if (is_copyable_pcap && ctx->compromised_files_loaded &&
        ctx->wardrive_wigle_file_count > 0) {
        int latest_index = ctx->wardrive_wigle_file_count - 1;
        lv_obj_t *copy_latest_btn = lv_btn_create(header);
        lv_obj_set_size(copy_latest_btn, 180, 50);
        lv_obj_set_style_bg_color(copy_latest_btn, lv_color_hex(0x087EA4), 0);
        lv_obj_set_style_bg_color(copy_latest_btn, lv_color_hex(0x05617F),
                                  LV_STATE_PRESSED);
        lv_obj_set_style_border_width(copy_latest_btn, 2, 0);
        lv_obj_set_style_border_color(copy_latest_btn, COLOR_MATERIAL_CYAN, 0);
        lv_obj_set_style_radius(copy_latest_btn, 8, 0);
        lv_obj_add_event_cb(copy_latest_btn, compromised_file_copy_cb,
                            LV_EVENT_CLICKED,
                            compromised_make_user_data(kind, latest_index));

        lv_obj_t *copy_latest_lbl = lv_label_create(copy_latest_btn);
        lv_label_set_text(copy_latest_lbl, "Copy latest");
        lv_obj_set_style_text_font(copy_latest_lbl, &lv_font_montserrat_16, 0);
        lv_obj_set_style_text_color(copy_latest_lbl, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(copy_latest_lbl);

        lv_obj_t *sync_btn = lv_btn_create(header);
        lv_obj_set_size(sync_btn, 155, 50);
        lv_obj_set_style_bg_color(sync_btn, lv_color_hex(0x008F76), 0);
        lv_obj_set_style_bg_color(sync_btn, lv_color_hex(0x006B58), LV_STATE_PRESSED);
        lv_obj_set_style_border_width(sync_btn, 2, 0);
        lv_obj_set_style_border_color(sync_btn, COLOR_NEON_GREEN, 0);
        lv_obj_set_style_radius(sync_btn, 8, 0);
        lv_obj_add_event_cb(sync_btn, compromised_files_sync_cb, LV_EVENT_CLICKED,
                            compromised_make_user_data(kind, 0));

        lv_obj_t *sync_lbl = lv_label_create(sync_btn);
        lv_label_set_text(sync_lbl,
                          kind == COMPROMISED_FILE_KIND_PCAP_CAPTURE
                              ? LV_SYMBOL_REFRESH " Sync all"
                              : LV_SYMBOL_REFRESH " Sync new");
        lv_obj_set_style_text_font(sync_lbl, &lv_font_montserrat_14, 0);
        lv_obj_set_style_text_color(sync_lbl, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(sync_lbl);
    }

    if (kind != COMPROMISED_FILE_KIND_WARDRIVE) {
        clean_btn = lv_btn_create(header);
        lv_obj_set_size(clean_btn, 120, 50);
        style_danger_button(clean_btn);
        lv_obj_add_event_cb(clean_btn, compromised_file_clean_cb, LV_EVENT_CLICKED,
                            compromised_make_user_data(kind, 0));

        lv_obj_t *clean_lbl = lv_label_create(clean_btn);
        lv_label_set_text(clean_lbl, LV_SYMBOL_TRASH " Clean");
        lv_obj_set_style_text_font(clean_lbl, &lv_font_montserrat_14, 0);
        lv_obj_set_style_text_color(clean_lbl, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(clean_lbl);
    }

    lv_obj_t *status_label = lv_label_create(*page_slot);
    lv_label_set_recolor(status_label, true);
    lv_label_set_text(status_label, "Loading...");
    lv_obj_set_style_text_font(status_label, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(status_label, ui_muted_color(), 0);

    lv_obj_t *list_container = lv_obj_create(*page_slot);
    lv_obj_set_size(list_container, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_grow(list_container, 1);
    style_surface_panel(list_container, 8);
    lv_obj_set_style_pad_all(list_container, 10, 0);
    lv_obj_set_flex_flow(list_container, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(list_container, 8, 0);

    if (!current_tab_has_sd_card()) {
        lv_label_set_text(status_label, "No SD card detected on this tab.");
        if (clean_btn) lv_obj_add_state(clean_btn, LV_STATE_DISABLED);
        return;
    }

    if (tab_is_internal(current_tab)) {
        lv_label_set_text(status_label, "Manage files from a JanOS transport tab.");
        if (clean_btn) lv_obj_add_state(clean_btn, LV_STATE_DISABLED);
        return;
    }

    // The listing is fetched over UART and can hash several MB of wardrive logs,
    // which takes many seconds. Do it on a background task with a live spinner so
    // the GUI stays responsive; compromised_files_load_task() rebuilds this page
    // (with compromised_files_loaded == true) once the module sends its END marker.
    if (!ctx->compromised_files_loaded) {
        lv_label_set_text(status_label, "Reading file list from module...");
        if (clean_btn) lv_obj_add_state(clean_btn, LV_STATE_DISABLED);

        // Centered overlay on top of the page (IGNORE_LAYOUT so flex can't squeeze
        // it to zero height, move_foreground so it never hides behind the list).
        lv_obj_t *loading_box = lv_obj_create(*page_slot);
        lv_obj_remove_style_all(loading_box);
        lv_obj_set_size(loading_box, lv_pct(100), lv_pct(100));
        lv_obj_add_flag(loading_box, LV_OBJ_FLAG_IGNORE_LAYOUT);
        lv_obj_clear_flag(loading_box, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_align(loading_box, LV_ALIGN_CENTER, 0, 0);

        lv_obj_t *spinner = lv_spinner_create(loading_box);
        lv_obj_set_size(spinner, 80, 80);
        lv_spinner_set_anim_params(spinner, 1000, 200);
        lv_obj_set_style_arc_color(spinner, accent, LV_PART_INDICATOR);
        lv_obj_center(spinner);

        lv_obj_t *loading_lbl = lv_label_create(loading_box);
        lv_label_set_text_fmt(loading_lbl, "Loading %s files...",
                              compromised_tile_name_for_kind(kind));
        lv_obj_set_style_text_font(loading_lbl, &lv_font_montserrat_16, 0);
        lv_obj_set_style_text_color(loading_lbl, ui_muted_color(), 0);
        lv_obj_align(loading_lbl, LV_ALIGN_CENTER, 0, 70);

        lv_obj_move_foreground(loading_box);

        if (!ctx->compromised_files_loading) {
            ctx->compromised_files_loading = true;
            ctx->compromised_files_load_kind = kind;
            if (xTaskCreate(compromised_files_load_task, "cf_load", 8192, ctx, 5,
                            &ctx->compromised_files_load_task) != pdTRUE) {
                ctx->compromised_files_loading = false;
                ctx->compromised_files_load_task = NULL;
                lv_label_set_text(status_label, "Failed to start file loader task.");
            }
        }
        return;
    }

    // Data is already in ctx (filled by the background task) — render from cache,
    // never re-issue the UART listing here.
    ctx->compromised_files_loaded = false;
    int entry_count = ctx->wardrive_wigle_file_count;
    if (kind == COMPROMISED_FILE_KIND_HANDSHAKE) {
        ctx->home_handshake_count = entry_count;
        update_home_dashboard_labels(ctx, battery_percent_from_voltage(current_battery_voltage));
    }

    // Wardrive keeps an upload journal that survives after files are uploaded and
    // moved to the archive, so an empty working dir is not necessarily an empty page.
    bool have_upload_state = (kind == COMPROMISED_FILE_KIND_WARDRIVE &&
                              ctx->wardrive_upload_state_loaded &&
                              ctx->wardrive_upload_state_count > 0);

    if (entry_count <= 0) {
        if (clean_btn) lv_obj_add_state(clean_btn, LV_STATE_DISABLED);

        if (!have_upload_state) {
            lv_label_set_text(status_label, compromised_empty_text_for_kind(kind));
            lv_obj_t *empty = lv_label_create(list_container);
            lv_label_set_text(empty, compromised_empty_text_for_kind(kind));
            lv_obj_set_style_text_font(empty, &lv_font_montserrat_16, 0);
            lv_obj_set_style_text_color(empty, ui_muted_color(), 0);
            lv_obj_set_style_text_align(empty, LV_TEXT_ALIGN_CENTER, 0);
            lv_obj_set_width(empty, lv_pct(100));
            return;
        }

        // No files waiting, but we have history below — say so and fall through.
        lv_label_set_text(status_label, "No files waiting - already uploaded/archived.");
        lv_obj_t *empty = lv_label_create(list_container);
        lv_label_set_text(empty, "No wardrive files in the working folder.");
        lv_obj_set_style_text_font(empty, &lv_font_montserrat_14, 0);
        lv_obj_set_style_text_color(empty, ui_muted_color(), 0);
        lv_obj_set_style_text_align(empty, LV_TEXT_ALIGN_CENTER, 0);
        lv_obj_set_width(empty, lv_pct(100));
    } else if (kind == COMPROMISED_FILE_KIND_WARDRIVE && ctx->wardrive_file_summary.valid) {
        char summary[320];
        wardrive_format_summary_text(&ctx->wardrive_file_summary, summary, sizeof(summary));
        lv_label_set_text(status_label, summary);
    } else {
        lv_label_set_text_fmt(status_label, "Found %d %s file(s)",
                              entry_count, compromised_tile_name_for_kind(kind));
    }

    // Newest first (wN.log auto-increments, so the last entry is the most recent).
    int max_entries = (entry_count < WARDRIVE_WIGLE_MAX_FILES) ? entry_count
                                                               : WARDRIVE_WIGLE_MAX_FILES;
    for (int disp = 0; disp < max_entries; disp++) {
        int i = max_entries - 1 - disp; // real array index, kept for delete callback
        wardrive_wigle_file_t *file = &ctx->wardrive_wigle_files[i];
        if (file->name[0] == '\0') {
            continue;
        }

        lv_color_t card_bg, card_border, card_title;
        wardrive_file_card_palette(file, &card_bg, &card_border, &card_title);

        lv_obj_t *row = lv_obj_create(list_container);
        lv_obj_set_size(row, lv_pct(100), LV_SIZE_CONTENT);
        lv_obj_set_style_bg_color(row, card_bg, 0);
        lv_obj_set_style_border_width(row, 1, 0);
        lv_obj_set_style_border_color(row, card_border, 0);
        lv_obj_set_style_border_opa(row, LV_OPA_80, 0);
        lv_obj_set_style_radius(row, 8, 0);
        lv_obj_set_style_pad_all(row, 10, 0);
        lv_obj_set_style_pad_column(row, 10, 0);
        lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                              LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

        lv_obj_t *info = lv_obj_create(row);
        lv_obj_remove_style_all(info);
        lv_obj_set_flex_grow(info, 1);
        lv_obj_set_height(info, LV_SIZE_CONTENT);
        lv_obj_set_flex_flow(info, LV_FLEX_FLOW_COLUMN);
        lv_obj_set_style_pad_row(info, 4, 0);
        lv_obj_clear_flag(info, LV_OBJ_FLAG_SCROLLABLE);

        lv_obj_t *name_lbl = lv_label_create(info);
        lv_label_set_text(name_lbl, file->name);
        lv_obj_set_style_text_font(name_lbl, &lv_font_montserrat_16, 0);
        lv_obj_set_style_text_color(name_lbl, card_title, 0);
        lv_obj_set_width(name_lbl, lv_pct(100));
        lv_label_set_long_mode(name_lbl, LV_LABEL_LONG_WRAP);

        lv_obj_t *path_lbl = lv_label_create(info);
        lv_label_set_text(path_lbl, file->path);
        lv_obj_set_style_text_font(path_lbl, &lv_font_montserrat_12, 0);
        lv_obj_set_style_text_color(path_lbl, ui_muted_color(), 0);
        lv_obj_set_width(path_lbl, lv_pct(100));
        lv_label_set_long_mode(path_lbl, LV_LABEL_LONG_WRAP);

        if (kind == COMPROMISED_FILE_KIND_PCAP_CAPTURE) {
            lv_obj_t *sync_state_lbl = lv_label_create(info);
            lv_label_set_recolor(sync_state_lbl, true);
            lv_label_set_text(sync_state_lbl,
                              file->tab5_synced
                                  ? "#52B6FF MONSTER: AVAILABLE#  |  #5EDCA3 TAB5: SYNCED#"
                                  : "#52B6FF MONSTER: AVAILABLE#  |  #F9A825 TAB5: NOT COPIED#");
            lv_obj_set_width(sync_state_lbl, lv_pct(100));
            lv_label_set_long_mode(sync_state_lbl, LV_LABEL_LONG_WRAP);
            lv_obj_set_style_text_font(sync_state_lbl, &lv_font_montserrat_12, 0);
            lv_obj_set_style_text_color(sync_state_lbl, ui_muted_color(), 0);
        }

        if (kind == COMPROMISED_FILE_KIND_WARDRIVE) {
            char detail[224];
            wardrive_format_file_detail_rich(file, detail, sizeof(detail));
            if (detail[0] != '\0') {
                lv_obj_t *detail_lbl = lv_label_create(info);
                lv_label_set_recolor(detail_lbl, true);
                lv_label_set_text(detail_lbl, detail);
                lv_obj_set_style_text_font(detail_lbl, &lv_font_montserrat_14, 0);
                lv_obj_set_style_text_color(detail_lbl, ui_muted_color(), 0);
                lv_obj_set_width(detail_lbl, lv_pct(100));
                lv_label_set_long_mode(detail_lbl, LV_LABEL_LONG_WRAP);
            }
        } else {
            char detail[192];
            wardrive_format_file_detail(file, detail, sizeof(detail));
            if (detail[0] != '\0') {
                lv_obj_t *detail_lbl = lv_label_create(info);
                lv_label_set_text(detail_lbl, detail);
                lv_obj_set_style_text_font(detail_lbl, &lv_font_montserrat_12, 0);
                lv_obj_set_style_text_color(detail_lbl, ui_muted_color(), 0);
                lv_obj_set_width(detail_lbl, lv_pct(100));
                lv_label_set_long_mode(detail_lbl, LV_LABEL_LONG_WRAP);
            }
        }

        lv_obj_t *actions = lv_obj_create(row);
        lv_obj_remove_style_all(actions);
        if (is_copyable_pcap) {
            // Explicit dimensions avoid LVGL resolving a percentage inside a
            // content-sized flex parent to zero and hiding the copy action.
            lv_obj_set_size(actions, 392, 62);
        } else {
            lv_obj_set_size(actions, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
        }
        lv_obj_set_flex_flow(actions, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(actions, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_set_style_pad_column(actions, 12, 0);
        lv_obj_clear_flag(actions, LV_OBJ_FLAG_SCROLLABLE);

        if (kind == COMPROMISED_FILE_KIND_WARDRIVE) {
            lv_obj_t *fix_btn = lv_btn_create(actions);
            lv_obj_set_size(fix_btn, 86, 44);
            lv_obj_set_style_bg_color(fix_btn, COLOR_MATERIAL_TEAL, 0);
            lv_obj_set_style_bg_color(fix_btn, lv_color_hex(0x00796B), LV_STATE_PRESSED);
            lv_obj_set_style_radius(fix_btn, 8, 0);
            lv_obj_set_style_shadow_width(fix_btn, 0, 0);
            lv_obj_add_event_cb(fix_btn, wardrive_fix_file_cb, LV_EVENT_CLICKED,
                                compromised_make_user_data(kind, i));

            lv_obj_t *fix_lbl = lv_label_create(fix_btn);
            lv_label_set_text(fix_lbl, "Fix");
            lv_obj_set_style_text_font(fix_lbl, &lv_font_montserrat_14, 0);
            lv_obj_set_style_text_color(fix_lbl, lv_color_hex(0xFFFFFF), 0);
            lv_obj_center(fix_lbl);
        }

        if (is_copyable_pcap) {
            lv_obj_t *copy_btn = lv_btn_create(actions);
            lv_obj_set_size(copy_btn, 250, 62);
            lv_obj_set_style_bg_color(copy_btn, lv_color_hex(0x087EA4), 0);
            lv_obj_set_style_bg_color(copy_btn, lv_color_hex(0x05617F), LV_STATE_PRESSED);
            lv_obj_set_style_border_width(copy_btn, 2, 0);
            lv_obj_set_style_border_color(copy_btn, COLOR_MATERIAL_CYAN, 0);
            lv_obj_set_style_border_opa(copy_btn, LV_OPA_100, 0);
            lv_obj_set_style_radius(copy_btn, 10, 0);
            lv_obj_set_style_shadow_width(copy_btn, 8, 0);
            lv_obj_set_style_shadow_color(copy_btn, COLOR_MATERIAL_CYAN, 0);
            lv_obj_set_style_shadow_opa(copy_btn, LV_OPA_30, 0);
            lv_obj_set_flex_flow(copy_btn, LV_FLEX_FLOW_COLUMN);
            lv_obj_set_flex_align(copy_btn, LV_FLEX_ALIGN_CENTER,
                                  LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
            lv_obj_set_style_pad_row(copy_btn, 1, 0);
            lv_obj_add_event_cb(copy_btn, compromised_file_copy_cb, LV_EVENT_CLICKED,
                                compromised_make_user_data(kind, i));

            lv_obj_t *copy_title = lv_label_create(copy_btn);
            lv_label_set_text(copy_title, "COPY TO TAB5");
            lv_obj_set_style_text_font(copy_title, &lv_font_montserrat_16, 0);
            lv_obj_set_style_text_color(copy_title, lv_color_hex(0xFFFFFF), 0);

            lv_obj_t *copy_hint = lv_label_create(copy_btn);
            lv_label_set_text(copy_hint, "Monster SD  >  Tab5 SD");
            lv_obj_set_style_text_font(copy_hint, &lv_font_montserrat_12, 0);
            lv_obj_set_style_text_color(copy_hint, lv_color_hex(0xD7F7FF), 0);
        }

        lv_obj_t *delete_btn = lv_btn_create(actions);
        lv_obj_set_size(delete_btn,
                        is_copyable_pcap ? 130 : 110,
                        is_copyable_pcap ? 62 : 44);
        style_danger_button(delete_btn);
        lv_obj_add_event_cb(delete_btn, compromised_file_delete_cb, LV_EVENT_CLICKED,
                            compromised_make_user_data(kind, i));

        lv_obj_t *delete_lbl = lv_label_create(delete_btn);
        lv_label_set_text(delete_lbl,
                          is_copyable_pcap
                              ? "DELETE FILE"
                              : LV_SYMBOL_TRASH " Delete");
        lv_obj_set_style_text_font(delete_lbl, &lv_font_montserrat_14, 0);
        lv_obj_set_style_text_color(delete_lbl, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(delete_lbl);
    }

    // Wardrive only: append the upload journal (upload_state). Files that were
    // already uploaded get moved to the "uploaded" archive folder, so they are
    // gone from the working-dir listing above - this is the only record left.
    if (kind == COMPROMISED_FILE_KIND_WARDRIVE && ctx->wardrive_upload_state_loaded &&
        ctx->wardrive_upload_state_count > 0) {
        lv_obj_t *state_title = lv_label_create(list_container);
        lv_label_set_text_fmt(state_title,
                              LV_SYMBOL_OK " Upload status - %d entr%s (uploaded / archived)",
                              ctx->wardrive_upload_state_count,
                              ctx->wardrive_upload_state_count == 1 ? "y" : "ies");
        lv_obj_set_style_text_font(state_title, &lv_font_montserrat_16, 0);
        lv_obj_set_style_text_color(state_title, COLOR_MATERIAL_PURPLE, 0);
        lv_obj_set_width(state_title, lv_pct(100));
        lv_obj_set_style_text_align(state_title, LV_TEXT_ALIGN_CENTER, 0);

        for (int disp = 0; disp < ctx->wardrive_upload_state_count; disp++) {
            int i = ctx->wardrive_upload_state_count - 1 - disp; // newest first
            wardrive_upload_state_entry_t *entry = &ctx->wardrive_upload_state_entries[i];
            if (entry->filename[0] == '\0') {
                continue;
            }

            lv_color_t card_bg, card_border, card_title;
            wardrive_status_card_palette(entry->status, entry->bad_rows,
                                         &card_bg, &card_border, &card_title);

            lv_obj_t *row = lv_obj_create(list_container);
            lv_obj_set_size(row, lv_pct(100), LV_SIZE_CONTENT);
            lv_obj_set_style_bg_color(row, card_bg, 0);
            lv_obj_set_style_border_width(row, 1, 0);
            lv_obj_set_style_border_color(row, card_border, 0);
            lv_obj_set_style_border_opa(row, LV_OPA_80, 0);
            lv_obj_set_style_radius(row, 8, 0);
            lv_obj_set_style_pad_all(row, 10, 0);
            lv_obj_set_style_pad_row(row, 4, 0);
            lv_obj_set_flex_flow(row, LV_FLEX_FLOW_COLUMN);
            lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

            lv_obj_t *name_lbl = lv_label_create(row);
            lv_label_set_text(name_lbl, entry->filename);
            lv_obj_set_style_text_font(name_lbl, &lv_font_montserrat_16, 0);
            lv_obj_set_style_text_color(name_lbl, card_title, 0);
            lv_obj_set_width(name_lbl, lv_pct(100));
            lv_label_set_long_mode(name_lbl, LV_LABEL_LONG_DOT);

            char detail[192];
            wardrive_format_upload_state_entry(entry, detail, sizeof(detail));
            lv_obj_t *detail_lbl = lv_label_create(row);
            lv_label_set_recolor(detail_lbl, true);
            lv_label_set_text(detail_lbl, detail);
            lv_obj_set_style_text_font(detail_lbl, &lv_font_montserrat_14, 0);
            lv_obj_set_style_text_color(detail_lbl, ui_muted_color(), 0);
            lv_obj_set_width(detail_lbl, lv_pct(100));
            lv_label_set_long_mode(detail_lbl, LV_LABEL_LONG_WRAP);
        }
    }
}

static void compromised_file_delete_cb(lv_event_t *e)
{
    tab_context_t *ctx = get_current_ctx();
    if (!ctx || ctx->compromised_cleanup_running) {
        return;
    }

    compromised_file_kind_t kind = compromised_kind_from_user_data(lv_event_get_user_data(e));
    int index = compromised_index_from_user_data(lv_event_get_user_data(e));
    if (index < 0 || index >= ctx->wardrive_wigle_file_count) {
        return;
    }

    const char *path = ctx->wardrive_wigle_files[index].path;
    if (!path || path[0] == '\0') {
        return;
    }

    compromised_cleanup_task_args_t *task_args = calloc(1, sizeof(*task_args));
    if (!task_args) {
        ESP_LOGW(TAG, "Failed to allocate delete task args");
        return;
    }

    task_args->ctx = ctx;
    task_args->kind = kind;
    task_args->action = COMPROMISED_CLEANUP_ACTION_DELETE;
    task_args->path_count = 1;
    snprintf(task_args->paths[0], sizeof(task_args->paths[0]), "%s", path);

    if (!compromised_start_cleanup_operation(ctx, task_args)) {
        free(task_args);
    }
}

static void wardrive_fix_file_cb(lv_event_t *e)
{
    tab_context_t *ctx = get_current_ctx();
    if (!ctx || ctx->compromised_cleanup_running) {
        return;
    }

    int index = compromised_index_from_user_data(lv_event_get_user_data(e));
    if (index < 0 || index >= ctx->wardrive_wigle_file_count) {
        return;
    }

    const char *file = ctx->wardrive_wigle_files[index].name;
    if (!file || file[0] == '\0') {
        return;
    }

    wardrive_fix_task_args_t *args = calloc(1, sizeof(*args));
    if (!args) {
        ESP_LOGW(TAG, "Failed to allocate wardrive fix task args");
        return;
    }

    args->ctx = ctx;
    snprintf(args->file, sizeof(args->file), "%s", file);

    ctx->compromised_cleanup_running = true;
    ctx->compromised_cleanup_kind = COMPROMISED_FILE_KIND_WARDRIVE;
    ctx->compromised_cleanup_action = COMPROMISED_CLEANUP_ACTION_CLEAN;
    ctx->compromised_cleanup_log_buffer[0] = '\0';

    show_compromised_cleanup_popup(ctx, COMPROMISED_FILE_KIND_WARDRIVE,
                                   COMPROMISED_CLEANUP_ACTION_CLEAN);
    if (ctx->compromised_cleanup_status_label) {
        lv_label_set_text(ctx->compromised_cleanup_status_label,
                          "Fixing wardrive file...");
    }
    if (ctx->compromised_cleanup_log_label) {
        lv_label_set_text(ctx->compromised_cleanup_log_label,
                          "Running wardrive_fix. Original file stays unchanged.");
    }
    if (ctx->compromised_cleanup_move_btn) {
        lv_obj_add_flag(ctx->compromised_cleanup_move_btn, LV_OBJ_FLAG_HIDDEN);
    }
    lv_refr_now(NULL);

    if (xTaskCreate(wardrive_fix_task, "wd_fix", 8192, args, 5,
                    &ctx->compromised_cleanup_task) != pdTRUE) {
        ctx->compromised_cleanup_running = false;
        ctx->compromised_cleanup_task = NULL;
        close_compromised_cleanup_popup(ctx);
        free(args);
    }
}

static void compromised_file_clean_cb(lv_event_t *e)
{
    tab_context_t *ctx = get_current_ctx();
    if (!ctx || ctx->wardrive_wigle_file_count <= 0 || ctx->compromised_cleanup_running) {
        return;
    }

    compromised_file_kind_t kind = compromised_kind_from_user_data(lv_event_get_user_data(e));
    compromised_cleanup_task_args_t *task_args = calloc(1, sizeof(*task_args));
    if (!task_args) {
        ESP_LOGW(TAG, "Failed to allocate cleanup task args");
        return;
    }

    task_args->ctx = ctx;
    task_args->kind = kind;
    task_args->action = COMPROMISED_CLEANUP_ACTION_CLEAN;
    for (int i = 0; i < ctx->wardrive_wigle_file_count && i < WARDRIVE_WIGLE_MAX_FILES; i++) {
        if (ctx->wardrive_wigle_files[i].path[0] != '\0') {
            snprintf(task_args->paths[task_args->path_count],
                     sizeof(task_args->paths[task_args->path_count]),
                     "%s",
                     ctx->wardrive_wigle_files[i].path);
            task_args->path_count++;
        }
    }

    if (task_args->path_count <= 0) {
        free(task_args);
        return;
    }

    if (!compromised_start_cleanup_operation(ctx, task_args)) {
        free(task_args);
    }
}

static lv_obj_t *espshark_create_action_card(lv_obj_t *parent, const char *icon,
                                              const char *title_text,
                                              const char *description,
                                              const char *status_text,
                                              lv_color_t accent,
                                              const char *action)
{
    lv_obj_t *card = lv_btn_create(parent);
    lv_obj_set_width(card, lv_pct(49));
    lv_obj_set_height(card, 190);
    lv_obj_set_style_bg_color(card, ui_card_color(), 0);
    lv_obj_set_style_bg_color(card, lv_color_hex(0x16364A), LV_STATE_PRESSED);
    lv_obj_set_style_border_width(card, 2, 0);
    lv_obj_set_style_border_color(card, accent, 0);
    lv_obj_set_style_border_opa(card, LV_OPA_90, 0);
    lv_obj_set_style_radius(card, 12, 0);
    lv_obj_set_style_pad_all(card, 16, 0);
    lv_obj_set_style_pad_row(card, 8, 0);
    lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(card, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);
    if (action) {
        lv_obj_add_event_cb(card, espshark_action_btn_event_cb,
                            LV_EVENT_CLICKED, (void *)action);
    }

    lv_obj_t *title = lv_label_create(card);
    lv_label_set_text_fmt(title, "%s  %s", icon ? icon : "", title_text ? title_text : "");
    lv_obj_set_width(title, lv_pct(100));
    lv_obj_set_style_text_font(title, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(title, accent, 0);

    lv_obj_t *desc = lv_label_create(card);
    lv_label_set_text(desc, description ? description : "");
    lv_obj_set_width(desc, lv_pct(100));
    lv_label_set_long_mode(desc, LV_LABEL_LONG_WRAP);
    lv_obj_set_style_text_font(desc, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(desc, ui_text_color(), 0);
    lv_obj_set_flex_grow(desc, 1);

    lv_obj_t *status = lv_label_create(card);
    lv_label_set_text(status, status_text ? status_text : "");
    lv_obj_set_width(status, lv_pct(100));
    lv_label_set_long_mode(status, LV_LABEL_LONG_WRAP);
    lv_obj_set_style_text_font(status, &lv_font_montserrat_12, 0);
    lv_obj_set_style_text_color(status, accent, 0);
    return card;
}

static void show_espshark_page(void)
{
    tab_context_t *ctx = get_current_ctx();
    lv_obj_t *container = get_current_tab_container();
    if (!ctx || !container) {
        return;
    }

    hide_all_pages(ctx);
    if (ctx->espshark_page && lv_obj_is_valid(ctx->espshark_page)) {
        lv_obj_del(ctx->espshark_page);
    }

    ctx->espshark_page = lv_obj_create(container);
    lv_obj_t *page = ctx->espshark_page;
    lv_obj_set_size(page, lv_pct(100), lv_pct(100));
    lv_obj_align(page, LV_ALIGN_TOP_MID, 0, 0);
    lv_obj_set_style_bg_color(page, ui_bg_color(), 0);
    lv_obj_set_style_border_width(page, 0, 0);
    lv_obj_set_style_pad_all(page, 10, 0);
    lv_obj_set_style_pad_row(page, 10, 0);
    lv_obj_set_flex_flow(page, LV_FLEX_FLOW_COLUMN);
    ctx->current_visible_page = page;

    lv_obj_t *header = lv_obj_create(page);
    lv_obj_set_size(header, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(header, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(header, 0, 0);
    lv_obj_set_style_pad_all(header, 0, 0);
    lv_obj_set_style_pad_column(header, 12, 0);
    lv_obj_set_flex_flow(header, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(header, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    lv_obj_t *back_btn = lv_btn_create(header);
    lv_obj_set_size(back_btn, 72, 60);
    style_back_nav_button(back_btn);
    lv_obj_add_event_cb(back_btn, espshark_back_btn_event_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t *back_icon = lv_label_create(back_btn);
    lv_label_set_text(back_icon, LV_SYMBOL_LEFT);
    lv_obj_set_style_text_color(back_icon, lv_color_white(), 0);
    lv_obj_center(back_icon);

    lv_obj_t *heading = lv_obj_create(header);
    lv_obj_remove_style_all(heading);
    lv_obj_set_height(heading, LV_SIZE_CONTENT);
    lv_obj_set_flex_grow(heading, 1);
    lv_obj_set_flex_flow(heading, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(heading, 2, 0);
    lv_obj_clear_flag(heading, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_t *title = lv_label_create(heading);
    lv_label_set_text(title, "ESPShark");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_24, 0);
    lv_obj_set_style_text_color(title, COLOR_NEON_CYAN, 0);
    lv_obj_t *subtitle = lv_label_create(heading);
    lv_label_set_text(subtitle, "Capture  |  Inspect  |  Analyze");
    lv_obj_set_style_text_font(subtitle, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(subtitle, ui_muted_color(), 0);

    lv_obj_t *mode_badge = lv_label_create(header);
    lv_label_set_text_fmt(mode_badge, "%s source", tab_transport_name(current_tab));
    lv_obj_set_style_text_font(mode_badge, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(mode_badge, COLOR_NEON_GREEN, 0);

    lv_obj_t *intro = lv_label_create(page);
    lv_label_set_text(intro,
                      "Choose where the capture comes from. Monster view shows what is on the module SD, "
                      "marks files already copied to Tab5 and can synchronize everything missing.");
    lv_obj_set_width(intro, lv_pct(100));
    lv_label_set_long_mode(intro, LV_LABEL_LONG_WRAP);
    lv_obj_set_style_text_font(intro, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(intro, ui_muted_color(), 0);

    lv_obj_t *actions = lv_obj_create(page);
    lv_obj_set_size(actions, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(actions, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(actions, 0, 0);
    lv_obj_set_style_pad_all(actions, 0, 0);
    lv_obj_set_style_pad_gap(actions, 12, 0);
    lv_obj_set_flex_flow(actions, LV_FLEX_FLOW_ROW_WRAP);
    lv_obj_set_flex_align(actions, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_clear_flag(actions, LV_OBJ_FLAG_SCROLLABLE);

    bool monster_ready = !tab_is_internal(current_tab) && current_tab_has_sd_card();
    char monster_status[128];
    if (monster_ready) {
        snprintf(monster_status, sizeof(monster_status),
                 "%s SD ready  |  COPY ONE / SYNC ALL", tab_transport_name(current_tab));
    } else if (tab_is_internal(current_tab)) {
        snprintf(monster_status, sizeof(monster_status),
                 "Select an MBus, Grove or USB JanOS tab first");
    } else {
        snprintf(monster_status, sizeof(monster_status),
                 "%s: Monster SD not detected", tab_transport_name(current_tab));
    }

    lv_obj_t *monster_card = espshark_create_action_card(
        actions, LV_SYMBOL_DOWNLOAD, "READ FROM MONSTER",
        "Browse captures on the Monster SD. Each row shows whether its verified copy "
        "already exists on Tab5.", monster_status, COLOR_MATERIAL_GREEN, "monster");
    if (!monster_ready) {
        lv_obj_add_state(monster_card, LV_STATE_DISABLED);
    }

    espshark_create_action_card(
        actions, LV_SYMBOL_EYE_OPEN, "OPEN FROM TAB5",
        "Open PCAP files already stored under /sdcard/lab/pcaps and inspect "
        "packets, summaries, DNS and protocol filters.",
        "TAB5 SD  |  LOCAL ANALYSIS", COLOR_NEON_CYAN, "tab5");

    lv_obj_t *future = lv_obj_create(page);
    lv_obj_set_size(future, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_color(future, ui_card_color(), 0);
    lv_obj_set_style_border_width(future, 1, 0);
    lv_obj_set_style_border_color(future, COLOR_MATERIAL_PURPLE, 0);
    lv_obj_set_style_radius(future, 10, 0);
    lv_obj_set_style_pad_all(future, 12, 0);
    lv_obj_clear_flag(future, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_t *future_text = lv_label_create(future);
    lv_label_set_text(future_text,
                      LV_SYMBOL_WARNING "  NEXT: NETWORK HEALTH / THREAT ANALYSIS\n"
                      "Baseline, suspicious DNS, scans, beaconing and worm-like lateral spread. "
                      "Live stream requires a later JanOS capture protocol.");
    lv_obj_set_width(future_text, lv_pct(100));
    lv_label_set_long_mode(future_text, LV_LABEL_LONG_WRAP);
    lv_obj_set_style_text_font(future_text, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(future_text, COLOR_MATERIAL_PURPLE, 0);

    ESP_LOGI(TAG, "[ESPShark] Hub opened on %s (Monster SD=%s)",
             tab_transport_name(current_tab), monster_ready ? "ready" : "unavailable");
}

// Show Compromised Data page with file-category tiles inside the current tab.
static void show_compromised_data_page(void)
{
    tab_context_t *ctx = get_current_ctx();
    lv_obj_t *container = get_current_tab_container();

    if (!container) {
        ESP_LOGE(TAG, "Container not initialized for tab %d", current_tab);
        return;
    }

    // Hide all other pages
    hide_all_pages(ctx);

    // If page already exists, just show it
    if (ctx->compromised_data_page) {
        lv_obj_clear_flag(ctx->compromised_data_page, LV_OBJ_FLAG_HIDDEN);
        ctx->current_visible_page = ctx->compromised_data_page;
        compromised_data_page = ctx->compromised_data_page;
        ESP_LOGI(TAG, "Showing existing compromised data page for tab %d", current_tab);
        return;
    }

    ESP_LOGI(TAG, "Creating new compromised data page for tab %d", current_tab);

    // Create page container inside tab container
    ctx->compromised_data_page = lv_obj_create(container);
    compromised_data_page = ctx->compromised_data_page;
    lv_obj_set_size(compromised_data_page, lv_pct(100), lv_pct(100));
    lv_obj_set_style_bg_color(compromised_data_page, lv_color_hex(0x1A1A1A), 0);
    lv_obj_set_style_border_width(compromised_data_page, 0, 0);
    lv_obj_set_style_pad_all(compromised_data_page, 10, 0);
    lv_obj_set_flex_flow(compromised_data_page, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(compromised_data_page, 10, 0);

    // Header with back button and title
    lv_obj_t *header = lv_obj_create(compromised_data_page);
    lv_obj_set_size(header, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(header, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(header, 0, 0);
    lv_obj_set_style_pad_all(header, 0, 0);
    lv_obj_set_flex_flow(header, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(header, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(header, 12, 0);

    // Back button (arrow style like other pages)
    lv_obj_t *back_btn = lv_btn_create(header);
    lv_obj_set_size(back_btn, 72, 60);
    lv_obj_set_style_bg_color(back_btn, lv_color_hex(0x333333), 0);
    lv_obj_set_style_bg_color(back_btn, lv_color_hex(0x444444), LV_STATE_PRESSED);
    lv_obj_set_style_radius(back_btn, 8, 0);
    lv_obj_add_event_cb(back_btn, compromised_data_main_back_btn_event_cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *back_icon = lv_label_create(back_btn);
    lv_label_set_text(back_icon, LV_SYMBOL_LEFT);
    lv_obj_set_style_text_color(back_icon, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(back_icon);

    // Title
    lv_obj_t *title = lv_label_create(header);
    lv_label_set_text(title, "Compromised Data");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(title, COLOR_MATERIAL_GREEN, 0);

    // Tiles container - match main menu grid behavior (top-aligned row wrap)
    lv_obj_t *tiles = lv_obj_create(compromised_data_page);
    lv_obj_set_size(tiles, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_grow(tiles, 1);
    lv_obj_set_style_bg_opa(tiles, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(tiles, 0, 0);
    lv_obj_set_style_pad_all(tiles, 2, 0);
    lv_obj_set_style_pad_gap(tiles, 10, 0);
    lv_obj_set_flex_flow(tiles, LV_FLEX_FLOW_ROW_WRAP);
    lv_obj_set_flex_align(tiles, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_clear_flag(tiles, LV_OBJ_FLAG_SCROLLABLE);

    // Same responsive row-wrap flow as the main menu. Category tiles wrap
    // into additional rows when the available width is smaller.
    create_tile(tiles, LV_SYMBOL_LIST, "Evil Twin\nPasswords", COLOR_MATERIAL_AMBER, compromised_data_tile_event_cb, "Evil Twin Passwords");
    create_tile(tiles, LV_SYMBOL_FILE, "Portal\nData", COLOR_MATERIAL_TEAL, compromised_data_tile_event_cb, "Portal Data");
    create_tile(tiles, LV_SYMBOL_DOWNLOAD, "Handshakes", COLOR_MATERIAL_PURPLE, compromised_data_tile_event_cb, "Handshakes");
    create_tile(tiles, LV_SYMBOL_EYE_OPEN, "ESPShark", lv_color_hex(0x087EA4), compromised_data_tile_event_cb, "ESPShark");
    create_tile(tiles, LV_SYMBOL_GPS, "Wardrive\nFiles", COLOR_MATERIAL_CYAN, compromised_data_tile_event_cb, "Wardrive Files");

    // Set current visible page
    ctx->current_visible_page = ctx->compromised_data_page;
}

