// Apply selected/unselected styling to a band button
static void jammer_style_band_btn(lv_obj_t *btn, bool selected)
{
    if (!btn) return;
    if (selected) {
        lv_obj_set_style_bg_color(btn, COLOR_MATERIAL_RED, 0);
        lv_obj_set_style_bg_opa(btn, LV_OPA_COVER, 0);
    } else {
        lv_obj_set_style_bg_color(btn, ui_card_color(), 0);
        lv_obj_set_style_bg_opa(btn, LV_OPA_COVER, 0);
    }
}

// Set band buttons enabled/disabled (locked while jamming)
static void jammer_set_bands_enabled(bool enabled)
{
    for (int i = 0; i < 5; i++) {
        if (!bt_jammer_band_btns[i]) continue;
        if (enabled) {
            lv_obj_clear_state(bt_jammer_band_btns[i], LV_STATE_DISABLED);
        } else {
            lv_obj_add_state(bt_jammer_band_btns[i], LV_STATE_DISABLED);
        }
    }
}

// One-shot probe run on page open: init the nRF24 and report whether the
// module is present, without starting a jam.
static void bt_jammer_probe_task(void *arg)
{
    tab_context_t *ctx = (tab_context_t *)arg;
    tab_id_t task_tab = tab_id_for_ctx(ctx);
    uart_port_t uart_port = (task_tab == TAB_MBUS && uart2_initialized) ? UART2_NUM : UART_NUM;

    ESP_LOGI(TAG, "Jammer probe: detecting nRF24 on tab %d", task_tab);
    uart_send_command_for_tab("init_nrf24");

    static char rx_buffer[256];
    static char line_buffer[128];
    int line_pos = 0;
    int verdict = 0; // 1=present 2=absent

    for (int iter = 0; iter < 10 && verdict == 0 && bt_jammer_probe_active; iter++) {
        int len = transport_read_bytes(uart_port, rx_buffer, sizeof(rx_buffer) - 1,
                                       pdMS_TO_TICKS(100));
        if (len <= 0) continue;
        rx_buffer[len] = '\0';
        for (int i = 0; i < len && verdict == 0; i++) {
            char c = rx_buffer[i];
            if (c == '\n' || c == '\r') {
                if (line_pos > 0) {
                    line_buffer[line_pos] = '\0';
                    if (strstr(line_buffer, "[NRF24] not detected")) verdict = 2;
                    else if (strstr(line_buffer, "[NRF24] detected"))  verdict = 1;
                    line_pos = 0;
                }
            } else if (line_pos < (int)sizeof(line_buffer) - 1) {
                line_buffer[line_pos++] = c;
            }
        }
    }

    if (verdict != 0) bt_nrf24_present = verdict;

    // Update the status label only if the probe still owns the page (user
    // hasn't pressed Start / left in the meantime).
    if (bt_jammer_probe_active) {
        bsp_display_lock(0);
        if (bt_jammer_status_lbl && ctx && !ctx->bt_jamming) {
            if (verdict == 1) {
                lv_label_set_text(bt_jammer_status_lbl, "nRF24: OK");
                lv_obj_set_style_text_color(bt_jammer_status_lbl, COLOR_MATERIAL_GREEN, 0);
            } else if (verdict == 2) {
                lv_label_set_text(bt_jammer_status_lbl, "nRF24: not detected");
                lv_obj_set_style_text_color(bt_jammer_status_lbl, COLOR_MATERIAL_RED, 0);
            }
        }
        bsp_display_unlock();
    }

    ESP_LOGI(TAG, "Jammer probe done: verdict=%d", verdict);
    bt_jammer_probe_active = false;
    bt_jammer_probe_handle = NULL;
    vTaskDelete(NULL);
}

// Reader task - parses nRF24 status markers from the active tab's transport
static void bt_jammer_task(void *arg)
{
    tab_context_t *ctx = (tab_context_t *)arg;

    tab_id_t task_tab = tab_id_for_ctx(ctx);
    uart_port_t uart_port = (task_tab == TAB_MBUS && uart2_initialized) ? UART2_NUM : UART_NUM;
    const char *uart_name = tab_transport_name(task_tab);

    ESP_LOGI(TAG, "[%s] Jammer reader task started for tab %d", uart_name, task_tab);

    static char rx_buffer[256];
    static char line_buffer[128];
    int line_pos = 0;

    while (ctx && ctx->bt_jamming) {
        int len = transport_read_bytes(uart_port, rx_buffer, sizeof(rx_buffer) - 1, pdMS_TO_TICKS(100));

        if (len > 0) {
            rx_buffer[len] = '\0';

            for (int i = 0; i < len; i++) {
                char c = rx_buffer[i];

                if (c == '\n' || c == '\r') {
                    if (line_pos > 0) {
                        line_buffer[line_pos] = '\0';

                        if (strstr(line_buffer, "[NRF24] not detected")) {
                            ESP_LOGW(TAG, "Jammer: nRF24 not detected");
                            bt_nrf24_present = 2;
                            ctx->bt_jamming = false; /* drop out of the loop */
                            bsp_display_lock(0);
                            if (bt_jammer_status_lbl) {
                                lv_label_set_text(bt_jammer_status_lbl, "nRF24 not detected!");
                                lv_obj_set_style_text_color(bt_jammer_status_lbl, COLOR_MATERIAL_RED, 0);
                            }
                            jammer_set_bands_enabled(true);
                            if (bt_jammer_big_btn)
                                lv_obj_set_style_bg_color(bt_jammer_big_btn, COLOR_MATERIAL_RED, 0);
                            if (bt_jammer_big_btn_lbl)
                                lv_label_set_text(bt_jammer_big_btn_lbl, LV_SYMBOL_PLAY "  Start Jammer");
                            bsp_display_unlock();
                        } else if (strstr(line_buffer, "[NRF24] failed to start")) {
                            ESP_LOGW(TAG, "Jammer: failed to start");
                            ctx->bt_jamming = false; /* drop out of the loop */
                            bsp_display_lock(0);
                            if (bt_jammer_status_lbl) {
                                lv_label_set_text(bt_jammer_status_lbl, "Failed to start");
                                lv_obj_set_style_text_color(bt_jammer_status_lbl, COLOR_MATERIAL_RED, 0);
                            }
                            jammer_set_bands_enabled(true);
                            if (bt_jammer_big_btn)
                                lv_obj_set_style_bg_color(bt_jammer_big_btn, COLOR_MATERIAL_RED, 0);
                            if (bt_jammer_big_btn_lbl)
                                lv_label_set_text(bt_jammer_big_btn_lbl, LV_SYMBOL_PLAY "  Start Jammer");
                            bsp_display_unlock();
                        } else if (strstr(line_buffer, "nRF24 jammer started")) {
                            ESP_LOGI(TAG, "Jammer: started");
                            bt_nrf24_present = 1;
                            bsp_display_lock(0);
                            if (bt_jammer_status_lbl) {
                                lv_label_set_text_fmt(bt_jammer_status_lbl, "Jamming %s...",
                                                      k_jam_bands[bt_jammer_band]);
                                lv_obj_set_style_text_color(bt_jammer_status_lbl, COLOR_MATERIAL_RED, 0);
                            }
                            bsp_display_unlock();
                        } else if (strstr(line_buffer, "[NRF24] detected")) {
                            bt_nrf24_present = 1;
                        }

                        line_pos = 0;
                    }
                } else if (line_pos < (int)sizeof(line_buffer) - 1) {
                    line_buffer[line_pos++] = c;
                }
            }
        }

        vTaskDelay(pdMS_TO_TICKS(50));
    }

    ESP_LOGI(TAG, "Jammer reader task ended");
    bt_jammer_task_handle = NULL;
    vTaskDelete(NULL);
}

// Band selector tap handler (ignored while jamming)
static void jammer_band_event_cb(lv_event_t *e)
{
    tab_context_t *ctx = get_current_ctx();
    if (ctx && ctx->bt_jamming) return;

    int idx = (int)(intptr_t)lv_event_get_user_data(e);
    if (idx < 0 || idx >= 5) return;

    bt_jammer_band = idx;
    for (int i = 0; i < 5; i++) {
        jammer_style_band_btn(bt_jammer_band_btns[i], i == idx);
    }
}

// Stop jamming and reset UI to idle (does not navigate)
static void jammer_stop(tab_context_t *ctx)
{
    if (!ctx || !ctx->bt_jamming) return;

    ctx->bt_jamming = false;
    uart_send_command_for_tab("stop");

    if (bt_jammer_task_handle != NULL) {
        vTaskDelay(pdMS_TO_TICKS(100));
        bt_jammer_task_handle = NULL;
    }

    jammer_set_bands_enabled(true);
    if (bt_jammer_big_btn) {
        lv_obj_set_style_bg_color(bt_jammer_big_btn, COLOR_MATERIAL_RED, 0);
    }
    if (bt_jammer_big_btn_lbl) {
        lv_label_set_text(bt_jammer_big_btn_lbl, LV_SYMBOL_PLAY "  Start Jammer");
    }
    if (bt_jammer_status_lbl) {
        lv_label_set_text(bt_jammer_status_lbl, "Idle");
        lv_obj_set_style_text_color(bt_jammer_status_lbl, ui_muted_color(), 0);
    }
}

// Big start/stop button handler
static void jammer_big_btn_event_cb(lv_event_t *e)
{
    (void)e;
    tab_context_t *ctx = get_current_ctx();
    if (!ctx) return;

    if (ctx->bt_jamming) {
        jammer_stop(ctx);
        return;
    }

    // Stop any in-flight detection probe so it doesn't consume the jam
    // command responses (both read the same UART).
    if (bt_jammer_probe_active) {
        bt_jammer_probe_active = false;
        for (int i = 0; i < 25 && bt_jammer_probe_handle; i++) vTaskDelay(pdMS_TO_TICKS(20));
    }

    ctx->bt_jamming = true;

    // Start the reader BEFORE sending commands so the detected / not-detected
    // / started responses are never missed (firmware replies within ms).
    xTaskCreate(bt_jammer_task, "bt_jammer", 4096, (void*)ctx, 5, &bt_jammer_task_handle);

    char cmd[32];
    snprintf(cmd, sizeof(cmd), "start_jammer24 %s", k_jam_bands[bt_jammer_band]);
    uart_send_command_for_tab("init_nrf24");
    uart_send_command_for_tab(cmd);

    jammer_set_bands_enabled(false);
    if (bt_jammer_big_btn) {
        lv_obj_set_style_bg_color(bt_jammer_big_btn, lv_color_hex(0x8B0000), 0);
    }
    if (bt_jammer_big_btn_lbl) {
        lv_label_set_text(bt_jammer_big_btn_lbl, LV_SYMBOL_STOP "  Stop Jammer");
    }
    if (bt_jammer_status_lbl) {
        lv_label_set_text_fmt(bt_jammer_status_lbl, "Starting %s...", k_jam_bands[bt_jammer_band]);
        lv_obj_set_style_text_color(bt_jammer_status_lbl, COLOR_MATERIAL_AMBER, 0);
    }
}

// Back to BT menu - always stops jamming first
static void jammer_back_btn_event_cb(lv_event_t *e)
{
    (void)e;
    tab_context_t *ctx = get_current_ctx();

    // Stop any in-flight nRF24 detection probe.
    if (bt_jammer_probe_active) {
        bt_jammer_probe_active = false;
        for (int i = 0; i < 25 && bt_jammer_probe_handle; i++) vTaskDelay(pdMS_TO_TICKS(20));
    }

    if (ctx && ctx->bt_jamming) {
        jammer_stop(ctx);
    } else {
        // Defensive: ensure firmware radio is idle even if UI thinks it's idle
        uart_send_command_for_tab("stop");
    }

    if (ctx && ctx->bt_jammer_page) {
        lv_obj_add_flag(ctx->bt_jammer_page, LV_OBJ_FLAG_HIDDEN);
    }

    if (ctx && ctx->bt_menu_page) {
        lv_obj_clear_flag(ctx->bt_menu_page, LV_OBJ_FLAG_HIDDEN);
        ctx->current_visible_page = ctx->bt_menu_page;
    }
}

// Kick a one-shot nRF24 detection probe (no-op while jamming / probing).
static void jammer_start_probe(tab_context_t *ctx)
{
    if (!ctx || ctx->bt_jamming) return;
    if (bt_jammer_probe_active) return;
    if (bt_jammer_status_lbl) {
        lv_label_set_text(bt_jammer_status_lbl, "Detecting nRF24...");
        lv_obj_set_style_text_color(bt_jammer_status_lbl, COLOR_MATERIAL_AMBER, 0);
    }
    bt_jammer_probe_active = true;
    if (xTaskCreate(bt_jammer_probe_task, "bt_jam_probe", 4096, (void *)ctx, 5,
                    &bt_jammer_probe_handle) != pdPASS) {
        bt_jammer_probe_active = false;
        ESP_LOGW(TAG, "Failed to start nRF24 probe task");
    }
}

// Show nRF24 Jammer page (inside current tab's container)
static void show_jammer_page(void)
{
    tab_context_t *ctx = get_current_ctx();
    lv_obj_t *container = get_current_tab_container();

    if (!container) {
        ESP_LOGE(TAG, "Container not initialized for tab %d", current_tab);
        return;
    }

    // Hide all other pages
    hide_all_pages(ctx);

    // If page already exists, just show it
    if (ctx->bt_jammer_page) {
        lv_obj_clear_flag(ctx->bt_jammer_page, LV_OBJ_FLAG_HIDDEN);
        ctx->current_visible_page = ctx->bt_jammer_page;
        bt_jammer_page = ctx->bt_jammer_page;
        if (!ctx->bt_jamming) jammer_start_probe(ctx);
        ESP_LOGI(TAG, "Showing existing Jammer page for tab %d", current_tab);
        return;
    }

    ESP_LOGI(TAG, "Creating new Jammer page for tab %d", current_tab);

    ctx->bt_jamming = false;

    // Create page container inside tab container
    ctx->bt_jammer_page = lv_obj_create(container);
    bt_jammer_page = ctx->bt_jammer_page;
    lv_obj_set_size(bt_jammer_page, lv_pct(100), lv_pct(100));
    lv_obj_set_style_bg_color(bt_jammer_page, ui_bg_color(), 0);
    lv_obj_set_style_border_width(bt_jammer_page, 0, 0);
    lv_obj_set_style_pad_all(bt_jammer_page, 10, 0);
    lv_obj_set_flex_flow(bt_jammer_page, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(bt_jammer_page, 10, 0);

    // Header
    lv_obj_t *header = lv_obj_create(bt_jammer_page);
    lv_obj_set_size(header, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(header, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(header, 0, 0);
    lv_obj_set_style_pad_all(header, 0, 0);
    lv_obj_set_flex_flow(header, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(header, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(header, 12, 0);
    lv_obj_clear_flag(header, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *back_btn = lv_btn_create(header);
    lv_obj_set_size(back_btn, 72, 60);
    style_back_nav_button(back_btn);
    lv_obj_add_event_cb(back_btn, jammer_back_btn_event_cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *back_icon = lv_label_create(back_btn);
    lv_label_set_text(back_icon, LV_SYMBOL_LEFT);
    lv_obj_set_style_text_color(back_icon, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(back_icon);

    lv_obj_t *title = lv_label_create(header);
    lv_label_set_text(title, "Jammer");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(title, dark_mode_enabled ? COLOR_LAB5_MAGENTA : ui_tab_icon_color(), 0);

    // Content container - centered column
    lv_obj_t *content = lv_obj_create(bt_jammer_page);
    lv_obj_set_size(content, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_grow(content, 1);
    lv_obj_set_style_bg_opa(content, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(content, 0, 0);
    lv_obj_set_style_pad_all(content, 20, 0);
    lv_obj_set_flex_flow(content, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(content, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(content, 24, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLLABLE);

    // Band selector row
    lv_obj_t *band_row = lv_obj_create(content);
    lv_obj_set_size(band_row, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(band_row, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(band_row, 0, 0);
    lv_obj_set_style_pad_all(band_row, 0, 0);
    lv_obj_set_flex_flow(band_row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(band_row, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(band_row, 12, 0);
    lv_obj_clear_flag(band_row, LV_OBJ_FLAG_SCROLLABLE);

    for (int i = 0; i < 5; i++) {
        lv_obj_t *btn = lv_btn_create(band_row);
        lv_obj_set_size(btn, 110, 56);
        lv_obj_set_style_radius(btn, 10, 0);
        jammer_style_band_btn(btn, i == bt_jammer_band);
        lv_obj_add_event_cb(btn, jammer_band_event_cb, LV_EVENT_CLICKED, (void*)(intptr_t)i);

        lv_obj_t *lbl = lv_label_create(btn);
        lv_label_set_text(lbl, k_jam_bands[i]);
        lv_obj_set_style_text_font(lbl, &lv_font_montserrat_18, 0);
        lv_obj_set_style_text_color(lbl, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(lbl);

        bt_jammer_band_btns[i] = btn;
    }

    // Big start/stop button
    bt_jammer_big_btn = lv_btn_create(content);
    lv_obj_set_size(bt_jammer_big_btn, 320, 80);
    lv_obj_set_style_radius(bt_jammer_big_btn, 16, 0);
    lv_obj_set_style_bg_color(bt_jammer_big_btn, COLOR_MATERIAL_RED, 0);
    lv_obj_add_event_cb(bt_jammer_big_btn, jammer_big_btn_event_cb, LV_EVENT_CLICKED, NULL);

    bt_jammer_big_btn_lbl = lv_label_create(bt_jammer_big_btn);
    lv_label_set_text(bt_jammer_big_btn_lbl, LV_SYMBOL_PLAY "  Start Jammer");
    lv_obj_set_style_text_font(bt_jammer_big_btn_lbl, &lv_font_montserrat_24, 0);
    lv_obj_set_style_text_color(bt_jammer_big_btn_lbl, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(bt_jammer_big_btn_lbl);

    // Status label
    bt_jammer_status_lbl = lv_label_create(content);
    lv_label_set_text(bt_jammer_status_lbl, "Idle");
    lv_obj_set_style_text_font(bt_jammer_status_lbl, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(bt_jammer_status_lbl, ui_muted_color(), 0);

    // Detect the nRF24 module up front so the user knows if it's attached.
    jammer_start_probe(ctx);

    // Set current visible page
    ctx->current_visible_page = ctx->bt_jammer_page;
}

//==================================================================================
// BT Scan Page
//==================================================================================

// Parse BT scan device line
// Format: "  N. XX:XX:XX:XX:XX:XX  RSSI: X dBm  Name: optional"
static bool parse_bt_device_line(const char *line, bt_device_t *dev)
{
    // Find MAC address pattern (XX:XX:XX:XX:XX:XX) in the line
    // Look for the pattern: two hex digits followed by colon, repeated
    const char *p = line;
    const char *mac_start = NULL;

    while (*p) {
        // Check if this could be start of a MAC address
        if (isxdigit((unsigned char)p[0]) && isxdigit((unsigned char)p[1]) && p[2] == ':') {
            // Verify it's a full MAC (17 chars: XX:XX:XX:XX:XX:XX)
            int colons = 0;
            bool valid = true;
            for (int i = 0; i < 17 && p[i]; i++) {
                if (i % 3 == 2) {
                    if (p[i] != ':' && i < 15) { valid = false; break; }
                    if (p[i] == ':') colons++;
                } else {
                    if (!isxdigit((unsigned char)p[i])) { valid = false; break; }
                }
            }
            if (valid && colons == 5) {
                mac_start = p;
                break;
            }
        }
        p++;
    }

    if (!mac_start) return false;

    // Copy MAC
    strncpy(dev->mac, mac_start, 17);
    dev->mac[17] = '\0';

    // Find RSSI
    const char *rssi_ptr = strstr(line, "RSSI:");
    if (rssi_ptr) {
        dev->rssi = atoi(rssi_ptr + 5);
    } else {
        dev->rssi = -100;
    }

    // Find Name
    const char *name_ptr = strstr(line, "Name:");
    if (name_ptr) {
        name_ptr += 5;
        while (*name_ptr == ' ') name_ptr++;
        strncpy(dev->name, name_ptr, sizeof(dev->name) - 1);
        dev->name[sizeof(dev->name) - 1] = '\0';
        // Trim trailing whitespace
        size_t len = strlen(dev->name);
        while (len > 0 && isspace((unsigned char)dev->name[len - 1])) {
            dev->name[--len] = '\0';
        }
    } else {
        dev->name[0] = '\0';
    }

    return true;
}

// Back to BT menu from BT scan page - hide page and show BT menu
static void bt_scan_back_btn_event_cb(lv_event_t *e)
{
    (void)e;
    tab_context_t *ctx = get_current_ctx();

    // Hide BT scan page
    if (ctx->bt_scan_page) {
        lv_obj_add_flag(ctx->bt_scan_page, LV_OBJ_FLAG_HIDDEN);
    }

    // Show BT menu
    if (ctx->bt_menu_page) {
        lv_obj_clear_flag(ctx->bt_menu_page, LV_OBJ_FLAG_HIDDEN);
        ctx->current_visible_page = ctx->bt_menu_page;
    }
}

// Rescan button callback
static void bt_scan_rescan_cb(lv_event_t *e)
{
    (void)e;
    ESP_LOGI(TAG, "BT Scan: Rescan clicked");
    show_bt_scan_page();
}

// Device click callback - opens locator tracking
static void bt_scan_device_click_cb(lv_event_t *e)
{
    int device_idx = (int)(intptr_t)lv_event_get_user_data(e);
    if (device_idx >= 0 && device_idx < bt_device_count) {
        show_bt_locator_page(device_idx);
    }
}

// Show BT Scan page (inside current tab's container)
static void show_bt_scan_page(void)
{
    tab_context_t *ctx = get_current_ctx();
    lv_obj_t *container = get_current_tab_container();

    if (!container) {
        ESP_LOGE(TAG, "Container not initialized for tab %d", current_tab);
        return;
    }

    // Hide all other pages
    hide_all_pages(ctx);

    // If page already exists, just show it
    if (ctx->bt_scan_page) {
        lv_obj_clear_flag(ctx->bt_scan_page, LV_OBJ_FLAG_HIDDEN);
        ctx->current_visible_page = ctx->bt_scan_page;
        bt_scan_page = ctx->bt_scan_page;
        ESP_LOGI(TAG, "Showing existing BT scan page for tab %d", current_tab);
        return;
    }

    ESP_LOGI(TAG, "Creating new BT scan page for tab %d", current_tab);

    // Create page container inside tab container
    ctx->bt_scan_page = lv_obj_create(container);
    bt_scan_page = ctx->bt_scan_page;
    lv_obj_set_size(bt_scan_page, lv_pct(100), lv_pct(100));
    lv_obj_set_style_bg_color(bt_scan_page, ui_bg_color(), 0);
    lv_obj_set_style_border_width(bt_scan_page, 0, 0);
    lv_obj_set_style_pad_all(bt_scan_page, 10, 0);
    lv_obj_set_flex_flow(bt_scan_page, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(bt_scan_page, 8, 0);

    // Header with back button, title, and rescan button
    lv_obj_t *header = lv_obj_create(bt_scan_page);
    lv_obj_set_size(header, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(header, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(header, 0, 0);
    lv_obj_set_style_pad_all(header, 0, 0);
    lv_obj_set_flex_flow(header, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(header, LV_FLEX_ALIGN_SPACE_BETWEEN, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(header, 10, 0);
    lv_obj_clear_flag(header, LV_OBJ_FLAG_SCROLLABLE);

    // Left side: Back + Title
    lv_obj_t *left_cont = lv_obj_create(header);
    lv_obj_set_size(left_cont, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(left_cont, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(left_cont, 0, 0);
    lv_obj_set_style_pad_all(left_cont, 0, 0);
    lv_obj_set_flex_flow(left_cont, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(left_cont, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(left_cont, 10, 0);
    lv_obj_clear_flag(left_cont, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *back_btn = lv_btn_create(left_cont);
    lv_obj_set_size(back_btn, 72, 60);
    style_back_nav_button(back_btn);
    lv_obj_add_event_cb(back_btn, bt_scan_back_btn_event_cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *back_icon = lv_label_create(back_btn);
    lv_label_set_text(back_icon, LV_SYMBOL_LEFT);
    lv_obj_set_style_text_color(back_icon, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(back_icon);

    lv_obj_t *title = lv_label_create(left_cont);
    lv_label_set_text(title, "BT Scan & Locate");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(title, dark_mode_enabled ? COLOR_LAB5_MAGENTA : ui_tab_icon_color(), 0);

    // Rescan button on right
    lv_obj_t *rescan_btn = lv_btn_create(header);
    lv_obj_set_size(rescan_btn, 100, 40);
    style_show_probes_button(rescan_btn);
    lv_obj_add_event_cb(rescan_btn, bt_scan_rescan_cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *rescan_label = lv_label_create(rescan_btn);
    lv_label_set_text(rescan_label, LV_SYMBOL_REFRESH " Rescan");
    lv_obj_set_style_text_font(rescan_label, &lv_font_montserrat_14, 0);
    lv_obj_center(rescan_label);

    // Loading container (shown during scan)
    lv_obj_t *loading_container = lv_obj_create(bt_scan_page);
    lv_obj_set_size(loading_container, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_grow(loading_container, 1);
    lv_obj_set_style_bg_opa(loading_container, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(loading_container, 0, 0);
    lv_obj_set_flex_flow(loading_container, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(loading_container, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(loading_container, LV_OBJ_FLAG_SCROLLABLE);

    // Spinner
    lv_obj_t *spinner = lv_spinner_create(loading_container);
    lv_obj_set_size(spinner, 60, 60);
    lv_spinner_set_anim_params(spinner, 1000, 200);

    lv_obj_t *loading_label = lv_label_create(loading_container);
    lv_label_set_text(loading_label, "Scanning for BT devices...");
    lv_obj_set_style_text_font(loading_label, &lv_font_montserrat_16, 0);
    lv_obj_set_style_text_color(loading_label, ui_muted_color(), 0);
    lv_obj_set_style_pad_top(loading_label, 20, 0);

    // Force UI refresh to show loading state - release display lock briefly
    lv_refr_now(NULL);
    bsp_display_unlock();
    vTaskDelay(pdMS_TO_TICKS(100));

    // Flush any stale UART data before scanning
    uart_port_t uart_port = uart_port_for_tab(current_tab);
    uart_flush_input(uart_port);

    // Send scan command to current tab's UART
    uart_send_command_for_tab("scan_bt");
    ESP_LOGI(TAG, "BT Scan: waiting for results (up to 15s)...");

    // Read data until we see "Summary:" or timeout
    static char rx_buffer[8192];
    int total_len = 0;
    bool summary_found = false;
    int timeout_ms = 15000;  // 15 second timeout
    int elapsed_ms = 0;

    while (!summary_found && elapsed_ms < timeout_ms && total_len < (int)sizeof(rx_buffer) - 256) {
        int len = transport_read_bytes(uart_port, rx_buffer + total_len, sizeof(rx_buffer) - total_len - 1, pdMS_TO_TICKS(200));
        if (len > 0) {
            total_len += len;
            rx_buffer[total_len] = '\0';

            // Check if we have the complete response
            if (strstr(rx_buffer, "Summary:") != NULL) {
                summary_found = true;
                ESP_LOGI(TAG, "BT Scan: Summary found, scan complete");
            }
        }
        elapsed_ms += 200;
    }

    ESP_LOGI(TAG, "BT Scan response (%d bytes, summary=%s)", total_len, summary_found ? "yes" : "no");

    // Re-acquire display lock
    bsp_display_lock(0);

    // Remove loading indicator
    lv_obj_del(loading_container);

    // Status label
    lv_obj_t *status_label = lv_label_create(bt_scan_page);
    lv_obj_set_style_text_font(status_label, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(status_label, ui_muted_color(), 0);

    // Scrollable list container
    lv_obj_t *list_container = lv_obj_create(bt_scan_page);
    lv_obj_set_size(list_container, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_grow(list_container, 1);
    style_surface_panel(list_container, 8);
    lv_obj_set_style_pad_all(list_container, 8, 0);
    lv_obj_set_flex_flow(list_container, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(list_container, 6, 0);

    // Parse devices
    bt_device_count = 0;
    char *line = strtok(rx_buffer, "\n\r");
    while (line != NULL && bt_device_count < BT_MAX_DEVICES) {
        // Look for device lines (contain MAC pattern and RSSI)
        if (strstr(line, "RSSI:") != NULL && strchr(line, ':') != NULL) {
            bt_device_t dev;
            if (parse_bt_device_line(line, &dev)) {
                bt_devices[bt_device_count++] = dev;
            }
        }
        line = strtok(NULL, "\n\r");
    }

    // Display clickable devices
    for (int i = 0; i < bt_device_count; i++) {
        bt_device_t *dev = &bt_devices[i];

        lv_obj_t *row = lv_obj_create(list_container);
        lv_obj_set_size(row, lv_pct(100), LV_SIZE_CONTENT);
        lv_obj_set_style_bg_color(row, ui_card_color(), 0);
        lv_obj_set_style_bg_color(row, ui_card_pressed_color(), LV_STATE_PRESSED);
        lv_obj_set_style_border_width(row, 1, 0);
        lv_obj_set_style_border_color(row, ui_border_color(), 0);
        lv_obj_set_style_border_opa(row, dark_mode_enabled ? LV_OPA_40 : LV_OPA_70, 0);
        lv_obj_set_style_radius(row, 6, 0);
        lv_obj_set_style_pad_all(row, 10, 0);
        lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_event_cb(row, bt_scan_device_click_cb, LV_EVENT_CLICKED, (void*)(intptr_t)i);

        // Name or MAC
        lv_obj_t *name_lbl = lv_label_create(row);
        if (strlen(dev->name) > 0) {
            lv_label_set_text(name_lbl, dev->name);
            lv_obj_set_flex_grow(name_lbl, 1);
            lv_label_set_long_mode(name_lbl, LV_LABEL_LONG_DOT);
        } else {
            // No name - show full MAC address without truncation
            lv_label_set_text(name_lbl, dev->mac);
            lv_obj_set_width(name_lbl, 155);  // Fixed width for MAC
        }
        lv_obj_set_style_text_font(name_lbl, &lv_font_montserrat_14, 0);
        lv_obj_set_style_text_color(name_lbl, ui_text_color(), 0);

        // MAC (if name exists, show MAC too)
        if (strlen(dev->name) > 0) {
            lv_obj_t *mac_lbl = lv_label_create(row);
            lv_label_set_text(mac_lbl, dev->mac);
            lv_obj_set_style_text_font(mac_lbl, &lv_font_montserrat_12, 0);
            lv_obj_set_style_text_color(mac_lbl, ui_muted_color(), 0);
            lv_obj_set_width(mac_lbl, 155);  // Full MAC width (17 chars)
        }

        // RSSI
        lv_obj_t *rssi_lbl = lv_label_create(row);
        lv_label_set_text_fmt(rssi_lbl, "%d dBm", dev->rssi);
        lv_obj_set_style_text_font(rssi_lbl, &lv_font_montserrat_14, 0);
        if (dev->rssi > -50) {
            lv_obj_set_style_text_color(rssi_lbl, COLOR_MATERIAL_GREEN, 0);
        } else if (dev->rssi > -70) {
            lv_obj_set_style_text_color(rssi_lbl, COLOR_MATERIAL_AMBER, 0);
        } else {
            lv_obj_set_style_text_color(rssi_lbl, COLOR_MATERIAL_RED, 0);
        }
        lv_obj_set_width(rssi_lbl, 70);
    }

    lv_label_set_text_fmt(status_label, "Tap device to locate (%d found)", bt_device_count);

    // Set current visible page
    ctx->current_visible_page = ctx->bt_scan_page;
}

//==================================================================================
// BT Locator Tracking Page
//==================================================================================

// ============================================================================
// AP Radar (WiFi AP locator)
// ============================================================================

static float ap_radar_rssi_to_dist_frac(int rssi_dbm)
{
    if (rssi_dbm >= AP_RADAR_RSSI_CENTER) return 0.0f;
    if (rssi_dbm <= AP_RADAR_RSSI_EDGE) return 1.0f;
    return (float)(AP_RADAR_RSSI_CENTER - rssi_dbm)
         / (float)(AP_RADAR_RSSI_CENTER - AP_RADAR_RSSI_EDGE);
}

static lv_color_t ap_radar_rssi_color(int rssi_dbm)
{
    if (rssi_dbm > -50) return COLOR_MATERIAL_GREEN;
    if (rssi_dbm > -70) return COLOR_MATERIAL_AMBER;
    return COLOR_MATERIAL_RED;
}

static bool parse_ap_locator_line(const char *line, int *out_rssi)
{
    if (!line || !out_rssi) return false;
    if (strstr(line, "[AP Locator]") == NULL) return false;

    const char *rssi_ptr = strstr(line, "RSSI:");
    if (!rssi_ptr) return false;

    *out_rssi = atoi(rssi_ptr + 5);
    return true;
}

static void ap_radar_stop_locator(void)
{
    if (ap_radar_running) {
        uart_send_command_for_tab("stop");
        ap_radar_running = false;

        tab_context_t *ctx = get_current_ctx();
        if (ctx) {
            ctx->ap_radar_running = false;
        }

        if (ap_radar_task_handle != NULL) {
            vTaskDelay(pdMS_TO_TICKS(100));
            ap_radar_task_handle = NULL;
        }
    }
}

static void ap_radar_sweep_timer_cb(lv_timer_t *timer)
{
    (void)timer;
    ap_radar_sweep_angle = (ap_radar_sweep_angle + 12) % 360;
    if (ap_radar_panel) {
        lv_obj_invalidate(ap_radar_panel);
    }
}

static void ap_radar_panel_draw_cb(lv_event_t *e)
{
    lv_event_code_t code = lv_event_get_code(e);
    if (code != LV_EVENT_DRAW_MAIN) return;

    lv_obj_t *obj = lv_event_get_target_obj(e);
    lv_layer_t *layer = lv_event_get_layer(e);

    lv_area_t coords;
    lv_obj_get_coords(obj, &coords);
    int32_t w = lv_area_get_width(&coords);
    int32_t h = lv_area_get_height(&coords);
    int32_t cx = coords.x1 + w / 2;
    int32_t cy = coords.y1 + h / 2;
    int32_t max_r = (w < h ? w : h) / 2 - 12;
    if (max_r < 20) max_r = 20;

    lv_color_t grid_col = lv_color_hex(0x1E4D3A);
    lv_color_t axis_col = lv_color_hex(0x2E6B52);
    lv_color_t sweep_col = lv_color_hex(0x33FF99);

    for (int ring = 1; ring <= 4; ring++) {
        int32_t r = max_r * ring / 4;
        lv_draw_arc_dsc_t arc_dsc;
        lv_draw_arc_dsc_init(&arc_dsc);
        arc_dsc.base.layer = layer;
        arc_dsc.color = grid_col;
        arc_dsc.width = 1;
        arc_dsc.center.x = cx;
        arc_dsc.center.y = cy;
        arc_dsc.radius = r;
        arc_dsc.start_angle = 0;
        arc_dsc.end_angle = 360;
        arc_dsc.opa = LV_OPA_60;
        lv_draw_arc(layer, &arc_dsc);
    }

    lv_draw_line_dsc_t line_dsc;
    lv_draw_line_dsc_init(&line_dsc);
    line_dsc.base.layer = layer;
    line_dsc.color = axis_col;
    line_dsc.width = 1;
    line_dsc.opa = LV_OPA_50;

    line_dsc.p1.x = cx - max_r;
    line_dsc.p1.y = cy;
    line_dsc.p2.x = cx + max_r;
    line_dsc.p2.y = cy;
    lv_draw_line(layer, &line_dsc);

    line_dsc.p1.x = cx;
    line_dsc.p1.y = cy - max_r;
    line_dsc.p2.x = cx;
    line_dsc.p2.y = cy + max_r;
    lv_draw_line(layer, &line_dsc);

    int16_t sweep = (int16_t)ap_radar_sweep_angle;
    int32_t sx = cx + (max_r * lv_trigo_cos(sweep)) / 32767;
    int32_t sy = cy + (max_r * lv_trigo_sin(sweep)) / 32767;

    line_dsc.color = sweep_col;
    line_dsc.width = 2;
    line_dsc.opa = LV_OPA_70;
    line_dsc.p1.x = cx;
    line_dsc.p1.y = cy;
    line_dsc.p2.x = sx;
    line_dsc.p2.y = sy;
    lv_draw_line(layer, &line_dsc);

    int32_t blip_r_px = (int32_t)(ap_radar_blip_dist_frac * max_r);
    int32_t bx = cx;
    int32_t by = cy - blip_r_px;

    lv_area_t blip_area;
    blip_area.x1 = bx - 8;
    blip_area.y1 = by - 8;
    blip_area.x2 = bx + 7;
    blip_area.y2 = by + 7;

    lv_draw_rect_dsc_t rect_dsc;
    lv_draw_rect_dsc_init(&rect_dsc);
    rect_dsc.base.layer = layer;
    rect_dsc.bg_color = ap_radar_rssi_color(ap_radar_last_rssi);
    rect_dsc.bg_opa = LV_OPA_COVER;
    rect_dsc.radius = LV_RADIUS_CIRCLE;
    rect_dsc.border_width = 0;
    lv_draw_rect(layer, &rect_dsc, &blip_area);
}

static void ap_radar_monitor_task(void *arg)
{
    tab_context_t *ctx = (tab_context_t *)arg;
    tab_id_t task_tab = tab_id_for_ctx(ctx);
    uart_port_t uart_port = (task_tab == TAB_MBUS && uart2_initialized) ? UART2_NUM : UART_NUM;
    const char *uart_name = tab_transport_name(task_tab);

    ESP_LOGI(TAG, "[%s][AP_RADAR] Monitor task started for tab %d", uart_name, task_tab);

    static char rx_buffer[256];
    static char line_buffer[192];
    int line_pos = 0;

    while (ctx && ctx->ap_radar_running) {
        int len = transport_read_bytes(uart_port, rx_buffer, sizeof(rx_buffer) - 1, pdMS_TO_TICKS(100));

        if (len > 0) {
            rx_buffer[len] = '\0';

            for (int i = 0; i < len; i++) {
                char c = rx_buffer[i];

                if (c == '\n' || c == '\r') {
                    if (line_pos > 0) {
                        line_buffer[line_pos] = '\0';

                        int rssi = 0;
                        if (parse_ap_locator_line(line_buffer, &rssi)) {
                            ap_radar_last_rssi = rssi;
                            ap_radar_blip_dist_frac = ap_radar_rssi_to_dist_frac(rssi);

                            bsp_display_lock(0);
                            if (ap_radar_rssi_label) {
                                lv_label_set_text_fmt(ap_radar_rssi_label, "%d dBm", rssi);
                                lv_obj_set_style_text_color(ap_radar_rssi_label,
                                                            ap_radar_rssi_color(rssi), 0);
                            }
                            if (ap_radar_panel) {
                                lv_obj_invalidate(ap_radar_panel);
                            }
                            bsp_display_unlock();
                        }

                        line_pos = 0;
                    }
                } else if (line_pos < (int)sizeof(line_buffer) - 1) {
                    line_buffer[line_pos++] = c;
                }
            }
        }

        vTaskDelay(pdMS_TO_TICKS(50));
    }

    ESP_LOGI(TAG, "[AP_RADAR] Monitor task ended");
    ap_radar_task_handle = NULL;
    vTaskDelete(NULL);
}

static void ap_radar_return_to_scan(void)
{
    ap_radar_stop_locator();

    if (ap_radar_sweep_timer) {
        lv_timer_del(ap_radar_sweep_timer);
        ap_radar_sweep_timer = NULL;
    }

    tab_context_t *ctx = get_current_ctx();
    if (!ctx) return;

    if (ctx->ap_radar_page) {
        lv_obj_add_flag(ctx->ap_radar_page, LV_OBJ_FLAG_HIDDEN);
    }

    if (ctx->scan_page) {
        lv_obj_clear_flag(ctx->scan_page, LV_OBJ_FLAG_HIDDEN);
        ctx->current_visible_page = ctx->scan_page;
    }
}

static void ap_radar_back_btn_event_cb(lv_event_t *e)
{
    (void)e;
    ap_radar_return_to_scan();
}

static void ap_radar_stop_btn_event_cb(lv_event_t *e)
{
    (void)e;
    ap_radar_return_to_scan();
}

static void show_ap_radar_page(int network_idx)
{
    tab_context_t *ctx = get_current_ctx();
    if (!ctx) return;

    if (network_idx < 0 || network_idx >= ctx->network_count) return;

    wifi_network_t *net = &ctx->networks[network_idx];

    strncpy(ap_radar_target_ssid, net->ssid, sizeof(ap_radar_target_ssid) - 1);
    ap_radar_target_ssid[sizeof(ap_radar_target_ssid) - 1] = '\0';
    strncpy(ap_radar_target_bssid, net->bssid, sizeof(ap_radar_target_bssid) - 1);
    ap_radar_target_bssid[sizeof(ap_radar_target_bssid) - 1] = '\0';
    ap_radar_target_channel = net->channel;

    ap_radar_blip_dist_frac = ap_radar_rssi_to_dist_frac(net->rssi);
    ap_radar_last_rssi = net->rssi;
    ap_radar_sweep_angle = 0;

    lv_obj_t *container = get_current_tab_container();
    if (!container) {
        ESP_LOGE(TAG, "Container not initialized for AP Radar");
        return;
    }

    ap_radar_stop_locator();
    if (ap_radar_sweep_timer) {
        lv_timer_del(ap_radar_sweep_timer);
        ap_radar_sweep_timer = NULL;
    }

    hide_all_pages(ctx);

    if (ctx->ap_radar_page) {
        lv_obj_del(ctx->ap_radar_page);
        ctx->ap_radar_page = NULL;
        ap_radar_page = NULL;
        ap_radar_panel = NULL;
        ap_radar_rssi_label = NULL;
    }

    if (ctx->scan_page) {
        lv_obj_add_flag(ctx->scan_page, LV_OBJ_FLAG_HIDDEN);
    }

    ctx->ap_radar_page = lv_obj_create(container);
    ap_radar_page = ctx->ap_radar_page;
    lv_obj_set_size(ap_radar_page, lv_pct(100), lv_pct(100));
    lv_obj_set_style_bg_color(ap_radar_page, ui_bg_color(), 0);
    lv_obj_set_style_border_width(ap_radar_page, 0, 0);
    lv_obj_set_style_pad_all(ap_radar_page, 10, 0);
    lv_obj_set_flex_flow(ap_radar_page, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(ap_radar_page, 8, 0);

    lv_obj_t *header = lv_obj_create(ap_radar_page);
    lv_obj_set_size(header, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(header, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(header, 0, 0);
    lv_obj_set_style_pad_all(header, 0, 0);
    lv_obj_set_flex_flow(header, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(header, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(header, 12, 0);
    lv_obj_clear_flag(header, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *back_btn = lv_btn_create(header);
    lv_obj_set_size(back_btn, 72, 60);
    style_back_nav_button(back_btn);
    lv_obj_add_event_cb(back_btn, ap_radar_back_btn_event_cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *back_icon = lv_label_create(back_btn);
    lv_label_set_text(back_icon, LV_SYMBOL_LEFT);
    lv_obj_set_style_text_color(back_icon, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(back_icon);

    lv_obj_t *title_col = lv_obj_create(header);
    lv_obj_set_size(title_col, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(title_col, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(title_col, 0, 0);
    lv_obj_set_style_pad_all(title_col, 0, 0);
    lv_obj_set_flex_flow(title_col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(title_col, 2, 0);
    lv_obj_clear_flag(title_col, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *title = lv_label_create(title_col);
    lv_label_set_text(title, LV_SYMBOL_GPS "  AP Radar");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(title, COLOR_MATERIAL_BLUE, 0);

    lv_obj_t *subtitle = lv_label_create(title_col);
    const char *ssid_display = strlen(ap_radar_target_ssid) > 0 ? ap_radar_target_ssid : "(Hidden)";
    lv_label_set_text_fmt(subtitle, "%s  |  %s  |  Ch %d",
                          ssid_display, ap_radar_target_bssid, ap_radar_target_channel);
    lv_obj_set_style_text_font(subtitle, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(subtitle, ui_muted_color(), 0);

    ap_radar_panel = lv_obj_create(ap_radar_page);
    lv_obj_set_width(ap_radar_panel, lv_pct(100));
    lv_obj_set_flex_grow(ap_radar_panel, 1);
    lv_obj_set_style_min_height(ap_radar_panel, 360, 0);
    lv_obj_set_style_bg_color(ap_radar_panel, lv_color_hex(0x0A1A12), 0);
    lv_obj_set_style_border_color(ap_radar_panel, COLOR_MATERIAL_GREEN, 0);
    lv_obj_set_style_border_width(ap_radar_panel, 1, 0);
    lv_obj_set_style_border_opa(ap_radar_panel, LV_OPA_40, 0);
    lv_obj_set_style_radius(ap_radar_panel, 12, 0);
    lv_obj_clear_flag(ap_radar_panel, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_event_cb(ap_radar_panel, ap_radar_panel_draw_cb, LV_EVENT_DRAW_MAIN, NULL);

    ap_radar_rssi_label = lv_label_create(ap_radar_page);
    lv_label_set_text_fmt(ap_radar_rssi_label, "%d dBm", ap_radar_last_rssi);
    lv_obj_set_style_text_font(ap_radar_rssi_label, &lv_font_montserrat_28, 0);
    lv_obj_set_style_text_color(ap_radar_rssi_label, ap_radar_rssi_color(ap_radar_last_rssi), 0);
    lv_obj_set_style_text_align(ap_radar_rssi_label, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_set_width(ap_radar_rssi_label, lv_pct(100));

    lv_obj_t *stop_btn = lv_btn_create(ap_radar_page);
    lv_obj_set_size(stop_btn, lv_pct(100), 56);
    lv_obj_set_style_bg_color(stop_btn, COLOR_MATERIAL_RED, 0);
    lv_obj_set_style_bg_color(stop_btn, lv_color_darken(COLOR_MATERIAL_RED, LV_OPA_20), LV_STATE_PRESSED);
    lv_obj_set_style_radius(stop_btn, 10, 0);
    lv_obj_add_event_cb(stop_btn, ap_radar_stop_btn_event_cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *stop_lbl = lv_label_create(stop_btn);
    lv_label_set_text(stop_lbl, LV_SYMBOL_STOP "  STOP");
    lv_obj_set_style_text_font(stop_lbl, &lv_font_montserrat_18, 0);
    lv_obj_set_style_text_color(stop_lbl, lv_color_white(), 0);
    lv_obj_center(stop_lbl);

    ap_radar_sweep_timer = lv_timer_create(ap_radar_sweep_timer_cb, 50, NULL);

    ap_radar_running = true;
    ctx->ap_radar_running = true;

    xTaskCreate(ap_radar_monitor_task, "ap_radar", 4096, (void *)ctx, 5, &ap_radar_task_handle);

    ctx->current_visible_page = ctx->ap_radar_page;
    ESP_LOGI(TAG, "AP Radar page shown for %s", ap_radar_target_ssid);
}

// Back to BT scan from locator tracking - hide page and show BT scan
static void bt_locator_tracking_back_btn_event_cb(lv_event_t *e)
{
    (void)e;

    // Stop tracking
    if (bt_locator_tracking) {
        uart_send_command_for_tab("stop");
        bt_locator_tracking = false;
        if (bt_locator_task_handle != NULL) {
            vTaskDelay(pdMS_TO_TICKS(100));
            bt_locator_task_handle = NULL;
        }
    }

    tab_context_t *ctx = get_current_ctx();

    // Hide locator tracking page
    if (ctx->bt_locator_page) {
        lv_obj_add_flag(ctx->bt_locator_page, LV_OBJ_FLAG_HIDDEN);
    }

    // Show BT scan page
    if (ctx->bt_scan_page) {
        lv_obj_clear_flag(ctx->bt_scan_page, LV_OBJ_FLAG_HIDDEN);
        ctx->current_visible_page = ctx->bt_scan_page;
    }
}

static void bt_locator_tracking_task(void *arg)
{
    // Get context passed to task
    tab_context_t *ctx = (tab_context_t *)arg;

    // Determine UART from context
    tab_id_t task_tab = tab_id_for_ctx(ctx);
    uart_port_t uart_port = (task_tab == TAB_MBUS && uart2_initialized) ? UART2_NUM : UART_NUM;
    const char *uart_name = tab_transport_name(task_tab);

    ESP_LOGI(TAG, "[%s][BT_LOC] Task started for tab %d, target MAC: '%s'", uart_name, task_tab, bt_locator_target_mac);

    static char rx_buffer[256];
    static char line_buffer[128];
    int line_pos = 0;
    int total_bytes_received = 0;
    int lines_parsed = 0;
    int matches_found = 0;

    // Use context's flag
    while (ctx && ctx->bt_locator_tracking) {
        int len = transport_read_bytes(uart_port, rx_buffer, sizeof(rx_buffer) - 1, pdMS_TO_TICKS(100));

        if (len > 0) {
            rx_buffer[len] = '\0';
            total_bytes_received += len;
            ESP_LOGD(TAG, "[BT_LOC] UART RX %d bytes (total: %d)", len, total_bytes_received);

            for (int i = 0; i < len; i++) {
                char c = rx_buffer[i];

                if (c == '\n' || c == '\r') {
                    if (line_pos > 0) {
                        line_buffer[line_pos] = '\0';
                        lines_parsed++;

                        ESP_LOGI(TAG, "[BT_LOC] Line #%d: '%s'", lines_parsed, line_buffer);

                        // Check if line contains our target MAC
                        if (strstr(line_buffer, bt_locator_target_mac) != NULL) {
                            matches_found++;
                            ESP_LOGI(TAG, "[BT_LOC] MAC match #%d found!", matches_found);

                            // Check if device is out of range
                            if (strstr(line_buffer, "not found") != NULL) {
                                ESP_LOGI(TAG, "[BT_LOC] Device out of range");
                                bsp_display_lock(0);
                                if (bt_locator_rssi_label) {
                                    lv_label_set_text(bt_locator_rssi_label, "No signal");
                                    lv_obj_set_style_text_font(bt_locator_rssi_label, &lv_font_montserrat_32, 0);
                                    lv_obj_set_style_text_color(bt_locator_rssi_label, ui_muted_color(), 0);
                                }
                                bsp_display_unlock();
                            } else {
                                // Parse RSSI
                                const char *rssi_ptr = strstr(line_buffer, "RSSI:");
                                if (rssi_ptr) {
                                    int rssi = atoi(rssi_ptr + 5);
                                    ESP_LOGI(TAG, "[BT_LOC] RSSI parsed: %d dBm", rssi);

                                    bsp_display_lock(0);
                                    if (bt_locator_rssi_label) {
                                        lv_label_set_text_fmt(bt_locator_rssi_label, "%d dBm", rssi);
                                        lv_obj_set_style_text_font(bt_locator_rssi_label, &lv_font_montserrat_44, 0);
                                        if (rssi > -50) {
                                            lv_obj_set_style_text_color(bt_locator_rssi_label, COLOR_MATERIAL_GREEN, 0);
                                        } else if (rssi > -70) {
                                            lv_obj_set_style_text_color(bt_locator_rssi_label, COLOR_MATERIAL_AMBER, 0);
                                        } else {
                                            lv_obj_set_style_text_color(bt_locator_rssi_label, COLOR_MATERIAL_RED, 0);
                                        }
                                        ESP_LOGI(TAG, "[BT_LOC] UI updated with RSSI %d", rssi);
                                    } else {
                                        ESP_LOGW(TAG, "[BT_LOC] bt_locator_rssi_label is NULL!");
                                    }
                                    bsp_display_unlock();
                                } else {
                                    ESP_LOGW(TAG, "[BT_LOC] MAC matched but no RSSI: found in line '%s'", line_buffer);
                                }
                            }
                        }

                        line_pos = 0;
                    }
                } else if (line_pos < (int)sizeof(line_buffer) - 1) {
                    line_buffer[line_pos++] = c;
                }
            }
        }

        vTaskDelay(pdMS_TO_TICKS(50));
    }

    ESP_LOGI(TAG, "[BT_LOC] Task ended - total bytes: %d, lines: %d, matches: %d",
             total_bytes_received, lines_parsed, matches_found);
    bt_locator_task_handle = NULL;
    vTaskDelete(NULL);
}

// Show BT Locator Tracking page (inside current tab's container)
static void show_bt_locator_page(int device_idx)
{
    if (device_idx < 0 || device_idx >= bt_device_count) return;

    bt_device_t *dev = &bt_devices[device_idx];

    // Save target info
    strncpy(bt_locator_target_mac, dev->mac, sizeof(bt_locator_target_mac) - 1);
    strncpy(bt_locator_target_name, dev->name, sizeof(bt_locator_target_name) - 1);

    tab_context_t *ctx = get_current_ctx();
    lv_obj_t *container = get_current_tab_container();

    if (!container) {
        ESP_LOGE(TAG, "Container not initialized for tab %d", current_tab);
        return;
    }

    // Hide all other pages
    hide_all_pages(ctx);

    // Note: Locator tracking page is not cached - always recreate
    // because it depends on the selected device
    if (ctx->bt_locator_page) {
        lv_obj_del(ctx->bt_locator_page);
        ctx->bt_locator_page = NULL;
    }

    ESP_LOGI(TAG, "Creating new BT locator tracking page for tab %d", current_tab);

    // Create page container inside tab container
    ctx->bt_locator_page = lv_obj_create(container);
    bt_locator_page = ctx->bt_locator_page;
    lv_obj_set_size(bt_locator_page, lv_pct(100), lv_pct(100));
    lv_obj_set_style_bg_color(bt_locator_page, ui_bg_color(), 0);
    lv_obj_set_style_border_width(bt_locator_page, 0, 0);
    lv_obj_set_style_pad_all(bt_locator_page, 10, 0);
    lv_obj_set_flex_flow(bt_locator_page, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(bt_locator_page, 10, 0);

    // Header
    lv_obj_t *header = lv_obj_create(bt_locator_page);
    lv_obj_set_size(header, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(header, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(header, 0, 0);
    lv_obj_set_style_pad_all(header, 0, 0);
    lv_obj_set_flex_flow(header, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(header, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(header, 12, 0);
    lv_obj_clear_flag(header, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *back_btn = lv_btn_create(header);
    lv_obj_set_size(back_btn, 72, 60);
    style_back_nav_button(back_btn);
    lv_obj_add_event_cb(back_btn, bt_locator_tracking_back_btn_event_cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *back_icon = lv_label_create(back_btn);
    lv_label_set_text(back_icon, LV_SYMBOL_LEFT);
    lv_obj_set_style_text_color(back_icon, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(back_icon);

    lv_obj_t *title = lv_label_create(header);
    lv_label_set_text(title, "BT Locator - Tracking");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(title, dark_mode_enabled ? COLOR_LAB5_MAGENTA : ui_tab_icon_color(), 0);

    // Content container - centered
    lv_obj_t *content = lv_obj_create(bt_locator_page);
    lv_obj_set_size(content, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_grow(content, 1);
    lv_obj_set_style_bg_opa(content, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(content, 0, 0);
    lv_obj_set_style_pad_all(content, 20, 0);
    lv_obj_set_flex_flow(content, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(content, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(content, 20, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLLABLE);

    // Device name/MAC
    lv_obj_t *name_lbl = lv_label_create(content);
    if (strlen(bt_locator_target_name) > 0) {
        lv_label_set_text(name_lbl, bt_locator_target_name);
    } else {
        lv_label_set_text(name_lbl, bt_locator_target_mac);
    }
    lv_obj_set_style_text_font(name_lbl, &lv_font_montserrat_24, 0);
    lv_obj_set_style_text_color(name_lbl, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_text_align(name_lbl, LV_TEXT_ALIGN_CENTER, 0);

    // MAC (if name shown)
    if (strlen(bt_locator_target_name) > 0) {
        lv_obj_t *mac_lbl = lv_label_create(content);
        lv_label_set_text(mac_lbl, bt_locator_target_mac);
        lv_obj_set_style_text_font(mac_lbl, &lv_font_montserrat_16, 0);
        lv_obj_set_style_text_color(mac_lbl, ui_muted_color(), 0);
    }

    // RSSI display box
    lv_obj_t *rssi_box = lv_obj_create(content);
    lv_obj_set_size(rssi_box, 250, 150);
    style_surface_panel(rssi_box, 16);
    lv_obj_set_style_border_color(rssi_box, ui_tab_icon_color(), 0);
    lv_obj_set_style_border_opa(rssi_box, dark_mode_enabled ? LV_OPA_70 : LV_OPA_90, 0);
    lv_obj_set_style_pad_all(rssi_box, 15, 0);
    lv_obj_set_flex_flow(rssi_box, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(rssi_box, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(rssi_box, LV_OBJ_FLAG_SCROLLABLE);

    bt_locator_rssi_label = lv_label_create(rssi_box);
    lv_label_set_text_fmt(bt_locator_rssi_label, "%d dBm", dev->rssi);
    lv_obj_set_style_text_font(bt_locator_rssi_label, &lv_font_montserrat_44, 0);
    if (dev->rssi > -50) {
        lv_obj_set_style_text_color(bt_locator_rssi_label, COLOR_MATERIAL_GREEN, 0);
    } else if (dev->rssi > -70) {
        lv_obj_set_style_text_color(bt_locator_rssi_label, COLOR_MATERIAL_AMBER, 0);
    } else {
        lv_obj_set_style_text_color(bt_locator_rssi_label, COLOR_MATERIAL_RED, 0);
    }

    lv_obj_t *rssi_title = lv_label_create(rssi_box);
    lv_label_set_text(rssi_title, "Signal Strength");
    lv_obj_set_style_text_font(rssi_title, &lv_font_montserrat_16, 0);
    lv_obj_set_style_text_color(rssi_title, ui_muted_color(), 0);

    // Start tracking
    char cmd[64];
    snprintf(cmd, sizeof(cmd), "scan_bt %s", bt_locator_target_mac);
    ESP_LOGI(TAG, "[BT_LOC] Sending UART command: '%s'", cmd);
    uart_send_command_for_tab(cmd);
    ESP_LOGI(TAG, "[BT_LOC] Command sent, starting monitor task");

    bt_locator_tracking = true;

    // Also mark in context
    tab_context_t *loc_ctx = get_current_ctx();
    if (loc_ctx) {
        loc_ctx->bt_locator_tracking = true;
    }

    xTaskCreate(bt_locator_tracking_task, "bt_locator", 4096, (void*)loc_ctx, 5, &bt_locator_task_handle);
    ESP_LOGI(TAG, "[BT_LOC] Monitor task created, tracking_page=%p, rssi_label=%p",
             (void*)bt_locator_page, (void*)bt_locator_rssi_label);

    // Set current visible page
    ctx->current_visible_page = ctx->bt_locator_page;
}

static void beacon_spam_escape_quoted_arg(const char *src, char *dst, size_t dst_size)
{
    if (!dst || dst_size == 0) return;
    dst[0] = '\0';
    if (!src) return;

    size_t out = 0;
    for (size_t i = 0; src[i] != '\0' && out + 1 < dst_size; i++) {
        char c = src[i];
        if ((c == '"' || c == '\\') && out + 2 < dst_size) {
            dst[out++] = '\\';
        }
        if (out + 1 < dst_size) {
            dst[out++] = c;
        }
    }
    dst[out] = '\0';
}

static bool build_wifi_connect_command(char *out, size_t out_sz, const char *ssid,
                                       const char *password, wifi_connect_auth_mode_t mode)
{
    if (!out || out_sz == 0 || !ssid || ssid[0] == '\0') {
        return false;
    }

    char escaped_ssid[67];
    char escaped_password[131];
    beacon_spam_escape_quoted_arg(ssid, escaped_ssid, sizeof(escaped_ssid));

    int cmd_len = 0;
    if (mode == WIFI_CONNECT_AUTH_SAVED) {
        cmd_len = snprintf(out, out_sz, "wifi_connect \"%s\" --saved", escaped_ssid);
    } else if (mode == WIFI_CONNECT_AUTH_PASSWORD && password && password[0] != '\0') {
        beacon_spam_escape_quoted_arg(password, escaped_password, sizeof(escaped_password));
        cmd_len = snprintf(out, out_sz, "wifi_connect \"%s\" \"%s\"",
                           escaped_ssid, escaped_password);
    } else {
        cmd_len = snprintf(out, out_sz, "wifi_connect \"%s\"", escaped_ssid);
    }

    return cmd_len >= 0 && cmd_len < (int)out_sz;
}

static bool wifi_network_security_is_open(const char *security)
{
    if (!security || security[0] == '\0') {
        return true;
    }
    char upper[32];
    size_t i = 0;
    for (; security[i] && i < sizeof(upper) - 1; i++) {
        upper[i] = (char)toupper((unsigned char)security[i]);
    }
    upper[i] = '\0';

    if (strstr(upper, "OPEN") || strstr(upper, "UNKNOWN") || strstr(upper, "OWE")) {
        return true;
    }
    if (strstr(upper, "WPA") || strstr(upper, "WEP") ||
        strstr(upper, "SAE") || strstr(upper, "PSK")) {
        return false;
    }
    return true;
}

static void beacon_spam_trim_whitespace(char *text)
{
    if (!text) return;
    char *start = text;
    while (*start && isspace((unsigned char)*start)) {
        start++;
    }
    if (start != text) {
        memmove(text, start, strlen(start) + 1);
    }
    trim_trailing_whitespace(text);
}

static void close_beacon_ssids_add_popup(tab_context_t *ctx)
{
    if (!ctx) return;
    if (ctx->beacon_ssids_add_overlay) {
        lv_obj_del(ctx->beacon_ssids_add_overlay);
    }
    ctx->beacon_ssids_add_overlay = NULL;
    ctx->beacon_ssids_add_popup = NULL;
    ctx->beacon_ssids_add_textarea = NULL;
    ctx->beacon_ssids_keyboard = NULL;
}

static void close_beacon_spam_active_popup(tab_context_t *ctx, bool send_stop)
{
    if (!ctx) return;

    if (send_stop) {
        tab_id_t tab = tab_id_for_ctx(ctx);
        if (!tab_is_internal(tab)) {
            uart_port_t uart_port = uart_port_for_tab(tab);
            transport_write_bytes_tab(tab, uart_port, "stop", 4);
            transport_write_bytes_tab(tab, uart_port, "\r\n", 2);
            ESP_LOGI(TAG, "[%s/Tab] Sent command: stop (Beacon Spam)", tab_transport_name(tab));
        }
    }

    if (ctx->beacon_spam_active_overlay) {
        lv_obj_del(ctx->beacon_spam_active_overlay);
    }
    ctx->beacon_spam_active_overlay = NULL;
    ctx->beacon_spam_active_popup = NULL;
}

static void beacon_spam_rebuild_ssid_grid(tab_context_t *ctx)
{
    if (!ctx || !ctx->beacon_ssids_grid) return;

    lv_obj_clean(ctx->beacon_ssids_grid);

    if (ctx->beacon_spam_ssid_count <= 0) {
        lv_obj_t *empty = lv_label_create(ctx->beacon_ssids_grid);
        lv_label_set_text(empty, "No SSIDs configured.");
        lv_obj_set_style_text_font(empty, &lv_font_montserrat_16, 0);
        lv_obj_set_style_text_color(empty, ui_muted_color(), 0);
        lv_obj_set_width(empty, lv_pct(100));
        lv_label_set_long_mode(empty, LV_LABEL_LONG_WRAP);
        return;
    }

    for (int i = 0; i < ctx->beacon_spam_ssid_count; i++) {
        beacon_spam_ssid_t *entry = &ctx->beacon_spam_ssids[i];

        lv_obj_t *row = lv_obj_create(ctx->beacon_ssids_grid);
        lv_obj_set_size(row, lv_pct(48), LV_SIZE_CONTENT);
        lv_obj_set_style_bg_color(row, ui_card_color(), 0);
        lv_obj_set_style_border_width(row, 1, 0);
        lv_obj_set_style_border_color(row, ui_border_color(), 0);
        lv_obj_set_style_border_opa(row, dark_mode_enabled ? LV_OPA_40 : LV_OPA_80, 0);
        lv_obj_set_style_radius(row, 8, 0);
        lv_obj_set_style_pad_all(row, 10, 0);
        lv_obj_set_style_pad_column(row, 10, 0);
        lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

        lv_obj_t *info = lv_obj_create(row);
        lv_obj_remove_style_all(info);
        lv_obj_set_flex_grow(info, 1);
        lv_obj_set_height(info, LV_SIZE_CONTENT);
        lv_obj_set_flex_flow(info, LV_FLEX_FLOW_COLUMN);
        lv_obj_set_style_pad_row(info, 2, 0);
        lv_obj_clear_flag(info, LV_OBJ_FLAG_SCROLLABLE);

        lv_obj_t *idx_lbl = lv_label_create(info);
        lv_label_set_text_fmt(idx_lbl, "%d", entry->index);
        lv_obj_set_style_text_font(idx_lbl, &lv_font_montserrat_12, 0);
        lv_obj_set_style_text_color(idx_lbl, ui_muted_color(), 0);

        lv_obj_t *ssid_lbl = lv_label_create(info);
        lv_label_set_text(ssid_lbl, entry->ssid);
        lv_obj_set_style_text_font(ssid_lbl, ssid_utf8_font(), 0);
        lv_obj_set_style_text_color(ssid_lbl, ui_text_color(), 0);
        lv_obj_set_width(ssid_lbl, lv_pct(100));
        lv_label_set_long_mode(ssid_lbl, LV_LABEL_LONG_WRAP);

        lv_obj_t *delete_btn = lv_btn_create(row);
        lv_obj_set_size(delete_btn, 54, 44);
        style_danger_button(delete_btn);
        lv_obj_add_event_cb(delete_btn, beacon_ssids_delete_cb, LV_EVENT_CLICKED,
                            (void*)(intptr_t)entry->index);

        lv_obj_t *delete_lbl = lv_label_create(delete_btn);
        lv_label_set_text(delete_lbl, LV_SYMBOL_TRASH);
        lv_obj_set_style_text_font(delete_lbl, &lv_font_montserrat_18, 0);
        lv_obj_set_style_text_color(delete_lbl, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(delete_lbl);
    }
}

static int beacon_spam_query_ssid_list_command(const char *command, char *rx_buffer, size_t rx_size)
{
    if (!command || !rx_buffer || rx_size < 2) return 0;
    if (tab_is_internal(current_tab)) return 0;

    uart_port_t uart_port = uart_port_for_tab(current_tab);
    uart_flush_input(uart_port);
    ESP_LOGI(TAG, "Beacon Spam: sending SSID list command: %s", command);
    uart_send_command_for_tab(command);
    vTaskDelay(pdMS_TO_TICKS(250));

    int total_len = 0;
    int retries = 18;
    int empty_reads = 0;

    while (retries-- > 0 && empty_reads < 4 && total_len < (int)rx_size - 1) {
        int len = transport_read_bytes(uart_port, rx_buffer + total_len,
                                       rx_size - (size_t)total_len - 1U,
                                       pdMS_TO_TICKS(150));
        if (len > 0) {
            total_len += len;
            empty_reads = 0;
        } else {
            empty_reads++;
        }
    }
    rx_buffer[total_len] = '\0';

    ESP_LOGI(TAG, "Beacon Spam: %s response (%d bytes)", command, total_len);
    if (total_len > 0) {
        ESP_LOGI(TAG, "Beacon Spam: raw UART output for %s:\n%s", command, rx_buffer);
    } else {
        ESP_LOGW(TAG, "Beacon Spam: empty UART output for %s", command);
    }
    return total_len;
}

static int beacon_spam_parse_ssid_list_response(tab_context_t *ctx, char *rx_buffer,
                                                bool *unknown_command,
                                                bool *empty_list,
                                                bool *missing_file)
{
    if (unknown_command) *unknown_command = false;
    if (empty_list) *empty_list = false;
    if (missing_file) *missing_file = false;
    if (!ctx || !rx_buffer) return 0;

    int count = 0;
    bool saw_unknown = false;
    bool saw_empty = false;
    bool saw_missing = false;
    int line_no = 0;

    char *line = strtok(rx_buffer, "\n\r");
    while (line != NULL && count < BEACON_SPAM_MAX_SSIDS) {
        line_no++;
        char *raw_line = line;
        ESP_LOGI(TAG, "Beacon Spam parse line %d raw: '%s'", line_no, raw_line);

        while (isspace((unsigned char)*line)) line++;
        if (*line == '\0') {
            ESP_LOGI(TAG, "Beacon Spam parse line %d: skipped (empty after trim)", line_no);
            line = strtok(NULL, "\n\r");
            continue;
        }

        if (strstr(line, "list_ssid") != NULL || strstr(line, "list_ssids") != NULL) {
            ESP_LOGI(TAG, "Beacon Spam parse line %d: skipped (echo/header line)", line_no);
            line = strtok(NULL, "\n\r");
            continue;
        }

        if (strstr(line, "No SSID") != NULL ||
            strstr(line, "SSID list empty") != NULL ||
            strstr(line, "No SSIDs configured") != NULL) {
            saw_empty = true;
            ESP_LOGI(TAG, "Beacon Spam parse line %d: detected empty SSID list marker", line_no);
            line = strtok(NULL, "\n\r");
            continue;
        }

        if (strstr(line, "ssid.txt") != NULL &&
            (strstr(line, "not found") != NULL ||
             strstr(line, "No such file") != NULL ||
             strstr(line, "failed") != NULL ||
             strstr(line, "Failed") != NULL ||
             strstr(line, "cannot open") != NULL ||
             strstr(line, "Cannot open") != NULL)) {
            saw_missing = true;
            ESP_LOGW(TAG, "Beacon Spam parse line %d: detected missing ssid.txt marker", line_no);
            line = strtok(NULL, "\n\r");
            continue;
        }

        if (strstr(line, "Unknown command") != NULL ||
            strstr(line, "unknown command") != NULL ||
            strstr(line, "Invalid command") != NULL ||
            strstr(line, "invalid command") != NULL ||
            strstr(line, "Unknown cmd") != NULL ||
            strstr(line, "unknown cmd") != NULL) {
            saw_unknown = true;
            ESP_LOGW(TAG, "Beacon Spam parse line %d: detected unsupported command marker", line_no);
            line = strtok(NULL, "\n\r");
            continue;
        }

        if (!isdigit((unsigned char)*line)) {
            ESP_LOGI(TAG, "Beacon Spam parse line %d: skipped (does not start with numeric index)", line_no);
            line = strtok(NULL, "\n\r");
            continue;
        }

        char *endptr = NULL;
        long index = strtol(line, &endptr, 10);
        if (index <= 0 || endptr == line) {
            ESP_LOGI(TAG, "Beacon Spam parse line %d: skipped (invalid numeric index)", line_no);
            line = strtok(NULL, "\n\r");
            continue;
        }

        while (*endptr == '.' || *endptr == ')' || *endptr == ':' || *endptr == '-') {
            endptr++;
        }
        while (*endptr && isspace((unsigned char)*endptr)) endptr++;
        if (*endptr == '\0') {
            ESP_LOGI(TAG, "Beacon Spam parse line %d: skipped (index without SSID value)", line_no);
            line = strtok(NULL, "\n\r");
            continue;
        }

        char ssid[BEACON_SPAM_SSID_MAX_LEN + 1];
        snprintf(ssid, sizeof(ssid), "%s", endptr);
        trim_trailing_whitespace(ssid);
        if (ssid[0] == '\0') {
            ESP_LOGI(TAG, "Beacon Spam parse line %d: skipped (SSID empty after trim)", line_no);
            line = strtok(NULL, "\n\r");
            continue;
        }

        size_t ssid_len = strlen(ssid);
        if (ssid_len >= 2 && ssid[0] == '"' && ssid[ssid_len - 1] == '"') {
            memmove(ssid, ssid + 1, ssid_len - 2);
            ssid[ssid_len - 2] = '\0';
        }

        ctx->beacon_spam_ssids[count].index = (int)index;
        snprintf(ctx->beacon_spam_ssids[count].ssid, sizeof(ctx->beacon_spam_ssids[count].ssid), "%s", ssid);
        ESP_LOGI(TAG, "Beacon Spam parse line %d: parsed entry index=%d ssid='%s'",
                 line_no, (int)index, ssid);
        count++;

        line = strtok(NULL, "\n\r");
    }

    ESP_LOGI(TAG, "Beacon Spam parse summary: parsed=%d unknown=%s empty=%s missing_file=%s",
             count,
             saw_unknown ? "yes" : "no",
             saw_empty ? "yes" : "no",
             saw_missing ? "yes" : "no");

    if (unknown_command) *unknown_command = saw_unknown;
    if (empty_list) *empty_list = saw_empty;
    if (missing_file) *missing_file = saw_missing;
    return count;
}

static void beacon_spam_refresh_ssids(tab_context_t *ctx)
{
    if (!ctx || !ctx->beacon_spam_ssids) return;

    ctx->beacon_spam_ssid_count = 0;
    memset(ctx->beacon_spam_ssids, 0, BEACON_SPAM_MAX_SSIDS * sizeof(beacon_spam_ssid_t));

    if (tab_is_internal(current_tab)) {
        if (ctx->beacon_ssids_status_label) {
            lv_label_set_text(ctx->beacon_ssids_status_label, "Beacon Spam is unavailable on INTERNAL tab.");
            lv_obj_set_style_text_color(ctx->beacon_ssids_status_label, COLOR_MATERIAL_RED, 0);
        }
        return;
    }

    static char rx_buffer[4096];
    const char *commands[] = {"list_ssids"};
    const size_t command_count = sizeof(commands) / sizeof(commands[0]);

    bool got_any_response = false;
    bool saw_unknown_only = false;
    bool saw_supported_output = false;
    bool empty_list = false;
    bool missing_file = false;
    int count = 0;

    for (size_t i = 0; i < command_count; i++) {
        ESP_LOGI(TAG, "Beacon Spam: SSID list attempt %d/%d using command '%s'",
                 (int)i + 1, (int)command_count, commands[i]);
        int total_len = beacon_spam_query_ssid_list_command(commands[i], rx_buffer, sizeof(rx_buffer));
        if (total_len <= 0) {
            continue;
        }

        got_any_response = true;

        bool command_unknown = false;
        bool command_empty = false;
        bool command_missing = false;
        int parsed = beacon_spam_parse_ssid_list_response(ctx, rx_buffer,
                                                          &command_unknown,
                                                          &command_empty,
                                                          &command_missing);
        ESP_LOGI(TAG, "Beacon Spam: parse result for '%s' -> parsed=%d unknown=%s empty=%s missing=%s",
                 commands[i],
                 parsed,
                 command_unknown ? "yes" : "no",
                 command_empty ? "yes" : "no",
                 command_missing ? "yes" : "no");
        if (parsed > 0) {
            saw_supported_output = true;
            count = parsed;
            break;
        }

        if (command_unknown) {
            saw_unknown_only = true;
        } else {
            saw_supported_output = true;
        }

        if (command_missing) {
            missing_file = true;
            break;
        }
        if (command_empty) {
            empty_list = true;
            break;
        }
    }

    ctx->beacon_spam_ssid_count = count;
    ESP_LOGI(TAG, "Beacon Spam refresh summary: count=%d got_response=%s unknown_only=%s empty=%s missing_file=%s",
             count,
             got_any_response ? "yes" : "no",
             saw_unknown_only ? "yes" : "no",
             empty_list ? "yes" : "no",
             missing_file ? "yes" : "no");

    if (ctx->beacon_ssids_status_label) {
        if (count > 0) {
            lv_label_set_text_fmt(ctx->beacon_ssids_status_label, "Loaded %d SSID(s)", count);
            lv_obj_set_style_text_color(ctx->beacon_ssids_status_label, COLOR_MATERIAL_GREEN, 0);
        } else if (missing_file) {
            lv_label_set_text(ctx->beacon_ssids_status_label, "Missing /sdcard/lab/ssid.txt on JanOS SD card.");
            lv_obj_set_style_text_color(ctx->beacon_ssids_status_label, COLOR_MATERIAL_RED, 0);
        } else if (saw_unknown_only && !saw_supported_output) {
            lv_label_set_text(ctx->beacon_ssids_status_label, "SSID list command unsupported (list_ssids).");
            lv_obj_set_style_text_color(ctx->beacon_ssids_status_label, COLOR_MATERIAL_RED, 0);
        } else if (!got_any_response) {
            lv_label_set_text(ctx->beacon_ssids_status_label, "No UART response for SSID list command.");
            lv_obj_set_style_text_color(ctx->beacon_ssids_status_label, COLOR_MATERIAL_RED, 0);
        } else if (empty_list) {
            lv_label_set_text(ctx->beacon_ssids_status_label, "No SSIDs in /sdcard/lab/ssid.txt. Add one to begin.");
            lv_obj_set_style_text_color(ctx->beacon_ssids_status_label, COLOR_MATERIAL_AMBER, 0);
        } else {
            lv_label_set_text(ctx->beacon_ssids_status_label, "No SSIDs found. Check list_ssids output format.");
            lv_obj_set_style_text_color(ctx->beacon_ssids_status_label, COLOR_MATERIAL_AMBER, 0);
        }
    }
}

static void beacon_ssids_keyboard_cb(lv_event_t *e)
{
    lv_event_code_t code = lv_event_get_code(e);
    if (code != LV_EVENT_READY && code != LV_EVENT_CANCEL) return;

    tab_context_t *ctx = get_current_ctx();
    if (ctx && ctx->beacon_ssids_keyboard) {
        lv_obj_add_flag(ctx->beacon_ssids_keyboard, LV_OBJ_FLAG_HIDDEN);
    }
}

static void beacon_ssids_textarea_focus_cb(lv_event_t *e)
{
    (void)e;
    tab_context_t *ctx = get_current_ctx();
    if (!ctx || !ctx->beacon_ssids_keyboard || !ctx->beacon_ssids_add_textarea) return;

    lv_keyboard_set_textarea(ctx->beacon_ssids_keyboard, ctx->beacon_ssids_add_textarea);
    lv_obj_clear_flag(ctx->beacon_ssids_keyboard, LV_OBJ_FLAG_HIDDEN);
}

static void beacon_ssids_add_popup_cancel_cb(lv_event_t *e)
{
    (void)e;
    tab_context_t *ctx = get_current_ctx();
    close_beacon_ssids_add_popup(ctx);
}

static void beacon_ssids_add_popup_save_cb(lv_event_t *e)
{
    (void)e;
    tab_context_t *ctx = get_current_ctx();
    if (!ctx || !ctx->beacon_ssids_add_textarea) return;

    char ssid[BEACON_SPAM_SSID_MAX_LEN + 1];
    snprintf(ssid, sizeof(ssid), "%s", lv_textarea_get_text(ctx->beacon_ssids_add_textarea));
    beacon_spam_trim_whitespace(ssid);
    if (ssid[0] == '\0') {
        if (ctx->beacon_ssids_status_label) {
            lv_label_set_text(ctx->beacon_ssids_status_label, "SSID cannot be empty.");
            lv_obj_set_style_text_color(ctx->beacon_ssids_status_label, COLOR_MATERIAL_RED, 0);
        }
        return;
    }

    char escaped[BEACON_SPAM_SSID_MAX_LEN * 2 + 1];
    beacon_spam_escape_quoted_arg(ssid, escaped, sizeof(escaped));

    char cmd[(BEACON_SPAM_SSID_MAX_LEN * 2) + 24];
    snprintf(cmd, sizeof(cmd), "add_ssid \"%s\"", escaped);
    uart_send_command_for_tab(cmd);
    ESP_LOGI(TAG, "Beacon Spam: added SSID '%s'", ssid);

    close_beacon_ssids_add_popup(ctx);
    vTaskDelay(pdMS_TO_TICKS(150));
    beacon_spam_refresh_ssids(ctx);
    beacon_spam_rebuild_ssid_grid(ctx);
}

