// Settings popup variables
static __attribute__((unused)) lv_obj_t *settings_popup_overlay = NULL;
static __attribute__((unused)) lv_obj_t *settings_popup_obj = NULL;

// NVS keys
#define NVS_NAMESPACE "settings"
#define NVS_KEY_RED_TEAM        "red_team"
#define NVS_KEY_SCREEN_TIMEOUT  "scr_timeout"
#define NVS_KEY_SCREEN_BRIGHT   "scr_bright"
#define NVS_KEY_DASHBOARD       "dashboard"
#define NVS_KEY_DARK_MODE       "dark_mode"
#define NVS_KEY_BOOT_SOUND      "boot_sound"
#define NVS_KEY_CLOCK_24H       "clock_24h"
#define NVS_KEY_CLOCK_DST       "clock_dst"
#define NVS_KEY_CLOCK_SHOW      "clock_show"
#define NVS_KEY_SCREEN_LOCK     "scr_lock"
#define NVS_KEY_AUTO_LOCK       "scr_autolock"
#define NVS_KEY_WD_AUTOUP_EN    "wd_au_en"
#define NVS_KEY_WD_AUTOUP_WIGLE "wd_au_wg"
#define NVS_KEY_WD_AUTOUP_WDG   "wd_au_wdg"
#define NVS_KEY_WD_AUTOUP_ARCH  "wd_au_arch"
#define NVS_KEY_WD_AUTOUP_POFF  "wd_au_poff"

// Load Red Team setting from NVS (called on startup)
// Note: Device detection is automatic via ping/pong
static void load_red_team_from_nvs(void)
{
    nvs_handle_t nvs;
    esp_err_t err = nvs_open(NVS_NAMESPACE, NVS_READONLY, &nvs);
    if (err == ESP_OK) {
        // Load red_team setting
        uint8_t red_team = 0;
        err = nvs_get_u8(nvs, NVS_KEY_RED_TEAM, &red_team);
        if (err == ESP_OK) {
            enable_red_team = (red_team != 0);
            ESP_LOGI(TAG, "Loaded Red Team from NVS: %s", enable_red_team ? "Enabled" : "Disabled");
        } else {
            ESP_LOGI(TAG, "No Red Team in NVS, using default: Disabled");
        }

        nvs_close(nvs);
    } else {
        ESP_LOGI(TAG, "NVS not available, using default: Red Team=Disabled");
    }
}

// Save Red Team setting to NVS
static void save_red_team_to_nvs(bool enabled)
{
    nvs_handle_t nvs;
    esp_err_t err = nvs_open(NVS_NAMESPACE, NVS_READWRITE, &nvs);
    if (err == ESP_OK) {
        nvs_set_u8(nvs, NVS_KEY_RED_TEAM, enabled ? 1 : 0);
        nvs_commit(nvs);
        nvs_close(nvs);
        ESP_LOGI(TAG, "Saved Red Team to NVS: %s", enabled ? "Enabled" : "Disabled");
    } else {
        ESP_LOGE(TAG, "Failed to open NVS for writing Red Team: %s", esp_err_to_name(err));
    }
}

// Load wardrive auto-upload (home networks) config from NVS (called on startup)
static void load_wd_autoupload_from_nvs(void)
{
    nvs_handle_t nvs;
    if (nvs_open(NVS_NAMESPACE, NVS_READONLY, &nvs) != ESP_OK) {
        return;
    }
    uint8_t v;
    if (nvs_get_u8(nvs, NVS_KEY_WD_AUTOUP_EN, &v) == ESP_OK)    g_wd_autoupload_enabled = (v != 0);
    if (nvs_get_u8(nvs, NVS_KEY_WD_AUTOUP_WIGLE, &v) == ESP_OK) g_wd_autoupload_wigle   = (v != 0);
    if (nvs_get_u8(nvs, NVS_KEY_WD_AUTOUP_WDG, &v) == ESP_OK)   g_wd_autoupload_wdgwars = (v != 0);
    if (nvs_get_u8(nvs, NVS_KEY_WD_AUTOUP_ARCH, &v) == ESP_OK)  g_wd_autoupload_archive = (v != 0);
    if (nvs_get_u8(nvs, NVS_KEY_WD_AUTOUP_POFF, &v) == ESP_OK)  g_wd_autoupload_poweroff = (v != 0);
    nvs_close(nvs);
    ESP_LOGI(TAG, "Loaded auto-upload cfg: en=%d wigle=%d wdg=%d arch=%d poff=%d",
             g_wd_autoupload_enabled, g_wd_autoupload_wigle,
             g_wd_autoupload_wdgwars, g_wd_autoupload_archive, g_wd_autoupload_poweroff);
}

// Save wardrive auto-upload (home networks) config to NVS
static void save_wd_autoupload_to_nvs(void)
{
    nvs_handle_t nvs;
    if (nvs_open(NVS_NAMESPACE, NVS_READWRITE, &nvs) != ESP_OK) {
        return;
    }
    nvs_set_u8(nvs, NVS_KEY_WD_AUTOUP_EN,    g_wd_autoupload_enabled ? 1 : 0);
    nvs_set_u8(nvs, NVS_KEY_WD_AUTOUP_WIGLE, g_wd_autoupload_wigle ? 1 : 0);
    nvs_set_u8(nvs, NVS_KEY_WD_AUTOUP_WDG,   g_wd_autoupload_wdgwars ? 1 : 0);
    nvs_set_u8(nvs, NVS_KEY_WD_AUTOUP_ARCH,  g_wd_autoupload_archive ? 1 : 0);
    nvs_set_u8(nvs, NVS_KEY_WD_AUTOUP_POFF,  g_wd_autoupload_poweroff ? 1 : 0);
    nvs_commit(nvs);
    nvs_close(nvs);
}

// Load screen settings from NVS (called on startup)
static void load_screen_settings_from_nvs(void)
{
    nvs_handle_t nvs;
    esp_err_t err = nvs_open(NVS_NAMESPACE, NVS_READONLY, &nvs);
    if (err == ESP_OK) {
        // Load screen timeout setting
        uint8_t timeout = 1;
        err = nvs_get_u8(nvs, NVS_KEY_SCREEN_TIMEOUT, &timeout);
        if (err == ESP_OK && timeout <= 4) {
            screen_timeout_setting = timeout;
            ESP_LOGI(TAG, "Loaded Screen Timeout from NVS: %d", screen_timeout_setting);
        } else {
            ESP_LOGI(TAG, "No Screen Timeout in NVS, using default: 30s");
        }

        // Load screen brightness setting
        uint8_t brightness = 80;
        err = nvs_get_u8(nvs, NVS_KEY_SCREEN_BRIGHT, &brightness);
        if (err == ESP_OK && brightness >= 1 && brightness <= 100) {
            screen_brightness_setting = brightness;
            ESP_LOGI(TAG, "Loaded Screen Brightness from NVS: %d%%", screen_brightness_setting);
        } else {
            ESP_LOGI(TAG, "No Screen Brightness in NVS, using default: 80%%");
        }

        uint8_t dash = 1;
        err = nvs_get_u8(nvs, NVS_KEY_DASHBOARD, &dash);
        if (err == ESP_OK) {
            dashboard_enabled = (dash != 0);
            ESP_LOGI(TAG, "Loaded Dashboard from NVS: %s", dashboard_enabled ? "ON" : "OFF");
        } else {
            dashboard_enabled = true;
            ESP_LOGI(TAG, "No Dashboard setting in NVS, using default: ON");
        }

        uint8_t dark_mode = 1;
        err = nvs_get_u8(nvs, NVS_KEY_DARK_MODE, &dark_mode);
        if (err == ESP_OK) {
            dark_mode_enabled = (dark_mode != 0);
            ESP_LOGI(TAG, "Loaded Dark Mode from NVS: %s", dark_mode_enabled ? "ON" : "OFF");
        } else {
            dark_mode_enabled = true;
            ESP_LOGI(TAG, "No Dark Mode setting in NVS, using default: ON");
        }

        uint8_t scr_lock = 1;
        err = nvs_get_u8(nvs, NVS_KEY_SCREEN_LOCK, &scr_lock);
        if (err == ESP_OK) {
            screen_lock_enabled = (scr_lock != 0);
            ESP_LOGI(TAG, "Loaded Screen Lock from NVS: %s", screen_lock_enabled ? "ON" : "OFF");
        } else {
            screen_lock_enabled = true;
            ESP_LOGI(TAG, "No Screen Lock setting in NVS, using default: ON");
        }

        uint8_t auto_lock = 0;
        err = nvs_get_u8(nvs, NVS_KEY_AUTO_LOCK, &auto_lock);
        if (err == ESP_OK) {
            screen_auto_lock_enabled = (auto_lock != 0);
            ESP_LOGI(TAG, "Loaded Auto Lock from NVS: %s", screen_auto_lock_enabled ? "ON" : "OFF");
        } else {
            screen_auto_lock_enabled = false;
            ESP_LOGI(TAG, "No Auto Lock setting in NVS, using default: OFF");
        }

        uint8_t boot_sound = (uint8_t)BOOT_SOUND_MODE_NOKIA;
        err = nvs_get_u8(nvs, NVS_KEY_BOOT_SOUND, &boot_sound);
        if (err == ESP_OK) {
            if (boot_sound <= (uint8_t)BOOT_SOUND_MODE_STAR_WARS) {
                boot_sound_mode = (boot_sound_mode_t)boot_sound;
            } else {
                // Backward compatibility / invalid values fallback:
                // old bool-style ON => Nokia, OFF => OFF.
                boot_sound_mode = (boot_sound == 0) ? BOOT_SOUND_MODE_OFF : BOOT_SOUND_MODE_NOKIA;
            }
            ESP_LOGI(TAG, "Loaded Boot Sound from NVS: %s", boot_sound_mode_name(boot_sound_mode));
        } else {
            boot_sound_mode = BOOT_SOUND_MODE_NOKIA;
            ESP_LOGI(TAG, "No Boot Sound setting in NVS, using default: %s", boot_sound_mode_name(boot_sound_mode));
        }

        nvs_close(nvs);
    } else {
        ESP_LOGI(TAG, "NVS not available, using default screen settings");
    }
}

