        lv_obj_set_style_bg_color(timeout_list, ui_card_color(), 0);
        lv_obj_set_style_border_color(timeout_list, ui_border_color(), 0);
        lv_obj_set_style_text_color(timeout_list, ui_text_color(), 0);
