    lv_obj_set_style_radius(info_btn, 8, 0);
    lv_obj_add_event_cb(info_btn, ota_info_btn_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t *info_lbl = lv_label_create(info_btn);
    lv_label_set_text(info_lbl, "Info");
