    lv_obj_set_style_bg_opa(ctx->sd_admin_leave_overlay, LV_OPA_50, 0);
    lv_obj_clear_flag(ctx->sd_admin_leave_overlay, LV_OBJ_FLAG_SCROLLABLE);
